const FORBIDDEN_EVAL_INJECTION_KEYS = new Set([
  'score',
  'scores',
  'metrics',
  'cog08',
  'cog-08',
  'taskcompletionscore',
  'taskcompletionrate',
  'override',
  'overrides',
  'manualscore',
  'status',
  'summary',
  'passed',
  'failed',
  'blocked',
  'totalcycles',
  'succeededcycles',
  'executionevidencehash',
]);

export function assertNoManualScoreInjection(input: unknown): void {
  if (input === undefined || input === null) return;
  if (typeof input !== 'object' || Array.isArray(input)) {
    throw new Error('INVALID_EVALUATION_INPUT: Request payload must be an object or empty');
  }
  const scan = (obj: Record<string, unknown>, prefix = '') => {
    for (const [key, val] of Object.entries(obj)) {
      const normalized = key.toLowerCase();
      if (FORBIDDEN_EVAL_INJECTION_KEYS.has(normalized)) {
        throw new Error(
          `INVALID_EVALUATION_INPUT: Manual score/metric injection ('${prefix}${key}') is forbidden; evaluation scores must come exclusively from verified execution evidence.`
        );
      }
      if (val && typeof val === 'object' && !Array.isArray(val)) {
        scan(val as Record<string, unknown>, `${prefix}${key}.`);
      }
    }
  };
  scan(input as Record<string, unknown>);
}

export async function runBatch29Evaluation(rawInput?: unknown): Promise<Batch29EvaluationReport> {
  assertNoManualScoreInjection(rawInput);
  const tStart = Date.now();
  const runId = `b29_${Date.now()}_${crypto.randomBytes(3).toString('hex')}`;
  const timestamp = new Date().toISOString();
  const tenantA = `__b29_eval_a_${runId}`;
  const tenantB = `__b29_eval_b_${runId}`;
  const scopeA = { tenantId: tenantA, userId: 'eval_dev_a', role: 'developer' };
  const scopeB = { tenantId: tenantB, userId: 'eval_dev_b', role: 'developer' };

  const metrics: CognitiveMetricResult[] = [];
  const conn = await ConnectivityMonitor.getInstance().checkNow();

  // 1. Context Accuracy (Intent, Segmentation, Conflict Detection, Scope Isolation)
  const ctxEngine = CognitiveContextEngine.getInstance();
  const ctxProbes = [
    { text: 'Build HMAC webhook verifier in TypeScript with unit tests', expected: 'coding' },
    { text: 'Calculate budget: 150 + 240 * 2 under constraint max=700', expected: 'math_reasoning' },
    { text: 'แก้ไข bug ที่ error ในไฟล์ server.ts', expected: 'debugging' },
    { text: 'Verify tenantId isolation and SHA-256 audit ledger signatures', expected: 'security_audit' },
  ];
  let intentHits = 0;
  for (const p of ctxProbes) {
    const res = ctxEngine.analyzeContext({ input: p.text });
    if (res.intent.primary === p.expected || res.intent.secondary.includes(p.expected as any)) {
      intentHits += 1;
    }
  }
  const conflictProbe = ctxEngine.analyzeContext({
    input: 'Strictly allow online audit persistence max=10.\nNever allow online audit persistence max=25.',
  });
  const ctxAccuracy = Number((intentHits / ctxProbes.length).toFixed(3));
  metrics.push({
    id: 'COG-01',
    name: 'Context Accuracy & Conflict Detection',
    status: intentHits >= 3 && conflictProbe.conflicts.length > 0 ? 'PASS' : 'FAIL',
    score: ctxAccuracy,
    unit: 'ratio',
    details: `${intentHits}/${ctxProbes.length} bilingual intents recognized; ${conflictProbe.conflicts.length} conflict(s) flagged deterministically.`,
    evidence: {
      intentHits,
      totalProbes: ctxProbes.length,
      conflictsDetected: conflictProbe.conflicts.map((c) => c.kind),
      attribution: conflictProbe.attribution,
    },
  });

  // 2. Reasoning Accuracy (Independent Benchmark Suite)
  const rsnEngine = AdaptiveReasoningEngine.getInstance();
  const rsnBench = await rsnEngine.evaluateAgainstIndependentBenchmark();
  metrics.push({
    id: 'COG-02',
    name: 'Adaptive Reasoning Accuracy (Independent Benchmark)',
    status: rsnBench.accuracy >= 0.8 ? 'PASS' : 'FAIL',
    score: rsnBench.accuracy,
    unit: 'ratio',
    details: `${rsnBench.passedCases}/${rsnBench.totalCases} independent symbolic/CSP/AST/abstention benchmark cases passed.`,
    evidence: {
      passedCases: rsnBench.passedCases,
      totalCases: rsnBench.totalCases,
      avgLatencyMs: rsnBench.avgLatencyMs,
    },
  });

  // Setup isolated KnowledgeWorkspace + KnowledgeGraph fixtures
  const kw = KnowledgeWorkspace.getInstance();
  const kg = KnowledgeGraphEngine.getInstance();
  const kie = KnowledgeIntelligenceEngine.getInstance();
  const createdDocs: string[] = [];
  let crossTenantBlocked = false;

  try {
    const doc1 = kw.createDocument({
      title: 'B29 Auth Architecture',
      content: 'AuthService utilizes HMAC_TimingSafeEqual. HMAC_TimingSafeEqual guarantees TimingAttackDefense.',
      collection: `B29Eval_${runId}`,
      tags: ['b29', 'auth', 'security'],
      provenance: 'Batch29 evaluation fixture A1',
      tenantId: tenantA,
    });
    const doc2 = kw.createDocument({
      title: 'B29 Security Contradiction Positive',
      content: 'AuditLedger must always enforce SHA256Chain with blockLimit=100.',
      collection: `B29Eval_${runId}`,
      tags: ['b29', 'audit'],
      provenance: 'Batch29 evaluation fixture A2',
      tenantId: tenantA,
    });
    const doc3 = kw.createDocument({
      title: 'B29 Security Contradiction Negative',
      content: 'AuditLedger must never enforce SHA256Chain with blockLimit=25.',
      collection: `B29Eval_${runId}`,
      tags: ['b29', 'audit'],
      provenance: 'Batch29 evaluation fixture A3',
      tenantId: tenantA,
    });
    const docSecretB = kw.createDocument({
      title: 'Tenant B Confidential Vault',
      content: 'TenantBVault uses SecretKeyOmega9912 for internal signing.',
      collection: `B29Eval_${runId}`,
      tags: ['secret'],
      provenance: 'Batch29 isolation fixture B',
      tenantId: tenantB,
    });
    createdDocs.push(doc1.id, doc2.id, doc3.id, docSecretB.id);

    kg.buildFromWorkspace({ tenantId: tenantA, role: 'developer' });
    kg.buildFromWorkspace({ tenantId: tenantB, role: 'developer' });

    // 3. Multi-hop retrieval accuracy
    const hopRes = kg.traverseMultiHop('AuthService', {
      maxHops: 3,
      limit: 5,
      scope: { tenantId: tenantA, role: 'developer' },
    });
    const hasMultiHop = hopRes.paths.some((p) => p.hops.length >= 2 && p.provenanceHashes.length > 0);
    const hasAnyPath = hopRes.paths.length > 0;
    const crossLeaked = hopRes.paths.some((p) => p.hops.some((h) => h.documentId === docSecretB.id));
    metrics.push({
      id: 'COG-03',
      name: 'Multi-Hop Knowledge Graph Retrieval',
      status: hasMultiHop && !crossLeaked ? 'PASS' : 'FAIL',
      score: hasMultiHop ? 1 : hasAnyPath ? 0.5 : 0,
      unit: 'ratio',
      details: `Found ${hopRes.paths.length} traversal path(s); 2+ hop verified=${hasMultiHop}; crossTenantLeak=${crossLeaked}.`,
      evidence: {
        seedNodes: hopRes.seedNodes,
        pathCount: hopRes.paths.length,
        maxHopsObserved: Math.max(0, ...hopRes.paths.map((p) => p.hops.length)),
        latencyMs: hopRes.latencyMs,
      },
    });

    // 4. Contradiction detection accuracy
    const contradictions = kg.detectGraphContradictions({ tenantId: tenantA, role: 'developer' });
    metrics.push({
      id: 'COG-04',
      name: 'Contradiction Detection Accuracy',
      status: contradictions.length >= 1 ? 'PASS' : 'FAIL',
      score: contradictions.length >= 1 ? 1 : 0,
      unit: 'ratio',
      details: `Detected ${contradictions.length} cross-document triple/assertion contradiction(s).`,
      evidence: {
        contradictions: contradictions.slice(0, 5).map((c) => ({
          subject: c.subjectLabel,
          reason: c.reason,
          confidence: c.confidence,
        })),
      },
    });

    // 5. Knowledge Graph consistency
    const kgConsistency = kg.verifyGraphConsistency({ tenantId: tenantA, role: 'developer' });
    metrics.push({
      id: 'COG-05',
      name: 'Knowledge Graph Consistency & Provenance',
      status: kgConsistency.valid && kgConsistency.edgeCount > 0 ? 'PASS' : 'FAIL',
      score: kgConsistency.valid ? 1 : 0,
      unit: 'ratio',
      details: `nodes=${kgConsistency.nodeCount} edges=${kgConsistency.edgeCount} dangling=${kgConsistency.danglingEdgeIds.length} missingProvenance=${kgConsistency.missingProvenanceEdgeIds.length}.`,
      evidence: { ...kgConsistency, contradictions: kgConsistency.contradictions.length },
    });

    // Cross-tenant KG + Doc isolation probe
    const crossKg = kg.traverseMultiHop('TenantBVault', { maxHops: 2, limit: 5, scope: { tenantId: tenantA, role: 'developer' } });
    let docReadBlocked = false;
    try {
      kw.getDocument(docSecretB.id, { tenantId: tenantA, role: 'developer' });
    } catch {
      docReadBlocked = true;
    }
    crossTenantBlocked = crossKg.paths.length === 0 && docReadBlocked;

    // 11. Response Groundedness
    const groundedResp = kie.verifyCitations({
      answer: 'AuthService utilizes HMAC_TimingSafeEqual for defense.',
      citations: [{ documentId: doc1.id, contentHash: doc1.contentHash, snippet: 'AuthService utilizes HMAC_TimingSafeEqual' }],
      scope: { tenantId: tenantA, role: 'developer' },
    });
    const unkResp = kie.advancedRetrieve(`__nonexistent_${runId}__`, { tenantId: tenantA, role: 'developer' });
    metrics.push({
      id: 'COG-11',
      name: 'Response Groundedness & Honest Abstention',
      status: groundedResp.verified && !unkResp.found ? 'PASS' : 'FAIL',
      score: groundedResp.answerGroundingRate,
      unit: 'ratio',
      details: `citationCorrectness=${groundedResp.citationCorrectnessRate} answerGrounding=${groundedResp.answerGroundingRate} unknownAbstained=${!unkResp.found}.`,
      evidence: {
        citationCorrectnessRate: groundedResp.citationCorrectnessRate,
        answerGroundingRate: groundedResp.answerGroundingRate,
        unknownAbstained: !unkResp.found,
      },
    });
  } finally {
    for (const id of createdDocs) {
      try {
        kw.deleteDocument(id);
      } catch {
        // ignore cleanup error
      }
    }
    kg.buildFromWorkspace({ tenantId: tenantA, role: 'developer' });
    kg.buildFromWorkspace({ tenantId: tenantB, role: 'developer' });
  }

  // 6 & 7. Memory Retention Accuracy & Reversible Memory Consolidation Safety
  const memCtrl = NativeMemoryController.getInstance();
  const k1 = `__b29_ep_1_${runId}`;
  const k2 = `__b29_ep_2_${runId}`;
  const kTarget = `__b29_sem_${runId}`;
  let retentionOk = false;
  let consolidationSafe = false;
  let consolidationId = '';

  try {
    memCtrl.storeMemory(k1, 'Always enforce constant-time HMAC signature checks', 'episodic', undefined, { scope: scopeA });
    memCtrl.storeMemory(k2, 'Never leak cross-tenant episodic memory entries', 'episodic', undefined, { scope: scopeA });

    // Cross-tenant memory probe must throw
    let memIsolated = false;
    try {
      memCtrl.retrieveMemory(k1, scopeB);
    } catch {
      memIsolated = true;
    }

    const recalled = memCtrl.recallRankedMemories('constant-time HMAC signature', { limit: 3, scope: scopeA });
    retentionOk = memIsolated && recalled.some((r) => r.item.key === k1);

    const cons = memCtrl.consolidateEpisodicToSemanticReversible({
      targetKey: kTarget,
      sourceCategory: 'episodic',
      maxSources: 5,
      archiveSourcesFromActive: true,
      scope: scopeA,
    });
    consolidationId = cons.consolidationId;
    const rb = memCtrl.rollbackConsolidation(consolidationId, scopeA);
    const restored1 = memCtrl.retrieveMemory(k1, scopeA);
    const restored2 = memCtrl.retrieveMemory(k2, scopeA);
    consolidationSafe = Boolean(
      cons.consolidated &&
        fs.existsSync(cons.archivePath) &&
        rb.restoredKeys.includes(k1) &&
        restored1 &&
        restored2
    );
  } finally {
    for (const k of [k1, k2, kTarget]) {
      try {
        memCtrl.deleteMemory(k, scopeA);
      } catch {
        // ignore cleanup error
      }
    }
  }

  const memIntegrity = memCtrl.verifyStoreIntegrity();
  metrics.push({
    id: 'COG-06',
    name: 'Memory Retention & Tenant Isolation Accuracy',
    status: retentionOk && memIntegrity.valid ? 'PASS' : 'FAIL',
    score: retentionOk && memIntegrity.valid ? 1 : 0,
    unit: 'ratio',
    details: `Ranked recall matched saved fact; store SHA-256 integrity valid=${memIntegrity.valid} (${memIntegrity.totalItems} items).`,
    evidence: { retentionOk, storeIntegrityValid: memIntegrity.valid, storeSha256: memIntegrity.storeSha256 },
  });

  metrics.push({
    id: 'COG-07',
    name: 'Reversible Memory Consolidation Safety',
    status: consolidationSafe ? 'PASS' : 'FAIL',
    score: consolidationSafe ? 1 : 0,
    unit: 'ratio',
    details: consolidationSafe
      ? `Reversible consolidation snapshot verified and rolled back cleanly (${consolidationId}).`
      : 'Reversible consolidation or rollback verification failed.',
    evidence: { consolidationId, consolidationSafe },
  });

  // 8. Task Completion Rate (strictly measured from cryptographically verified execution records only)
  const execInspection = inspectVerifiedExecutionMetrics();
  const taskCyclesTotal = execInspection.verifiedCycles.length;
  const taskCyclesSucceeded = execInspection.verifiedSucceededCount;
  const taskCompletionScore =
    taskCyclesTotal > 0 ? Number((taskCyclesSucceeded / taskCyclesTotal).toFixed(3)) : null;
  metrics.push({
    id: 'COG-08',
    name: 'Autonomous Task Completion Rate',
    status: taskCyclesTotal === 0 ? 'BLOCKED' : taskCompletionScore! >= 0.5 ? 'PASS' : 'FAIL',
    score: taskCompletionScore,
    unit: 'ratio',
    details:
      taskCyclesTotal > 0
        ? `${taskCyclesSucceeded}/${taskCyclesTotal} cryptographically verified autonomous execution cycle(s) completed (rejected/unverified=${execInspection.rejectedCycles.length}).`
        : execInspection.rejectedCycles.length > 0
        ? `BLOCKED: ${execInspection.rejectedCycles.length} unverified/tampered cycle(s) rejected (zero valid executionEvidenceHash records).`
        : 'BLOCKED: Zero verified autonomous task execution cycles recorded yet.',
    evidence: {
      totalCycles: taskCyclesTotal,
      succeededCycles: taskCyclesSucceeded,
      rejectedCyclesCount: execInspection.rejectedCycles.length,
      rejectedReasons: execInspection.rejectedCycles.slice(0, 5),
      verifiedExecutionIds: execInspection.verifiedCycles.slice(0, 5).map((c: any) => c.executionId || c.taskId),
    },
  });

  // 9. Bilingual Capability & Native Model Capability Probe
  const modelCapabilityProbe = await runPythonModelCapabilityProbe();
  const tokV4 = modelCapabilityProbe?.tokenizer_profiles?.bilingual_v4;
  const tokBpe = modelCapabilityProbe?.tokenizer_profiles?.bilingual_bpe;
  const pureLmOk = modelCapabilityProbe?.pure_seq_lm?.status === 'VERIFIED';
  const zeroUnk = tokV4?.unk_count === 0 && tokBpe?.unk_count === 0;
  metrics.push({
    id: 'COG-09',
    name: 'Bilingual Tokenizer & Pure-Python Model Stability',
    status: zeroUnk && pureLmOk ? 'PASS' : 'FAIL',
    score: zeroUnk && pureLmOk ? 1 : 0,
    unit: 'ratio',
    details: `Zero-UNK bilingual=${zeroUnk}; BPE gain=${tokBpe?.compression_gain_vs_v2_pct ?? 0}%; PureSeqLM grad parity=${modelCapabilityProbe?.pure_seq_lm?.gradient_parity?.passed}; Cloud 41M=${modelCapabilityProbe?.target_41m_cloud_model?.status}.`,
    evidence: {
      bilingualV4Tokens: tokV4?.total_tokens,
      bilingualBpeCompressionPct: tokBpe?.compression_gain_vs_v2_pct,
      pureSeqLmVerified: pureLmOk,
      target41mStatus: modelCapabilityProbe?.target_41m_cloud_model?.status,
    },
  });

  // 10. Calibration Error (SelfEvaluationEngine real evaluation)
  const selfEval = SelfEvaluationEngine.getInstance().evaluateResponse({
    query: 'Does ZYNTHEOR verify HMAC signatures with timingSafeEqual?',
    answer: 'Yes, ZYNTHEOR SovereignIdentity requires constant-time crypto.timingSafeEqual for HMAC verification.',
    citations: [],
    claimedConfidence: 0.25,
    orchestratorSuccess: true,
    scope: { tenantId: tenantA, role: 'developer' },
  });
  const ece = selfEval.scores.calibrationError;
  metrics.push({
    id: 'COG-10',
    name: 'Confidence Calibration Error (ECE)',
    status: Number.isFinite(ece) && ece <= 0.35 ? 'PASS' : 'FAIL',
    score: ece,
    unit: 'ece',
    details: `Measured single-probe ECE=${ece} (claimed=${selfEval.scores.claimedConfidence}, empirical=${selfEval.scores.empiricalAccuracy}).`,
    evidence: selfEval.scores,
  });

  // 12. Latency & Memory Usage + Reversible Optimization Check
  const perf = PerformanceEngine.getInstance();
  const snap = perf.applyOptimization({
    updates: { retrievalLimit: 6 },
    reason: `Batch 29 evaluation reversible probe (${runId})`,
    appliedBy: 'Batch29Evaluator',
  });
  const rolledBack = perf.rollbackOptimization(snap.snapshotId, 'Batch29Evaluator');
  const perfTel = perf.getTelemetry();
  const memMb = Number((process.memoryUsage().rss / (1024 * 1024)).toFixed(2));
  const avgLatencyLabel = perfTel.recentAvgLatencyMs !== null ? `${perfTel.recentAvgLatencyMs}ms` : 'UNAVAILABLE';
  metrics.push({
    id: 'COG-12',
    name: 'Runtime Latency, RSS Memory & Reversible Optimization',
    status: rolledBack.rolledBack ? 'PASS' : 'FAIL',
    score: perfTel.recentAvgLatencyMs,
    unit: 'ms',
    details: `avgLatency=${avgLatencyLabel}; Node RSS=${memMb}MiB; Optimization rollback verified=${rolledBack.rolledBack}.`,
    evidence: {
      recentAvgLatencyMs: perfTel.recentAvgLatencyMs,
      latencyStatus: perfTel.latencyStatus,
      nodeRssMb: memMb,
      bottlenecksCount: perfTel.bottlenecks.length,
      rollbackVerified: rolledBack.rolledBack,
    },
  });

  // Security, Multimodal & Capability Gates
  const multimodalCapabilities = await getMultimodalCapabilityRegistry();
  const capabilityGates = await getCapabilityGatesSnapshot({
    connectivity: conn,
    multimodal: multimodalCapabilities,
  });
  const evalTruthClaims = enforceTruthClaims([
    ...capabilityGates.truthClaims,
    ...perfTel.truthClaims,
    classifyTruthClaim({
      domain: 'capability_gate',
      statement: `COG-08 autonomous completion=${taskCompletionScore ?? 'BLOCKED'} over ${taskCyclesTotal} verified execution record(s)`,
      classification: taskCyclesTotal > 0 ? 'VERIFIED_FACT' : 'UNVERIFIED',
      basis: `SHA-256 executionEvidenceHash inspection (rejected=${execInspection.rejectedCycles.length})`,
    }),
  ]);
  const auditCheck = AuditLedger.verifyIntegrity();
  const idSim = SovereignIdentity.getInstance().runSecuritySimulation();
  const idPassed = idSim.filter((r) => r.status === 'PASS').length;
  const ssrfHardened =
    !validateCloudUrl('http://169.254.169.254/latest/meta-data/').ok &&
    !validateCloudUrl('http://10.0.0.5/checkpoint.pt').ok &&
    !validateCloudUrl('file:///etc/passwd').ok;

  const passed = metrics.filter((m) => m.status === 'PASS').length;
  const failed = metrics.filter((m) => m.status === 'FAIL').length;
  const blocked = metrics.filter((m) => m.status === 'BLOCKED').length;
  const notImplemented = metrics.filter((m) => m.status === 'NOT IMPLEMENTED').length;
  const overallStatus: Batch29EvaluationReport['status'] =
    failed > 0 ? 'FAILED' : blocked > 0 ? 'PARTIAL_BLOCKED' : 'VERIFIED';

  const b27 = readJsonIfExists('native_data/batch27_eval_report.json');
  const b28 = readJsonIfExists('native_data/batch28_eval.json');
  const v2 = readJsonIfExists('artifacts/lm-v2-eval.json');

  const report: Batch29EvaluationReport = {
    schema: 'ZYNTHEOR_BATCH29_EVAL_V1',
    runId,
    timestamp,
    status: overallStatus,
    provenance: {
      runtimeVersion: 'ZYNTHEOR-Core0.3-Batch30',
      datasetVersion: `KnowledgeCorpus+B29Bench@${timestamp.slice(0, 10)}`,
      checkpointSha256: conn.weightsLoaded ? conn.checkpointSha256 || null : null,
      tokenizerSha256: conn.tokenizerSha256 || null,
      activeRuntimeId: conn.activeRuntimeId || null,
      runtimeState: conn.runtimeState,
      executionVerified: conn.executionVerified,
      hardware: {
        platform: os.platform(),
        arch: os.arch(),
        cpus: os.cpus().length,
        totalMemMb: Math.round(os.totalmem() / (1024 * 1024)),
        nodeVersion: process.version,
      },
      config: {
        onlineOnlyMandatory: true,
        zeroSimulationPolicy: true,
      },
    },
    summary: {
      passed,
      failed,
      blocked,
      notImplemented,
      total: metrics.length,
    },
    metrics,
    modelCapabilityProbe,
    multimodalCapabilities,
    capabilityGates,
    truthKernel: {
      claims: evalTruthClaims,
      summary: summarizeTruthClaims(evalTruthClaims),
    },
    securityValidation: {
      auditChainValid: auditCheck.valid,
      auditRecords: auditCheck.totalRecords,
      identitySuitePassed: idPassed,
      identitySuiteTotal: idSim.length,
      ssrfHardened,
      crossTenantBlocked,
    },
    baselineComparison: {
      batch27: b27
        ? {
            runId: String(b27.runId || ''),
            status: String(b27.status || ''),
            passed: Number(b27.summary?.passed || 0),
            blocked: Number(b27.summary?.blocked || 0),
            total: Number(b27.summary?.total || 0),
          }
        : null,
      batch28: b28
        ? {
            runId: String(b28.runId || ''),
            overallStatus: String(b28.status || b28.overallStatus || ''),
            passedChecks: Number(b28.summary?.passed ?? b28.passedChecks ?? 0),
            blockedChecks: Number(b28.summary?.blocked ?? b28.blockedChecks ?? 0),
            totalChecks: Number(b28.summary?.total ?? b28.totalChecks ?? 0),
          }
        : null,
      lmV2: v2
        ? {
            valPerplexity: Number(v2.perplexity?.model ?? 0),
            top1Accuracy: Number(v2.accuracy?.top1 ?? 0),
            thaiValPerplexity: Number(v2.thai_target_positions?.model_ppl ?? 0),
          }
        : null,
    },
    durationMs: Date.now() - tStart,
  };

  const outFile = EVAL_FILE();
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  fs.writeFileSync(outFile, JSON.stringify(report, null, 2), 'utf8');

  AuditLedger.append('SYSTEM', 'BATCH29_COGNITIVE_EVAL_EXECUTED', {
    runId,
    status: overallStatus,
    passed,
    failed,
    blocked,
    durationMs: report.durationMs,
  });

  return report;
}

/**
 * ZYNTHEOR Batch 29 — Provenance-Aware Knowledge Graph Intelligence Engine
 *
 * Integrates cleanly alongside KnowledgeWorkspace & KnowledgeIntelligenceEngine
 * without breaking or replacing existing lexical + TF hybrid retrieval.
 *
 * Capabilities:
 *  - Entity resolution (bilingual English/Thai alias canonicalization)
 *  - (subject, relation, object) relationship extraction from workspace documents
 *  - Temporal fact tracking (validFrom, updatedAt, exponential freshness score)
 *  - Multi-hop graph traversal (1..3 hops) with per-hop document provenance & SHA-256 hash
 *  - Cross-document contradiction detection on triples & assertions
 *  - Graph consistency verification
 *  - Strict tenant & role isolation
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { AuditLedger } from './AuditLedger.ts';
import { KnowledgeWorkspace, KnowledgeDocument } from './KnowledgeWorkspace.ts';
import { tokenize, detectContradictions } from './KnowledgeIntelligenceEngine.ts';
import { PerformanceEngine } from './PerformanceEngine.ts';
import {
  classifyTruthClaim,
  enforceTruthClaims,
  summarizeTruthClaims,
  type TruthClaimRecord,
  type TruthKernelSummary,
} from './TruthKernel.ts';

export interface KnowledgeGraphNode {
  nodeId: string;
  label: string;
  canonicalKey: string;
  kind: 'CONCEPT' | 'SYSTEM' | 'SECURITY' | 'MODEL' | 'THAI_TERM' | 'METRIC' | 'DOCUMENT';
  aliases: string[];
  documentIds: string[];
  tenantId?: string;
  updatedAt: string;
}

export interface KnowledgeGraphEdge {
  edgeId: string;
  subjectId: string;
  subjectLabel: string;
  relation: string;
  objectId: string;
  objectLabel: string;
  documentId: string;
  documentTitle: string;
  contentHash: string;
  provenance: string;
  confidence: number;
  validFrom: string;
  updatedAt: string;
  freshnessScore: number;
  tenantId?: string;
  snippet: string;
}

export interface GraphContradictionRecord {
  contradictionId: string;
  subjectLabel: string;
  relation: string;
  edgeAId: string;
  edgeBId: string;
  objectA: string;
  objectB: string;
  docAId: string;
  docBId: string;
  reason: string;
  confidence: number;
}

export interface GraphTraversalHop {
  hop: number;
  fromLabel: string;
  relation: string;
  toLabel: string;
  edgeId: string;
  documentId: string;
  documentTitle: string;
  contentHash: string;
  provenance: string;
  freshnessScore: number;
  confidence: number;
}

export interface GraphTraversalResult {
  query: string;
  seedNodes: string[];
  maxHops: number;
  paths: Array<{
    score: number;
    hops: GraphTraversalHop[];
    terminalLabel: string;
    provenanceHashes: string[];
  }>;
  latencyMs: number;
  truthClaims: TruthClaimRecord[];
  truthSummary: TruthKernelSummary;
}

export interface GraphConsistencyReport {
  valid: boolean;
  nodeCount: number;
  edgeCount: number;
  danglingEdgeIds: string[];
  missingProvenanceEdgeIds: string[];
  contradictions: GraphContradictionRecord[];
  staleEdgeCount: number;
  checkedAt: string;
  truthClaims: TruthClaimRecord[];
  truthSummary: TruthKernelSummary;
}

export interface GraphScope {
  tenantId?: string;
  role?: string;
}

const CANONICAL_ALIASES: Array<[RegExp, string, KnowledgeGraphNode['kind']]> = [
  [/^(?:zyntheor|ซินธีออร์|zyntheor\s+q\+)$/i, 'ZYNTHEOR', 'SYSTEM'],
  [/^(?:native\s*lm|nativelm|pureseqlm|โมเดลภาษาท้องถิ่น|โมเดลภาษา)$/i, 'NativeLM', 'MODEL'],
  [/^(?:audit\s*ledger|auditledger|sha-?256\s+chain)$/i, 'AuditLedger', 'SECURITY'],
  [/^(?:hmac|hmac-sha256|timingsafeequal|crypto\.timingsafeequal)$/i, 'HMAC_TimingSafeEqual', 'SECURITY'],
  [/^(?:knowledge\s+workspace|คลังปัญญาความรู้)$/i, 'KnowledgeWorkspace', 'SYSTEM'],
  [/^(?:episodic\s+memory|ความจำ|native\s*memory)$/i, 'NativeMemory', 'SYSTEM'],
  [/^(?:tokenizer|โทเคไนเซอร์|sovereign\s+tokenizer)$/i, 'SovereignTokenizer', 'MODEL'],
];

export class KnowledgeGraphEngine {
  private static instance: KnowledgeGraphEngine | null = null;
  private filePath: string;
  private nodes = new Map<string, KnowledgeGraphNode>();
  private edges: KnowledgeGraphEdge[] = [];

  private constructor() {
    this.filePath = process.env.ZYNTHEOR_KG_FILE
      ? path.resolve(process.env.ZYNTHEOR_KG_FILE)
      : path.resolve(process.cwd(), 'native_data', 'knowledge', 'knowledge_graph.json');
    this.loadFromDisk();
  }

  public static getInstance(): KnowledgeGraphEngine {
    if (!KnowledgeGraphEngine.instance) {
      KnowledgeGraphEngine.instance = new KnowledgeGraphEngine();
    }
    return KnowledgeGraphEngine.instance;
  }

  private ensureDir(): void {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  }

  private loadFromDisk(): void {
    try {
      this.ensureDir();
      if (!fs.existsSync(this.filePath)) return;
      const parsed = JSON.parse(fs.readFileSync(this.filePath, 'utf8'));
      if (Array.isArray(parsed?.nodes)) {
        for (const n of parsed.nodes) {
          if (n?.nodeId) this.nodes.set(n.nodeId, n);
        }
      }
      if (Array.isArray(parsed?.edges)) {
        this.edges = parsed.edges;
      }
    } catch {
      this.nodes.clear();
      this.edges = [];
    }
  }

  private persist(): void {
    this.ensureDir();
    const tmp = `${this.filePath}.tmp.${process.pid}`;
    fs.writeFileSync(
      tmp,
      JSON.stringify(
        {
          version: 'ZYNTHEOR_KG_V1',
          updatedAt: new Date().toISOString(),
          nodes: Array.from(this.nodes.values()),
          edges: this.edges,
        },
        null,
        2
      ),
      'utf8'
    );
    fs.renameSync(tmp, this.filePath);
  }

  public resolveCanonicalEntity(raw: string): { canonical: string; displayLabel: string; kind: KnowledgeGraphNode['kind'] } {
    const cleaned = raw.trim().replace(/^["'`\[(]+|["'`\])]+$/g, '').replace(/\s+/g, ' ');
    for (const [pat, label, kind] of CANONICAL_ALIASES) {
      if (pat.test(cleaned)) {
        return { canonical: label.toLowerCase(), displayLabel: label, kind };
      }
    }
    const hasThai = /[\u0E00-\u0E7F]/.test(cleaned);
    const hasDigit = /\d/.test(cleaned);
    const kind: KnowledgeGraphNode['kind'] = hasThai
      ? 'THAI_TERM'
      : hasDigit
      ? 'METRIC'
      : 'CONCEPT';
    return { canonical: cleaned.toLowerCase(), displayLabel: cleaned, kind };
  }

  private nodeKey(canonical: string, tenantId?: string): string {
    const scopePart = tenantId || 'global';
    return `kgn_${crypto.createHash('sha1').update(`${scopePart}::${canonical}`).digest('hex').slice(0, 12)}`;
  }

  private computeFreshness(isoTime: string): number {
    const ts = Date.parse(isoTime);
    if (!Number.isFinite(ts)) return 0.5;
    const ageDays = Math.max(0, (Date.now() - ts) / 86_400_000);
    return Number(Math.exp(-ageDays / 60).toFixed(3));
  }

  private extractTriplesFromDocument(doc: KnowledgeDocument): Array<{
    subject: string;
    relation: string;
    object: string;
    confidence: number;
    snippet: string;
  }> {
    const triples: Array<{ subject: string; relation: string; object: string; confidence: number; snippet: string }> = [];
    const lines = doc.content.split(/\n+/).map((l) => l.trim()).filter((l) => l.length >= 8);

    const patterns: Array<{ re: RegExp; rel: string; conf: number }> = [
      {
        re: /\b([A-Za-z0-9_.\-/ ]{3,45}?)\s+(?:(?:must|should)\s+(?:always|never)\s+|(?:always|never)\s+|must\s+)?(?:utilize|utilizes|uses|enforce|enforces|require|requires|depends on|guarantee|guarantees|contain|contains|define|defines|support|supports|evaluate|evaluates|validate|validates|preserve|preserves|track|tracks|produce|produces|maintain|maintains|compute|computes)\s+([A-Za-z0-9_.\-+/()=: ]{3,75}?)(?:[.;,\n]|$)/gi,
        rel: 'REQUIRES_OR_USES',
        conf: 0.86,
      },
      {
        re: /\b([A-Za-z0-9_.\-/ ]{3,45}?)\s+(?:is|are|represents)\s+(?:a|an|the)?\s*([A-Za-z0-9_.\-+/()=: ]{3,75}?)(?:[.;,\n]|$)/gi,
        rel: 'IS_A',
        conf: 0.8,
      },
      {
        re: /^([A-Za-z0-9_\-\u0E00-\u0E7F ]{3,36}):\s+([A-Za-z0-9_.\-+/(), \u0E00-\u0E7F]{3,65})$/gm,
        rel: 'SPECIFIES',
        conf: 0.78,
      },
      {
        re: /([A-Za-z0-9_\u0E00-\u0E7F ]{2,40})\s*(?:->|→)\s*([A-Za-z0-9_\u0E00-\u0E7F ]{2,40})/g,
        rel: 'LEADS_TO',
        conf: 0.88,
      },
      {
        re: /([\u0E00-\u0E7FA-Za-z0-9_ ]{2,40}?)\s+(?:คือ|ใช้|รองรับ|รับประกัน|ต้องมี)\s+([\u0E00-\u0E7FA-Za-z0-9_+.\-/() ]{2,65})/g,
        rel: 'THAI_ASSERTION',
        conf: 0.84,
      },
    ];

    for (const line of lines) {
      const cleanLine = line.replace(/^#+\s*/, '').replace(/^[-*]\s*/, '');
      for (const { re, rel, conf } of patterns) {
        for (const m of cleanLine.matchAll(re)) {
          const s = m[1].trim();
          const o = m[2].trim();
          if (s.length >= 2 && o.length >= 2 && s.toLowerCase() !== o.toLowerCase() && s.split(' ').length <= 6) {
            triples.push({ subject: s, relation: rel, object: o, confidence: conf, snippet: cleanLine.slice(0, 180) });
          }
        }
      }
      // Also link document title/collection anchor to key headings or tags for reliable multi-hop reachability
      if (line.startsWith('#')) {
        const heading = cleanLine.slice(0, 56);
        if (heading.length >= 4 && doc.tags[0]) {
          triples.push({
            subject: doc.tags[0],
            relation: 'COVERED_IN',
            object: heading,
            confidence: 0.72,
            snippet: cleanLine.slice(0, 180),
          });
        }
      }
    }

    // Link document title to its first tag so every seeded/ingested doc participates in graph paths
    if (doc.title && doc.tags[0] && doc.title.toLowerCase() !== doc.tags[0].toLowerCase()) {
      triples.push({
        subject: doc.title.slice(0, 48),
        relation: 'TAGGED_AS',
        object: doc.tags[0],
        confidence: 0.75,
        snippet: `Document '${doc.title}' (${doc.collection})`,
      });
    }

    // Tag-to-tag structural linkage within the document
    for (let i = 0; i < Math.min(doc.tags.length - 1, 3); i++) {
      triples.push({
        subject: doc.tags[i],
        relation: 'RELATED_DOMAIN',
        object: doc.tags[i + 1],
        confidence: 0.7,
        snippet: `Document '${doc.title}' tags: ${doc.tags.join(', ')}`,
      });
    }

    return triples.slice(0, 32);
  }

  /**
   * Builds/refreshes the provenance-aware graph from accessible KnowledgeWorkspace documents.
   * Respects tenant boundaries strictly: scoped documents only link within that tenant (or unscoped global docs).
   */
  public buildFromWorkspace(scope?: GraphScope): {
    nodesCount: number;
    edgesCount: number;
    documentsProcessed: number;
    contradictionsCount: number;
  } {
    const kw = KnowledgeWorkspace.getInstance();
    const docs = kw.listDocuments(scope ? { tenantId: scope.tenantId, role: scope.role } : undefined);

    // Clear previous edges belonging to the target tenant (or all if unscoped rebuild)
    if (scope?.tenantId) {
      this.edges = this.edges.filter((e) => e.tenantId !== scope.tenantId);
    } else {
      this.edges = [];
      this.nodes.clear();
    }

    const upsertNode = (rawLabel: string, doc: KnowledgeDocument): KnowledgeGraphNode => {
      const resolved = this.resolveCanonicalEntity(rawLabel);
      const id = this.nodeKey(resolved.canonical, doc.tenantId);
      const existing = this.nodes.get(id);
      if (existing) {
        if (!existing.aliases.includes(rawLabel.trim())) {
          existing.aliases = [...existing.aliases, rawLabel.trim()].slice(0, 12);
        }
        if (!existing.documentIds.includes(doc.id)) {
          existing.documentIds.push(doc.id);
        }
        existing.updatedAt = doc.updatedAt;
        return existing;
      }
      const created: KnowledgeGraphNode = {
        nodeId: id,
        label: resolved.displayLabel,
        canonicalKey: resolved.canonical,
        kind: resolved.kind,
        aliases: [rawLabel.trim()],
        documentIds: [doc.id],
        tenantId: doc.tenantId,
        updatedAt: doc.updatedAt,
      };
      this.nodes.set(id, created);
      return created;
    };

    const edgeSeen = new Set<string>();
    for (const doc of docs) {
      const triples = this.extractTriplesFromDocument(doc);
      for (const tr of triples) {
        const sNode = upsertNode(tr.subject, doc);
        const oNode = upsertNode(tr.object, doc);
        if (sNode.nodeId === oNode.nodeId) continue;

        const edgeSig = `${doc.id}::${sNode.nodeId}::${tr.relation}::${oNode.nodeId}`;
        if (edgeSeen.has(edgeSig)) continue;
        edgeSeen.add(edgeSig);

        this.edges.push({
          edgeId: `kge_${crypto.createHash('sha1').update(edgeSig).digest('hex').slice(0, 12)}`,
          subjectId: sNode.nodeId,
          subjectLabel: sNode.label,
          relation: tr.relation,
          objectId: oNode.nodeId,
          objectLabel: oNode.label,
          documentId: doc.id,
          documentTitle: doc.title,
          contentHash: doc.contentHash,
          provenance: doc.provenance,
          confidence: tr.confidence,
          validFrom: doc.createdAt,
          updatedAt: doc.updatedAt,
          freshnessScore: this.computeFreshness(doc.updatedAt),
          tenantId: doc.tenantId,
          snippet: tr.snippet,
        });
      }
    }

    this.persist();
    if (scope?.tenantId) {
      PerformanceEngine.getInstance().invalidateTenantNamespace(scope.tenantId, 'kg_traverse');
    }

    const contradictions = this.detectGraphContradictions(scope);
    AuditLedger.append('SYSTEM', 'KNOWLEDGE_GRAPH_REBUILT', {
      tenantId: scope?.tenantId || 'global',
      documentsProcessed: docs.length,
      nodesCount: this.getScopedNodes(scope).length,
      edgesCount: this.getScopedEdges(scope).length,
      contradictionsCount: contradictions.length,
    });

    return {
      nodesCount: this.getScopedNodes(scope).length,
      edgesCount: this.getScopedEdges(scope).length,
      documentsProcessed: docs.length,
      contradictionsCount: contradictions.length,
    };
  }

  private getScopedEdges(scope?: GraphScope): KnowledgeGraphEdge[] {
    if (!scope?.tenantId) return [...this.edges];
    return this.edges.filter((e) => !e.tenantId || e.tenantId === scope.tenantId);
  }

  private getScopedNodes(scope?: GraphScope): KnowledgeGraphNode[] {
    const all = Array.from(this.nodes.values());
    if (!scope?.tenantId) return all;
    return all.filter((n) => !n.tenantId || n.tenantId === scope.tenantId);
  }

  /**
   * Multi-hop BFS traversal (1..3 hops) returning full provenance chains.
   */
  public traverseMultiHop(
    query: string,
    options: { maxHops?: number; limit?: number; scope?: GraphScope } = {}
  ): GraphTraversalResult {
    const t0 = Date.now();
    const maxHops = Math.min(3, Math.max(1, options.maxHops ?? 2));
    const limit = Math.min(20, Math.max(1, options.limit ?? 8));
    const tenantKey = options.scope?.tenantId || 'global';
    const cacheKey = `${query.trim().toLowerCase()}::h=${maxHops}::l=${limit}`;

    const perf = PerformanceEngine.getInstance();
    const cached = perf.getCached<GraphTraversalResult>('kg_traverse', tenantKey, cacheKey);
    if (cached) return cached;

    if (this.edges.length === 0) {
      this.buildFromWorkspace(options.scope);
    }

    const scopedNodes = this.getScopedNodes(options.scope);
    const scopedEdges = this.getScopedEdges(options.scope);
    const qLower = query.toLowerCase().trim();
    const qTokens = new Set(tokenize(query));

    // Identify seed nodes matching query tokens or canonical aliases
    const seedNodes = scopedNodes
      .map((n) => {
        let score = 0;
        if (qLower.includes(n.canonicalKey) || n.canonicalKey.includes(qLower)) score += 3;
        for (const al of n.aliases) {
          const alLower = al.toLowerCase();
          if (qLower.includes(alLower) || alLower.includes(qLower)) score += 2.5;
          for (const alTok of tokenize(al)) {
            if (qTokens.has(alTok)) score += 1.5;
          }
        }
        for (const tok of tokenize(n.label)) {
          if (qTokens.has(tok)) score += 1.2;
        }
        return { node: n, score };
      })
      .filter((x) => x.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, 5)
      .map((x) => x.node);

    // Build adjacency list over scoped edges (undirected traversal keeping directional provenance)
    const adj = new Map<string, KnowledgeGraphEdge[]>();
    for (const e of scopedEdges) {
      const listS = adj.get(e.subjectId) || [];
      listS.push(e);
      adj.set(e.subjectId, listS);

      const listO = adj.get(e.objectId) || [];
      listO.push(e);
      adj.set(e.objectId, listO);
    }

    const paths: GraphTraversalResult['paths'] = [];
    for (const seed of seedNodes) {
      interface QueueState {
        nodeId: string;
        hops: GraphTraversalHop[];
        visited: Set<string>;
      }
      const queue: QueueState[] = [{ nodeId: seed.nodeId, hops: [], visited: new Set([seed.nodeId]) }];

      while (queue.length > 0 && paths.length < 40) {
        const cur = queue.shift()!;
        if (cur.hops.length > 0) {
          const score =
            cur.hops.reduce((acc, h) => acc + h.confidence * h.freshnessScore, 0) / cur.hops.length -
            (cur.hops.length - 1) * 0.08;
          paths.push({
            score: Number(Math.max(0.05, score).toFixed(3)),
            hops: cur.hops,
            terminalLabel: cur.hops[cur.hops.length - 1].toLabel,
            provenanceHashes: Array.from(new Set(cur.hops.map((h) => h.contentHash).filter(Boolean))),
          });
        }
        if (cur.hops.length >= maxHops) continue;

        for (const edge of adj.get(cur.nodeId) || []) {
          const forward = edge.subjectId === cur.nodeId;
          const nextId = forward ? edge.objectId : edge.subjectId;
          if (cur.visited.has(nextId)) continue;

          const nextVisited = new Set(cur.visited);
          nextVisited.add(nextId);
          queue.push({
            nodeId: nextId,
            visited: nextVisited,
            hops: [
              ...cur.hops,
              {
                hop: cur.hops.length + 1,
                fromLabel: forward ? edge.subjectLabel : edge.objectLabel,
                relation: forward ? edge.relation : `INVERSE_${edge.relation}`,
                toLabel: forward ? edge.objectLabel : edge.subjectLabel,
                edgeId: edge.edgeId,
                documentId: edge.documentId,
                documentTitle: edge.documentTitle,
                contentHash: edge.contentHash,
                provenance: edge.provenance,
                freshnessScore: edge.freshnessScore,
                confidence: edge.confidence,
              },
            ],
          });
        }
      }
    }

    paths.sort((a, b) => b.score - a.score || b.hops.length - a.hops.length);
    const slicedPaths = paths.slice(0, limit);
    const allHashes = Array.from(new Set(slicedPaths.flatMap((p) => p.provenanceHashes).filter(Boolean)));
    const traversalClaims = enforceTruthClaims([
      classifyTruthClaim({
        domain: 'knowledge_graph',
        statement:
          slicedPaths.length > 0
            ? `Traversed ${slicedPaths.length} knowledge-graph path(s) across ${seedNodes.length} seed node(s) with ${allHashes.length} SHA-256 provenance hash(es)`
            : `No provenance-backed knowledge-graph path matched query '${query.slice(0, 64)}'`,
        classification: slicedPaths.length > 0 && allHashes.length > 0 ? 'VERIFIED_FACT' : 'UNVERIFIED',
        basis:
          slicedPaths.length > 0
            ? 'Direct graph BFS traversal bounded to tenant-scoped document hashes'
            : 'Zero matching entity edges in scoped workspace graph',
        evidenceRefs: allHashes.slice(0, 8),
      }),
    ]);

    const result: GraphTraversalResult = {
      query,
      seedNodes: seedNodes.map((n) => n.label),
      maxHops,
      paths: slicedPaths,
      latencyMs: Date.now() - t0,
      truthClaims: traversalClaims,
      truthSummary: summarizeTruthClaims(traversalClaims),
    };

    perf.setCached('kg_traverse', tenantKey, cacheKey, result);
    return result;
  }

  public detectGraphContradictions(scope?: GraphScope): GraphContradictionRecord[] {
    const scopedEdges = this.getScopedEdges(scope);
    const contradictions: GraphContradictionRecord[] = [];
    const seen = new Set<string>();

    // 1. Conflicting object values for same canonical subject + relation across different docs
    for (let i = 0; i < scopedEdges.length; i++) {
      for (let j = i + 1; j < scopedEdges.length; j++) {
        const a = scopedEdges[i];
        const b = scopedEdges[j];
        if (a.documentId === b.documentId) continue;
        if (a.subjectId === b.subjectId && a.relation === b.relation && a.objectId !== b.objectId) {
          // Check opposing polarity or numeric mismatch in snippets
          const numA = a.objectLabel.match(/\b(\d+(?:,\d+)*(?:\.\d+)?)\b/);
          const numB = b.objectLabel.match(/\b(\d+(?:,\d+)*(?:\.\d+)?)\b/);
          const negRe = /\b(never|forbidden|disabled|not supported|no|ห้าม|ไม่ใช่)\b/i;
          const posRe = /\b(always|must|required|enabled|supported|อนุญาต|ต้อง)\b/i;
          const polarityClash =
            (negRe.test(a.snippet) && posRe.test(b.snippet)) || (posRe.test(a.snippet) && negRe.test(b.snippet));

          if ((numA && numB && numA[1] !== numB[1]) || polarityClash) {
            const pairKey = [a.edgeId, b.edgeId].sort().join(':');
            if (seen.has(pairKey)) continue;
            seen.add(pairKey);
            contradictions.push({
              contradictionId: `kgc_${crypto.createHash('sha1').update(pairKey).digest('hex').slice(0, 10)}`,
              subjectLabel: a.subjectLabel,
              relation: a.relation,
              edgeAId: a.edgeId,
              edgeBId: b.edgeId,
              objectA: a.objectLabel,
              objectB: b.objectLabel,
              docAId: a.documentId,
              docBId: b.documentId,
              reason: polarityClash
                ? `Opposing assertion polarity for '${a.subjectLabel}' across '${a.documentTitle}' vs '${b.documentTitle}'`
                : `Conflicting numeric assertion for '${a.subjectLabel}' (${numA?.[1]} vs ${numB?.[1]})`,
              confidence: polarityClash ? 0.84 : 0.79,
            });
          }
        }
      }
    }

    // 2. Fallback snippet-level contradiction pass
    const textFlags = detectContradictions(
      scopedEdges.slice(0, 40).map((e) => ({ documentId: e.documentId, text: e.snippet }))
    );
    for (const tf of textFlags) {
      const edgeA = scopedEdges.find((e) => e.documentId === tf.docA && e.snippet === tf.snippetA);
      const edgeB = scopedEdges.find((e) => e.documentId === tf.docB && e.snippet === tf.snippetB);
      if (edgeA && edgeB) {
        const pairKey = [edgeA.edgeId, edgeB.edgeId].sort().join(':');
        if (seen.has(pairKey)) continue;
        seen.add(pairKey);
        contradictions.push({
          contradictionId: `kgc_${crypto.createHash('sha1').update(pairKey).digest('hex').slice(0, 10)}`,
          subjectLabel: edgeA.subjectLabel,
          relation: edgeA.relation,
          edgeAId: edgeA.edgeId,
          edgeBId: edgeB.edgeId,
          objectA: edgeA.objectLabel,
          objectB: edgeB.objectLabel,
          docAId: edgeA.documentId,
          docBId: edgeB.documentId,
          reason: tf.reason,
          confidence: tf.confidence,
        });
      }
    }

    return contradictions;
  }

  public verifyGraphConsistency(scope?: GraphScope): GraphConsistencyReport {
    const nodes = this.getScopedNodes(scope);
    const edges = this.getScopedEdges(scope);
    const nodeIds = new Set(nodes.map((n) => n.nodeId));

    const danglingEdgeIds = edges
      .filter((e) => !nodeIds.has(e.subjectId) || !nodeIds.has(e.objectId))
      .map((e) => e.edgeId);

    const missingProvenanceEdgeIds = edges
      .filter((e) => !e.documentId || !e.contentHash || e.contentHash.length !== 64 || !e.provenance)
      .map((e) => e.edgeId);

    const staleEdgeCount = edges.filter((e) => e.freshnessScore < 0.25).length;
    const contradictions = this.detectGraphContradictions(scope);
    const valid = danglingEdgeIds.length === 0 && missingProvenanceEdgeIds.length === 0;

    const rawClaims: TruthClaimRecord[] = [
      classifyTruthClaim({
        domain: 'knowledge_graph',
        statement: `Graph consistency check across ${nodes.length} node(s) and ${edges.length} edge(s): valid=${valid}`,
        classification: valid ? 'VERIFIED_FACT' : 'UNVERIFIED',
        basis: `dangling=${danglingEdgeIds.length}, missingProvenance=${missingProvenanceEdgeIds.length}`,
      }),
    ];
    if (contradictions.length > 0) {
      rawClaims.push(
        classifyTruthClaim({
          domain: 'knowledge_graph',
          statement: `${contradictions.length} cross-document contradiction(s) detected in knowledge graph`,
          classification: 'CONTRADICTED',
          basis: 'Triple/assertion polarity and numeric conflict check',
          evidenceRefs: contradictions.slice(0, 5).map((c) => c.contradictionId),
        })
      );
    }
    if (staleEdgeCount > 0) {
      rawClaims.push(
        classifyTruthClaim({
          domain: 'knowledge_graph',
          statement: `${staleEdgeCount} edge(s) have low temporal freshness (<0.25) and may require re-verification`,
          classification: 'ASSUMPTION',
          basis: 'Exponential freshness decay heuristic',
        })
      );
    }
    const truthClaims = enforceTruthClaims(rawClaims);

    return {
      valid,
      nodeCount: nodes.length,
      edgeCount: edges.length,
      danglingEdgeIds,
      missingProvenanceEdgeIds,
      contradictions,
      staleEdgeCount,
      checkedAt: new Date().toISOString(),
      truthClaims,
      truthSummary: summarizeTruthClaims(truthClaims),
    };
  }

  public getGraphSummary(scope?: GraphScope) {
    if (this.edges.length === 0) {
      this.buildFromWorkspace(scope);
    }
    const nodes = this.getScopedNodes(scope);
    const edges = this.getScopedEdges(scope);
    const consistency = this.verifyGraphConsistency(scope);
    return {
      nodeCount: nodes.length,
      edgeCount: edges.length,
      contradictionsCount: consistency.contradictions.length,
      consistencyValid: consistency.valid,
      topNodes: nodes.slice(0, 12),
      recentEdges: edges.slice(0, 15),
      truthClaims: consistency.truthClaims,
      truthSummary: consistency.truthSummary,
    };
  }
}

/**
 * ZYNTHEOR Sovereign NativeMemoryController
 * Manages episodic, semantic, task, working-context, and reasoning memories within the Sovereign Core.
 * Persists across sessions in native_data/memory_store.json (or ZYNTHEOR_MEMORY_FILE).
 *
 * CRITICAL INVARIANTS:
 *  - Every read, write, update, query, delete, consolidation, and rollback is logged to AuditLedger with SHA-256 chaining.
 *  - Strict tenant isolation: cross-tenant reads/writes/rollbacks throw FORBIDDEN.
 *  - Reversible consolidation preserves verbatim snapshots under memory_archives/ for exact rollback.
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { AuditLedger } from './AuditLedger';
import {
  classifyTruthClaim,
  enforceTruthClaims,
  summarizeTruthClaims,
  type TruthClaimRecord,
  type TruthKernelSummary,
} from './TruthKernel';

export type MemoryCategory =
  | 'episodic'
  | 'semantic'
  | 'user_preference'
  | 'reasoning_trace'
  | 'task_memory'
  | 'working_context';

export interface MemoryScope {
  tenantId?: string;
  userId?: string;
  role?: string;
}

export interface MemoryHistoryEntry {
  version: number;
  updatedAt: string;
  contentDigest: string;
  valuePreview: string;
}

export interface EpisodicMemoryItem {
  key: string;
  value: any;
  category: MemoryCategory;
  createdAt: string;
  updatedAt: string;
  readCount: number;
  version: number;
  history: MemoryHistoryEntry[];
  metadata?: Record<string, any>;
  scope?: MemoryScope;
  expiresAt?: string;
  importanceScore: number;
  contentDigest: string;
}

export interface ConsolidationArchiveRecord {
  consolidationId: string;
  tenantId: string;
  targetKey: string;
  sourceCategory: MemoryCategory;
  createdAt: string;
  sourceKeys: string[];
  sources: EpisodicMemoryItem[];
}

export interface MemoryStoreData {
  version: string;
  lastPersisted: string;
  verified_knowledge: Record<string, string>;
  sessions: Array<{ key: string; val: string; timestamp?: string }>;
  episodic: Record<string, EpisodicMemoryItem>;
  consolidations?: Record<string, { consolidationId: string; archivePath: string; tenantId: string; createdAt: string; targetKey: string }>;
}

function normalizeScopeArg(scopeOrOpts?: MemoryScope | { scope?: MemoryScope; ttlSeconds?: number }): {
  scope?: MemoryScope;
  ttlSeconds?: number;
} {
  if (!scopeOrOpts || typeof scopeOrOpts !== 'object') return {};
  if ('scope' in scopeOrOpts || 'ttlSeconds' in scopeOrOpts) {
    return {
      scope: (scopeOrOpts as { scope?: MemoryScope }).scope,
      ttlSeconds: (scopeOrOpts as { ttlSeconds?: number }).ttlSeconds,
    };
  }
  return { scope: scopeOrOpts as MemoryScope };
}

function tokenizeText(input: string): string[] {
  return String(input || '')
    .toLowerCase()
    .replace(/[^a-z0-9\u0E00-\u0E7F_]+/g, ' ')
    .trim()
    .split(/\s+/)
    .filter((t) => t.length >= 2);
}

export class NativeMemoryController {
  private static instance: NativeMemoryController | null = null;
  private loadedFilePath: string;
  private store: MemoryStoreData;

  private constructor() {
    this.loadedFilePath = this.resolveFilePath();
    this.store = this.loadFromDisk(this.loadedFilePath);
  }

  public static getInstance(): NativeMemoryController {
    if (!NativeMemoryController.instance) {
      NativeMemoryController.instance = new NativeMemoryController();
    }
    return NativeMemoryController.instance;
  }

  private resolveFilePath(): string {
    if (process.env.ZYNTHEOR_MEMORY_FILE) {
      return path.resolve(process.env.ZYNTHEOR_MEMORY_FILE);
    }
    return path.resolve(process.cwd(), 'native_data', 'memory_store.json');
  }

  private resolveArchiveDir(): string {
    return path.join(path.dirname(this.resolveFilePath()), 'memory_archives');
  }

  private ensureSyncedStore(): void {
    const target = this.resolveFilePath();
    if (target !== this.loadedFilePath) {
      this.loadedFilePath = target;
      this.store = this.loadFromDisk(target);
    }
  }

  private loadFromDisk(filePath: string): MemoryStoreData {
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    if (fs.existsSync(filePath)) {
      try {
        const raw = fs.readFileSync(filePath, 'utf8');
        const parsed = JSON.parse(raw);
        if (!parsed.episodic) parsed.episodic = {};
        if (!parsed.verified_knowledge) parsed.verified_knowledge = {};
        if (!parsed.sessions) parsed.sessions = [];
        if (!parsed.consolidations) parsed.consolidations = {};
        for (const item of Object.values(parsed.episodic) as EpisodicMemoryItem[]) {
          if (!Number.isFinite(item.version)) item.version = 1;
          if (!Array.isArray(item.history)) {
            item.history = [
              {
                version: item.version,
                updatedAt: item.updatedAt || item.createdAt || new Date().toISOString(),
                contentDigest: item.contentDigest || this.computeDigest(item.value),
                valuePreview: this.previewValue(item.value),
              },
            ];
          }
          if (!Number.isFinite(item.importanceScore)) {
            item.importanceScore = this.computeImportance(item.value, item.category, item.readCount || 0);
          }
        }
        return parsed;
      } catch (err) {
        console.error('[NativeMemoryController] Failed to parse memory store, resetting', err);
      }
    }

    const initial: MemoryStoreData = {
      version: '1.0.0-SOVEREIGN',
      lastPersisted: new Date().toISOString(),
      verified_knowledge: {
        architecture: 'ZYNTHEOR Native Core; active checkpoint size must be read from verified Cloud Runtime evidence',
        sovereignty_rule: 'Native model is the intelligence core; runtime readiness requires a verified Cloud checkpoint and recorded evidence',
        sandbox_root: '/workspace',
        multilingual_engine: 'Thai-English Dual Native Vocabulary & Code-Switching',
      },
      sessions: [],
      episodic: {},
      consolidations: {},
    };

    this.persistToDisk(initial, filePath);
    return initial;
  }

  private persistToDisk(data: MemoryStoreData, targetPath?: string): void {
    const filePath = targetPath || this.resolveFilePath();
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    data.lastPersisted = new Date().toISOString();
    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf8');
  }

  private computeDigest(val: any): string {
    const serialized = typeof val === 'string' ? val : JSON.stringify(val);
    return crypto.createHash('sha256').update(serialized ?? '').digest('hex');
  }

  private previewValue(val: any): string {
    const s = typeof val === 'string' ? val : JSON.stringify(val);
    return String(s || '').slice(0, 140);
  }

  private computeImportance(val: any, category: MemoryCategory, readCount: number): number {
    const catWeight: Record<MemoryCategory, number> = {
      semantic: 0.85,
      user_preference: 0.8,
      task_memory: 0.78,
      reasoning_trace: 0.72,
      working_context: 0.65,
      episodic: 0.55,
    };
    const lenBoost = Math.min(0.1, String(typeof val === 'string' ? val : JSON.stringify(val)).length / 2000);
    const readBoost = Math.min(0.1, readCount * 0.02);
    return Number(Math.min(1, (catWeight[category] || 0.5) + lenBoost + readBoost).toFixed(3));
  }

  private isExpired(item: EpisodicMemoryItem): boolean {
    if (!item.expiresAt) return false;
    const expMs = Date.parse(item.expiresAt);
    return Number.isFinite(expMs) && expMs <= Date.now();
  }

  private assertScopeAccess(item: EpisodicMemoryItem, callerScope?: MemoryScope, action = 'read'): void {
    if (!item.scope?.tenantId) return;
    if (!callerScope?.tenantId) {
      throw new Error(`FORBIDDEN: Tenant scope required to ${action} tenant-scoped memory '${item.key}'.`);
    }
    if (item.scope.tenantId !== callerScope.tenantId) {
      throw new Error(
        `FORBIDDEN: Cross-tenant memory access denied for key '${item.key}' (expected tenant '${item.scope.tenantId}', got '${callerScope.tenantId}').`
      );
    }
  }

  private isItemAccessibleInScope(item: EpisodicMemoryItem, callerScope?: MemoryScope): boolean {
    if (this.isExpired(item)) return false;
    if (!callerScope?.tenantId) {
      return !item.scope?.tenantId;
    }
    if (!item.scope?.tenantId) return true;
    return item.scope.tenantId === callerScope.tenantId;
  }

  /**
   * Stores or updates an episodic/semantic/task memory item with optional tenant scope & TTL.
   */
  public storeMemory(
    key: string,
    value: any,
    category: MemoryCategory = 'episodic',
    metadata?: Record<string, any>,
    options?: { scope?: MemoryScope; ttlSeconds?: number }
  ): EpisodicMemoryItem {
    this.ensureSyncedStore();
    const now = new Date().toISOString();
    const digest = this.computeDigest(value);
    const existing = this.store.episodic[key];
    if (existing && options?.scope) {
      this.assertScopeAccess(existing, options.scope, 'overwrite');
    }

    const nextVersion = existing ? (existing.version || 1) + 1 : 1;
    const historyEntry: MemoryHistoryEntry = {
      version: nextVersion,
      updatedAt: now,
      contentDigest: digest,
      valuePreview: this.previewValue(value),
    };
    const priorHistory = existing?.history ? [...existing.history] : [];
    const mergedScope = options?.scope || existing?.scope;
    const expiresAt =
      typeof options?.ttlSeconds === 'number' && Number.isFinite(options.ttlSeconds) && options.ttlSeconds > 0
        ? new Date(Date.now() + options.ttlSeconds * 1000).toISOString()
        : existing?.expiresAt;

    const item: EpisodicMemoryItem = {
      key,
      value,
      category,
      createdAt: existing ? existing.createdAt : now,
      updatedAt: now,
      readCount: existing ? existing.readCount : 0,
      version: nextVersion,
      history: [...priorHistory, historyEntry].slice(-25),
      metadata: metadata || existing?.metadata,
      ...(mergedScope ? { scope: { tenantId: mergedScope.tenantId, userId: mergedScope.userId, role: mergedScope.role } } : {}),
      ...(expiresAt ? { expiresAt } : {}),
      importanceScore: this.computeImportance(value, category, existing?.readCount || 0),
      contentDigest: digest,
    };

    this.store.episodic[key] = item;
    this.persistToDisk(this.store);

    AuditLedger.append('SYSTEM', 'MEMORY_WRITE_OP', {
      memoryKey: key,
      category,
      version: nextVersion,
      tenantId: mergedScope?.tenantId || null,
      contentDigest: digest,
      isUpdate: Boolean(existing),
      timestamp: now,
    });

    return item;
  }

  /**
   * Updates an existing memory item, incrementing version and retaining history.
   */
  public updateMemory(
    key: string,
    value: any,
    category?: MemoryCategory,
    metadata?: Record<string, any>,
    options?: { scope?: MemoryScope; ttlSeconds?: number }
  ): EpisodicMemoryItem {
    this.ensureSyncedStore();
    const existing = this.store.episodic[key];
    if (existing && options?.scope) {
      this.assertScopeAccess(existing, options.scope, 'update');
    }
    const now = new Date().toISOString();
    const digest = this.computeDigest(value);
    const prevDigest = existing ? existing.contentDigest : null;
    const nextCategory = category || existing?.category || 'episodic';
    const nextVersion = existing ? (existing.version || 1) + 1 : 1;
    const historyEntry: MemoryHistoryEntry = {
      version: nextVersion,
      updatedAt: now,
      contentDigest: digest,
      valuePreview: this.previewValue(value),
    };
    const mergedScope = options?.scope || existing?.scope;
    const expiresAt =
      typeof options?.ttlSeconds === 'number' && Number.isFinite(options.ttlSeconds) && options.ttlSeconds > 0
        ? new Date(Date.now() + options.ttlSeconds * 1000).toISOString()
        : existing?.expiresAt;

    const item: EpisodicMemoryItem = {
      key,
      value,
      category: nextCategory,
      createdAt: existing ? existing.createdAt : now,
      updatedAt: now,
      readCount: existing ? existing.readCount : 0,
      version: nextVersion,
      history: [...(existing?.history || []), historyEntry].slice(-25),
      metadata: metadata || existing?.metadata,
      ...(mergedScope ? { scope: { tenantId: mergedScope.tenantId, userId: mergedScope.userId, role: mergedScope.role } } : {}),
      ...(expiresAt ? { expiresAt } : {}),
      importanceScore: this.computeImportance(value, nextCategory, existing?.readCount || 0),
      contentDigest: digest,
    };

    this.store.episodic[key] = item;
    this.persistToDisk(this.store);

    AuditLedger.append('SYSTEM', 'MEMORY_UPDATE_OP', {
      memoryKey: key,
      previousDigest: prevDigest,
      newDigest: digest,
      version: nextVersion,
      category: item.category,
      tenantId: mergedScope?.tenantId || null,
      updatedAt: now,
    });

    return item;
  }

  /**
   * Retrieves a memory item by key with TTL enforcement and tenant isolation.
   */
  public retrieveMemory(
    key: string,
    scopeOrOpts?: MemoryScope | { scope?: MemoryScope }
  ): EpisodicMemoryItem | null {
    this.ensureSyncedStore();
    const { scope } = normalizeScopeArg(scopeOrOpts);
    const item = this.store.episodic[key];
    const now = new Date().toISOString();

    if (item) {
      this.assertScopeAccess(item, scope, 'retrieve');
      if (this.isExpired(item)) {
        delete this.store.episodic[key];
        this.persistToDisk(this.store);
        AuditLedger.append('SYSTEM', 'MEMORY_READ_OP', {
          memoryKey: key,
          found: false,
          expired: true,
          timestamp: now,
        });
        return null;
      }

      item.readCount++;
      item.importanceScore = this.computeImportance(item.value, item.category, item.readCount);
      this.persistToDisk(this.store);

      AuditLedger.append('SYSTEM', 'MEMORY_READ_OP', {
        memoryKey: key,
        found: true,
        readCount: item.readCount,
        contentDigest: item.contentDigest,
        timestamp: now,
      });

      return item;
    }

    AuditLedger.append('SYSTEM', 'MEMORY_READ_OP', {
      memoryKey: key,
      found: false,
      timestamp: now,
    });

    return null;
  }

  /**
   * Queries memories by substring or category with optional tenant scope filtering.
   */
  public queryMemories(
    queryStr: string,
    category?: MemoryCategory,
    scopeOrOpts?: MemoryScope | { scope?: MemoryScope }
  ): EpisodicMemoryItem[] {
    this.ensureSyncedStore();
    const { scope } = normalizeScopeArg(scopeOrOpts);
    const items = Object.values(this.store.episodic);
    const qLower = String(queryStr || '').toLowerCase();

    const results = items.filter((item) => {
      if (!this.isItemAccessibleInScope(item, scope)) return false;
      if (category && item.category !== category) return false;
      if (!queryStr) return true;
      const keyMatch = item.key.toLowerCase().includes(qLower);
      const valMatch = JSON.stringify(item.value).toLowerCase().includes(qLower);
      return keyMatch || valMatch;
    });

    AuditLedger.append('SYSTEM', 'MEMORY_QUERY_OP', {
      query: queryStr,
      categoryFilter: category || 'ALL',
      matchCount: results.length,
    });

    return results;
  }

  /**
   * Ranked recall combining token overlap, importance score, and recency within scope.
   */
  public recallRankedMemories(
    query: string,
    options: { limit?: number; category?: MemoryCategory; scope?: MemoryScope } = {}
  ): Array<{ item: EpisodicMemoryItem; score: number }> {
    this.ensureSyncedStore();
    const qTokens = tokenizeText(query);
    const limit = Math.max(1, Math.min(50, options.limit ?? 10));
    const scored: Array<{ item: EpisodicMemoryItem; score: number }> = [];

    for (const item of Object.values(this.store.episodic)) {
      if (!this.isItemAccessibleInScope(item, options.scope)) continue;
      if (options.category && item.category !== options.category) continue;
      const hay = `${item.key} ${typeof item.value === 'string' ? item.value : JSON.stringify(item.value)}`.toLowerCase();
      const hayTokens = new Set(tokenizeText(hay));
      let overlap = 0;
      for (const tok of qTokens) {
        if (hayTokens.has(tok) || hay.includes(tok)) overlap += 1;
      }
      if (qTokens.length > 0 && overlap === 0) continue;
      const tokenScore = qTokens.length > 0 ? overlap / qTokens.length : 0.5;
      const recencyMs = Math.max(0, Date.now() - Date.parse(item.updatedAt || item.createdAt));
      const recencyBoost = 1 / (1 + recencyMs / (1000 * 60 * 60 * 24));
      const totalScore = Number((tokenScore * 0.7 + item.importanceScore * 0.2 + recencyBoost * 0.1).toFixed(4));
      scored.push({ item, score: totalScore });
    }

    scored.sort((a, b) => b.score - a.score);
    return scored.slice(0, limit);
  }

  /**
   * Returns working_context & task_memory entries associated with a session ID under caller scope.
   */
  public getWorkingContextForSession(
    sessionId: string,
    scope?: MemoryScope
  ): { sessionId: string; workingContext: EpisodicMemoryItem[]; taskMemories: EpisodicMemoryItem[] } {
    this.ensureSyncedStore();
    const all = Object.values(this.store.episodic).filter((item) => {
      if (!this.isItemAccessibleInScope(item, scope)) return false;
      return item.metadata?.sessionId === sessionId;
    });

    return {
      sessionId,
      workingContext: all.filter((i) => i.category === 'working_context'),
      taskMemories: all.filter((i) => i.category === 'task_memory'),
    };
  }

  /**
   * Stores a memory with explicit conflict detection when the same key holds divergent content.
   */
  public storeWithConflictResolution(
    key: string,
    value: any,
    category: MemoryCategory = 'episodic',
    strategy: 'manual_review' | 'overwrite' | 'keep_existing' = 'manual_review',
    options?: { scope?: MemoryScope; ttlSeconds?: number }
  ): {
    conflictDetected: boolean;
    stored: boolean;
    item: EpisodicMemoryItem;
    conflict: {
      resolution: 'NEEDS_REVIEW' | 'OVERWROTE' | 'KEPT_EXISTING' | 'NONE';
      existingDigest: string | null;
      candidateDigest: string;
    };
  } {
    this.ensureSyncedStore();
    const existing = this.store.episodic[key];
    const candidateDigest = this.computeDigest(value);

    if (existing && !this.isExpired(existing)) {
      if (options?.scope) {
        this.assertScopeAccess(existing, options.scope, 'resolve conflict on');
      }
      if (existing.contentDigest !== candidateDigest) {
        if (strategy === 'manual_review') {
          AuditLedger.append('SYSTEM', 'MEMORY_CONFLICT_FLAGGED', {
            memoryKey: key,
            existingDigest: existing.contentDigest,
            candidateDigest,
            resolution: 'NEEDS_REVIEW',
          });
          return {
            conflictDetected: true,
            stored: false,
            item: existing,
            conflict: {
              resolution: 'NEEDS_REVIEW',
              existingDigest: existing.contentDigest,
              candidateDigest,
            },
          };
        }
        if (strategy === 'keep_existing') {
          return {
            conflictDetected: true,
            stored: false,
            item: existing,
            conflict: {
              resolution: 'KEPT_EXISTING',
              existingDigest: existing.contentDigest,
              candidateDigest,
            },
          };
        }
        const updated = this.storeMemory(key, value, category, undefined, options);
        return {
          conflictDetected: true,
          stored: true,
          item: updated,
          conflict: {
            resolution: 'OVERWROTE',
            existingDigest: existing.contentDigest,
            candidateDigest,
          },
        };
      }
    }

    const saved = this.storeMemory(key, value, category, undefined, options);
    return {
      conflictDetected: false,
      stored: true,
      item: saved,
      conflict: {
        resolution: 'NONE',
        existingDigest: existing?.contentDigest || null,
        candidateDigest,
      },
    };
  }

  /**
   * Non-destructive provenance consolidation of matching memories into a single semantic summary key.
   */
  public consolidateMemories(params: {
    targetKey: string;
    sourceCategory?: MemoryCategory;
    maxSources?: number;
    scope?: MemoryScope;
  }): {
    consolidated: boolean;
    consolidationId: string;
    targetKey: string;
    sourceKeys: string[];
    count: number;
  } {
    this.ensureSyncedStore();
    const sourceCategory = params.sourceCategory || 'task_memory';
    const maxSources = Math.max(1, Math.min(100, params.maxSources ?? 20));
    const candidates = Object.values(this.store.episodic)
      .filter((item) => {
        if (item.key === params.targetKey) return false;
        if (item.category !== sourceCategory) return false;
        if (!this.isItemAccessibleInScope(item, params.scope)) return false;
        if (params.scope?.tenantId) return item.scope?.tenantId === params.scope.tenantId;
        return true;
      })
      .slice(0, maxSources);

    const consolidationId = `cons_${crypto.randomUUID().slice(0, 12)}`;
    const sourceKeys = candidates.map((c) => c.key);
    const summaryText = candidates
      .map((c) => `[${c.key}] ${typeof c.value === 'string' ? c.value : JSON.stringify(c.value)}`)
      .join('\n');

    this.storeMemory(
      params.targetKey,
      {
        consolidationId,
        sourceCategory,
        sourceKeys,
        summary: summaryText,
        createdAt: new Date().toISOString(),
      },
      'semantic',
      { consolidationId, sourceKeys },
      { scope: params.scope }
    );

    AuditLedger.append('SYSTEM', 'MEMORY_CONSOLIDATION_OP', {
      consolidationId,
      targetKey: params.targetKey,
      sourceCategory,
      sourceKeys,
      reversible: false,
    });

    return {
      consolidated: candidates.length > 0,
      consolidationId,
      targetKey: params.targetKey,
      sourceKeys,
      count: candidates.length,
    };
  }

  /**
   * Detects near-duplicate memories within caller scope via token Jaccard similarity (>= 0.85).
   */
  public detectNearDuplicates(
    scope?: MemoryScope
  ): Array<{ keyA: string; keyB: string; similarity: number }> {
    this.ensureSyncedStore();
    const items = Object.values(this.store.episodic).filter((item) => {
      if (!this.isItemAccessibleInScope(item, scope)) return false;
      if (scope?.tenantId) return item.scope?.tenantId === scope.tenantId;
      return true;
    });

    const tokenSets = items.map((item) => ({
      item,
      tokens: new Set(tokenizeText(typeof item.value === 'string' ? item.value : JSON.stringify(item.value))),
    }));

    const duplicates: Array<{ keyA: string; keyB: string; similarity: number }> = [];
    for (let i = 0; i < tokenSets.length; i++) {
      for (let j = i + 1; j < tokenSets.length; j++) {
        const a = tokenSets[i];
        const b = tokenSets[j];
        if (a.item.contentDigest === b.item.contentDigest) {
          duplicates.push({ keyA: a.item.key, keyB: b.item.key, similarity: 1 });
          continue;
        }
        if (a.tokens.size === 0 || b.tokens.size === 0) continue;
        let inter = 0;
        for (const tok of a.tokens) {
          if (b.tokens.has(tok)) inter++;
        }
        const union = a.tokens.size + b.tokens.size - inter;
        const sim = union > 0 ? inter / union : 0;
        if (sim >= 0.85) {
          duplicates.push({
            keyA: a.item.key,
            keyB: b.item.key,
            similarity: Number(sim.toFixed(3)),
          });
        }
      }
    }
    return duplicates;
  }

  /**
   * Reversible episodic -> semantic consolidation.
   * Archives verbatim source items to disk so rollbackConsolidation restores every source bit-for-bit.
   */
  public consolidateEpisodicToSemanticReversible(params: {
    targetKey: string;
    sourceCategory?: MemoryCategory;
    maxSources?: number;
    archiveSourcesFromActive?: boolean;
    scope?: MemoryScope;
  }): {
    consolidated: boolean;
    consolidationId: string;
    targetKey: string;
    archivePath: string;
    sourceKeys: string[];
    archivedCount: number;
  } {
    this.ensureSyncedStore();
    const sourceCategory = params.sourceCategory || 'episodic';
    const maxSources = Math.max(1, Math.min(100, params.maxSources ?? 20));
    const archiveSourcesFromActive = params.archiveSourcesFromActive ?? true;

    const candidates = Object.values(this.store.episodic)
      .filter((item) => {
        if (item.key === params.targetKey) return false;
        if (item.category !== sourceCategory) return false;
        if (!this.isItemAccessibleInScope(item, params.scope)) return false;
        if (params.scope?.tenantId) return item.scope?.tenantId === params.scope.tenantId;
        return true;
      })
      .slice(0, maxSources);

    const consolidationId = `rev_cons_${crypto.randomUUID().slice(0, 12)}`;
    const archiveDir = this.resolveArchiveDir();
    if (!fs.existsSync(archiveDir)) {
      fs.mkdirSync(archiveDir, { recursive: true });
    }
    const archivePath = path.join(archiveDir, `${consolidationId}.json`);
    const snapshot: ConsolidationArchiveRecord = {
      consolidationId,
      tenantId: params.scope?.tenantId || 'default',
      targetKey: params.targetKey,
      sourceCategory,
      createdAt: new Date().toISOString(),
      sourceKeys: candidates.map((c) => c.key),
      sources: JSON.parse(JSON.stringify(candidates)),
    };
    fs.writeFileSync(archivePath, JSON.stringify(snapshot, null, 2), 'utf8');

    const consolidatedSummary = candidates
      .map((c) => `- (${c.key}) ${typeof c.value === 'string' ? c.value : JSON.stringify(c.value)}`)
      .join('\n');

    this.storeMemory(
      params.targetKey,
      {
        consolidationId,
        sourceCategory,
        sourceCount: candidates.length,
        sourceKeys: snapshot.sourceKeys,
        summary: consolidatedSummary,
        archivePath,
      },
      'semantic',
      { consolidationId, sourceKeys: snapshot.sourceKeys, archivePath },
      { scope: params.scope }
    );

    let archivedCount = 0;
    if (archiveSourcesFromActive) {
      for (const c of candidates) {
        if (this.store.episodic[c.key]) {
          delete this.store.episodic[c.key];
          archivedCount++;
        }
      }
    }

    if (!this.store.consolidations) this.store.consolidations = {};
    this.store.consolidations[consolidationId] = {
      consolidationId,
      archivePath,
      tenantId: snapshot.tenantId,
      createdAt: snapshot.createdAt,
      targetKey: params.targetKey,
    };
    this.persistToDisk(this.store);

    AuditLedger.append('SYSTEM', 'MEMORY_REVERSIBLE_CONSOLIDATION', {
      consolidationId,
      tenantId: snapshot.tenantId,
      targetKey: params.targetKey,
      sourceKeys: snapshot.sourceKeys,
      archivedCount,
      archivePath,
    });

    return {
      consolidated: candidates.length > 0,
      consolidationId,
      targetKey: params.targetKey,
      archivePath,
      sourceKeys: snapshot.sourceKeys,
      archivedCount,
    };
  }

  /**
   * Restores verbatim archived source memories from a reversible consolidation snapshot.
   */
  public rollbackConsolidation(
    consolidationId: string,
    scope?: MemoryScope
  ): {
    rolledBack: boolean;
    consolidationId: string;
    restoredKeys: string[];
  } {
    this.ensureSyncedStore();
    const indexRec = this.store.consolidations?.[consolidationId];
    const archivePath = indexRec?.archivePath || path.join(this.resolveArchiveDir(), `${consolidationId}.json`);
    if (!fs.existsSync(archivePath)) {
      throw new Error(`NOT_FOUND: Consolidation archive '${consolidationId}' does not exist.`);
    }

    const snapshot = JSON.parse(fs.readFileSync(archivePath, 'utf8')) as ConsolidationArchiveRecord;
    if (snapshot.tenantId && snapshot.tenantId !== 'default') {
      if (!scope?.tenantId || scope.tenantId !== snapshot.tenantId) {
        throw new Error(
          `FORBIDDEN: Cross-tenant rollback denied for consolidation '${consolidationId}' (expected tenant '${snapshot.tenantId}', got '${scope?.tenantId || 'none'}').`
        );
      }
    }

    const restoredKeys: string[] = [];
    for (const src of snapshot.sources || []) {
      this.store.episodic[src.key] = src;
      restoredKeys.push(src.key);
    }
    if (snapshot.targetKey && this.store.episodic[snapshot.targetKey]) {
      delete this.store.episodic[snapshot.targetKey];
    }
    this.persistToDisk(this.store);

    AuditLedger.append('SYSTEM', 'MEMORY_CONSOLIDATION_ROLLBACK', {
      consolidationId,
      tenantId: snapshot.tenantId,
      restoredKeys,
    });

    return {
      rolledBack: true,
      consolidationId,
      restoredKeys,
    };
  }

  /**
   * Lists all currently active non-expired memories (optionally scoped by tenant).
   */
  public listAll(scope?: MemoryScope): EpisodicMemoryItem[] {
    this.ensureSyncedStore();
    return Object.values(this.store.episodic).filter((item) => this.isItemAccessibleInScope(item, scope));
  }

  /**
   * Clears a specific memory key with optional tenant isolation enforcement.
   */
  public deleteMemory(key: string, scopeOrOpts?: MemoryScope | { scope?: MemoryScope }): boolean {
    this.ensureSyncedStore();
    const { scope } = normalizeScopeArg(scopeOrOpts);
    const existing = this.store.episodic[key];
    if (existing) {
      if (scope) {
        this.assertScopeAccess(existing, scope, 'delete');
      }
      const digest = existing.contentDigest;
      delete this.store.episodic[key];
      this.persistToDisk(this.store);

      AuditLedger.append('SYSTEM', 'MEMORY_DELETE_OP', {
        memoryKey: key,
        previousDigest: digest,
      });
      return true;
    }
    return false;
  }

  /**
   * Analyzes memory lifecycle health, expirations, and duplicate candidates with Truth Kernel claims.
   */
  public analyzeMemoryLifecycle(scope?: MemoryScope): {
    checkedAt: string;
    totalScopedItems: number;
    byCategory: Record<string, number>;
    expiringSoonCount: number;
    nearDuplicatesCount: number;
    consolidationSnapshotsCount: number;
    truthClaims: TruthClaimRecord[];
    truthSummary: TruthKernelSummary;
  } {
    this.ensureSyncedStore();
    const items = Object.values(this.store.episodic).filter((item) => {
      if (scope?.tenantId) {
        return !item.scope?.tenantId || item.scope.tenantId === scope.tenantId;
      }
      return true;
    });
    const byCategory: Record<string, number> = {};
    let expiringSoonCount = 0;
    const oneDayMs = 24 * 60 * 60 * 1000;
    for (const item of items) {
      byCategory[item.category] = (byCategory[item.category] || 0) + 1;
      if (item.expiresAt) {
        const expMs = Date.parse(item.expiresAt);
        if (Number.isFinite(expMs) && expMs - Date.now() <= oneDayMs) {
          expiringSoonCount++;
        }
      }
    }
    const dups = this.detectNearDuplicates(scope);
    const consCount = Object.keys(this.store.consolidations || {}).length;

    const claims = enforceTruthClaims([
      classifyTruthClaim({
        domain: 'memory_controller',
        statement: `Analyzed ${items.length} scoped memory item(s): ${dups.length} near-duplicate pair(s), ${expiringSoonCount} expiring <=24h, ${consCount} reversible consolidation archive(s)`,
        classification: 'VERIFIED_FACT',
        basis: `Direct inspection of persisted store (${path.basename(this.resolveFilePath())}) and token Jaccard duplicate scan`,
      }),
    ]);

    return {
      checkedAt: new Date().toISOString(),
      totalScopedItems: items.length,
      byCategory,
      expiringSoonCount,
      nearDuplicatesCount: dups.length,
      consolidationSnapshotsCount: consCount,
      truthClaims: claims,
      truthSummary: summarizeTruthClaims(claims),
    };
  }

  /**
   * Verifies SHA-256 content digests of every item and the backing store file.
   */
  public verifyStoreIntegrity(): {
    valid: boolean;
    totalItems: number;
    corruptedKeys: string[];
    storeSha256: string;
    checkedAt: string;
    truthClaims: TruthClaimRecord[];
    truthSummary: TruthKernelSummary;
  } {
    this.ensureSyncedStore();
    const items = Object.values(this.store.episodic);
    const corruptedKeys: string[] = [];
    for (const item of items) {
      const actualDigest = this.computeDigest(item.value);
      if (actualDigest !== item.contentDigest) {
        corruptedKeys.push(item.key);
      }
    }

    const filePath = this.resolveFilePath();
    let storeSha256 = '';
    try {
      const raw = fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : JSON.stringify(this.store);
      storeSha256 = crypto.createHash('sha256').update(raw).digest('hex');
    } catch {
      storeSha256 = crypto.createHash('sha256').update(JSON.stringify(this.store)).digest('hex');
    }

    const valid = corruptedKeys.length === 0 && /^[a-f0-9]{64}$/.test(storeSha256);
    const claims = enforceTruthClaims([
      classifyTruthClaim({
        domain: 'memory_controller',
        statement: valid
          ? `Memory store integrity VERIFIED (${items.length} item(s), storeSha256=${storeSha256.slice(0, 12)})`
          : `Memory store integrity FAILED: ${corruptedKeys.length} corrupted key(s)`,
        classification: valid ? 'VERIFIED_FACT' : 'CONTRADICTED',
        basis: `Per-item SHA-256 contentDigest verification + backing file SHA-256`,
        evidenceRefs: [storeSha256, ...corruptedKeys],
      }),
    ]);

    return {
      valid,
      totalItems: items.length,
      corruptedKeys,
      storeSha256,
      checkedAt: new Date().toISOString(),
      truthClaims: claims,
      truthSummary: summarizeTruthClaims(claims),
    };
  }

  /**
   * Gets memory health stats.
   */
  public getStats(): {
    totalItems: number;
    totalCategories: Record<string, number>;
    storeSizeBytes: number;
    lastPersisted: string;
  } {
    this.ensureSyncedStore();
    const items = Object.values(this.store.episodic);
    const categories: Record<string, number> = {};
    for (const item of items) {
      categories[item.category] = (categories[item.category] || 0) + 1;
    }

    let sizeBytes = 0;
    try {
      sizeBytes = fs.statSync(this.resolveFilePath()).size;
    } catch {
      sizeBytes = 0;
    }

    return {
      totalItems: items.length,
      totalCategories: categories,
      storeSizeBytes: sizeBytes,
      lastPersisted: this.store.lastPersisted,
    };
  }
}

/**
 * ZYNTHEOR Sovereign Identity & Access Layer
 * Hardened First-Party Cryptographic Token Validator & RBAC Engine.
 *
 * Strict Security Invariants:
 * 1. No hardcoded default secrets (must load from env or fail-closed).
 * 2. Constant-time signature comparison using crypto.timingSafeEqual().
 * 3. Strict token expiration (exp) and issue-time (iat) verification.
 * 4. Algorithm validation (enforces HS256, rejects "none" and spoofed headers).
 * 5. Strict 3-part token structure validation.
 * 6. Safe JSON parsing with comprehensive exception boundaries.
 * 7. Tenant isolation enforcement (prevents cross-tenant token replay).
 * 8. Role-based authorization & privilege escalation prevention.
 */

import crypto from 'crypto';
import { AuditLedger } from './AuditLedger';

export type SovereignRole = 'guest' | 'developer' | 'operator' | 'admin' | 'auditor';

export interface TokenHeader {
  alg: 'HS256';
  typ: 'ZY-TOKEN';
}

export interface TokenPayload {
  sub: string;             // Subject (User / Agent ID)
  tenantId: string;        // Tenant isolation domain
  role: SovereignRole;     // Authorized role
  iat: number;             // Issued at (unix seconds)
  exp: number;             // Expiration (unix seconds)
  jti?: string;            // Unique JWT ID to prevent replay attacks
  scope?: string[];        // Authorized scopes
}

export interface VerificationResult {
  valid: boolean;
  code:
    | 'VERIFIED'
    | 'MISSING_SECRET'
    | 'MALFORMED_STRUCTURE'
    | 'INVALID_HEADER'
    | 'UNSUPPORTED_ALGORITHM'
    | 'MALFORMED_JSON'
    | 'SIGNATURE_MISMATCH'
    | 'TOKEN_EXPIRED'
    | 'TOKEN_NOT_YET_VALID'
    | 'TENANT_MISMATCH'
    | 'UNAUTHORIZED_ROLE';
  reason: string;
  payload?: TokenPayload;
  latencyMs?: number;
}

export class SovereignIdentity {
  private static instance: SovereignIdentity | null = null;
  private masterSecret: Buffer;

  private static readonly ROLE_HIERARCHY: Record<SovereignRole, number> = {
    guest: 1,
    developer: 2,
    operator: 3,
    auditor: 4,
    admin: 5
  };

  private constructor() {
    // 1. Secret Management: MUST load from environment or generate a secure ephemeral 32-byte secret.
    // ABSOLUTE BAN on weak hardcoded strings like 'zyntheor-sovereign-master-secret'.
    const envSecret = process.env.ZYNTHEOR_MASTER_SECRET;
    if (envSecret && envSecret.trim().length >= 32) {
      this.masterSecret = Buffer.from(envSecret.trim(), 'utf8');
    } else {
      // Ephemeral crypto-random 256-bit key if not specified
      this.masterSecret = crypto.randomBytes(32);
      AuditLedger.append('SYSTEM', 'IDENTITY_EPHEMERAL_SECRET_GENERATED', {
        bits: 256,
        source: 'crypto.randomBytes(32)',
        warning: 'Set ZYNTHEOR_MASTER_SECRET in environment for cross-reboot persistence.'
      });
    }
  }

  public static getInstance(): SovereignIdentity {
    if (!SovereignIdentity.instance) {
      SovereignIdentity.instance = new SovereignIdentity();
    }
    return SovereignIdentity.instance;
  }

  /**
   * Helper: base64url encode Buffer or string
   */
  private base64UrlEncode(input: Buffer | string): string {
    const buf = typeof input === 'string' ? Buffer.from(input, 'utf8') : input;
    return buf.toString('base64url');
  }

  /**
   * Helper: base64url decode with safety check
   */
  private base64UrlDecode(str: string): Buffer {
    return Buffer.from(str, 'base64url');
  }

  /**
   * Issues a signed sovereign token with strict header, exp, iat, and tenant invariants.
   */
  public signToken(params: {
    sub: string;
    tenantId: string;
    role: SovereignRole;
    ttlSeconds?: number;
    scope?: string[];
  }): { token: string; payload: TokenPayload } {
    const now = Math.floor(Date.now() / 1000);
    const ttl = params.ttlSeconds || 3600; // Default 1 hour TTL

    const header: TokenHeader = {
      alg: 'HS256',
      typ: 'ZY-TOKEN'
    };

    const payload: TokenPayload = {
      sub: params.sub,
      tenantId: params.tenantId,
      role: params.role,
      iat: now,
      exp: now + ttl,
      jti: crypto.randomUUID(),
      scope: params.scope || ['workspace:read', 'workspace:execute']
    };

    const headerB64 = this.base64UrlEncode(JSON.stringify(header));
    const payloadB64 = this.base64UrlEncode(JSON.stringify(payload));
    const signaturePreimage = `${headerB64}.${payloadB64}`;

    const signature = crypto
      .createHmac('sha256', this.masterSecret)
      .update(signaturePreimage)
      .digest();

    const signatureB64 = signature.toString('base64url');
    const token = `${signaturePreimage}.${signatureB64}`;

    AuditLedger.append('COMMERCIAL', 'TOKEN_ISSUED', {
      sub: payload.sub,
      tenantId: payload.tenantId,
      role: payload.role,
      exp: payload.exp,
      jti: payload.jti
    });

    return { token, payload };
  }

  /**
   * Verifies token with constant-time comparison, header verification, expiration checks, and JSON safety.
   */
  public verifyToken(
    rawToken: string,
    options: {
      expectedTenantId?: string;
      requiredRole?: SovereignRole;
      currentTimestamp?: number;
    } = {}
  ): VerificationResult {
    const startTime = Date.now();

    if (!rawToken || typeof rawToken !== 'string') {
      return {
        valid: false,
        code: 'MALFORMED_STRUCTURE',
        reason: 'Token string is empty or missing.',
        latencyMs: Date.now() - startTime
      };
    }

    // 1. Strict 3-part structure check
    const parts = rawToken.split('.');
    if (parts.length !== 3) {
      return {
        valid: false,
        code: 'MALFORMED_STRUCTURE',
        reason: `Expected exactly 3 segments (header.payload.signature), received ${parts.length}.`,
        latencyMs: Date.now() - startTime
      };
    }

    const [headerB64, payloadB64, signatureB64] = parts;
    if (!headerB64 || !payloadB64 || !signatureB64) {
      return {
        valid: false,
        code: 'MALFORMED_STRUCTURE',
        reason: 'One or more token segments are zero-length.',
        latencyMs: Date.now() - startTime
      };
    }

    // 2. Safe Header Parse & Algorithm Validation
    let header: TokenHeader;
    try {
      const headerJson = this.base64UrlDecode(headerB64).toString('utf8');
      header = JSON.parse(headerJson);
    } catch {
      return {
        valid: false,
        code: 'MALFORMED_JSON',
        reason: 'Header is not valid JSON.',
        latencyMs: Date.now() - startTime
      };
    }

    if (header.alg !== 'HS256' || header.typ !== 'ZY-TOKEN') {
      AuditLedger.append('SYSTEM', 'SECURITY_UNSUPPORTED_ALGORITHM_REJECTED', {
        attemptedAlg: header.alg,
        attemptedTyp: header.typ
      });
      return {
        valid: false,
        code: 'UNSUPPORTED_ALGORITHM',
        reason: `Unsupported algorithm or token type. Expected HS256/ZY-TOKEN, got ${header.alg}/${header.typ}.`,
        latencyMs: Date.now() - startTime
      };
    }

    // 3. Constant-Time Cryptographic Signature Check (timingSafeEqual)
    const preimage = `${headerB64}.${payloadB64}`;
    const expectedSignature = crypto
      .createHmac('sha256', this.masterSecret)
      .update(preimage)
      .digest();

    let actualSignature: Buffer;
    try {
      actualSignature = this.base64UrlDecode(signatureB64);
    } catch {
      return {
        valid: false,
        code: 'SIGNATURE_MISMATCH',
        reason: 'Malformed signature encoding.',
        latencyMs: Date.now() - startTime
      };
    }

    // Buffer length must match before timingSafeEqual to avoid RangeError
    if (
      actualSignature.length !== expectedSignature.length ||
      !crypto.timingSafeEqual(actualSignature, expectedSignature)
    ) {
      AuditLedger.append('SYSTEM', 'SECURITY_SIGNATURE_TAMPER_DETECTED', {
        reason: 'Cryptographic HMAC mismatch'
      });
      return {
        valid: false,
        code: 'SIGNATURE_MISMATCH',
        reason: 'HMAC signature verification failed. Token has been tampered with or signed with an untrusted key.',
        latencyMs: Date.now() - startTime
      };
    }

    // 4. Safe Payload Parse
    let payload: TokenPayload;
    try {
      const payloadJson = this.base64UrlDecode(payloadB64).toString('utf8');
      payload = JSON.parse(payloadJson);
    } catch {
      return {
        valid: false,
        code: 'MALFORMED_JSON',
        reason: 'Payload is not valid JSON.',
        latencyMs: Date.now() - startTime
      };
    }

    // 5. Expiration & Temporal Validity
    const now = options.currentTimestamp !== undefined ? options.currentTimestamp : Math.floor(Date.now() / 1000);

    if (typeof payload.exp !== 'number' || payload.exp < now) {
      return {
        valid: false,
        code: 'TOKEN_EXPIRED',
        reason: `Token expired at unix ${payload.exp} (current time is ${now}).`,
        payload,
        latencyMs: Date.now() - startTime
      };
    }

    if (typeof payload.iat !== 'number' || payload.iat > now + 60) {
      return {
        valid: false,
        code: 'TOKEN_NOT_YET_VALID',
        reason: `Token issued in the future (iat: ${payload.iat}, current: ${now}).`,
        payload,
        latencyMs: Date.now() - startTime
      };
    }

    // 6. Tenant Isolation Enforcement
    if (options.expectedTenantId && payload.tenantId !== options.expectedTenantId) {
      AuditLedger.append('SYSTEM', 'SECURITY_CROSS_TENANT_VIOLATION_BLOCKED', {
        tokenTenant: payload.tenantId,
        requestedTenant: options.expectedTenantId,
        sub: payload.sub
      });
      return {
        valid: false,
        code: 'TENANT_MISMATCH',
        reason: `Cross-tenant access forbidden. Token belongs to tenant '${payload.tenantId}', requested resource is in '${options.expectedTenantId}'.`,
        payload,
        latencyMs: Date.now() - startTime
      };
    }

    // 7. Role Authorization Enforcement
    if (options.requiredRole) {
      const tokenLevel = SovereignIdentity.ROLE_HIERARCHY[payload.role] || 0;
      const requiredLevel = SovereignIdentity.ROLE_HIERARCHY[options.requiredRole] || 999;

      if (tokenLevel < requiredLevel) {
        AuditLedger.append('SYSTEM', 'SECURITY_PRIVILEGE_ESCALATION_BLOCKED', {
          sub: payload.sub,
          currentRole: payload.role,
          requiredRole: options.requiredRole
        });
        return {
          valid: false,
          code: 'UNAUTHORIZED_ROLE',
          reason: `Insufficient privileges. Role '${payload.role}' lacks level required for '${options.requiredRole}'.`,
          payload,
          latencyMs: Date.now() - startTime
        };
      }
    }

    return {
      valid: true,
      code: 'VERIFIED',
      reason: 'Token passed all cryptographic, temporal, tenant, and role invariants.',
      payload,
      latencyMs: Date.now() - startTime
    };
  }

  /**
   * Executes the 6-test Sovereign Security Attack Simulation Suite to verify true hardening.
   */
  public runSecuritySimulation(): Array<{
    testId: string;
    attackVector: string;
    simulatedBehavior: string;
    expectedResult: string;
    actualResult: string;
    status: 'PASS' | 'FAIL';
    evidence: string;
  }> {
    const results: Array<{
      testId: string;
      attackVector: string;
      simulatedBehavior: string;
      expectedResult: string;
      actualResult: string;
      status: 'PASS' | 'FAIL';
      evidence: string;
    }> = [];

    // Test 1: Tampered Signature
    const { token: legitToken } = this.signToken({
      sub: 'usr_001',
      tenantId: 'tenant_alpha',
      role: 'developer'
    });
    const tamperedSigToken = legitToken.slice(0, -6) + 'xxxxxx';
    const res1 = this.verifyToken(tamperedSigToken);
    results.push({
      testId: 'SEC-01',
      attackVector: 'Tampered Signature & Bit Flip',
      simulatedBehavior: 'Attacker flips characters in HMAC segment',
      expectedResult: 'SIGNATURE_MISMATCH via crypto.timingSafeEqual()',
      actualResult: res1.code,
      status: res1.code === 'SIGNATURE_MISMATCH' ? 'PASS' : 'FAIL',
      evidence: res1.reason
    });

    // Test 2: Expired Token
    const { token: expiredToken } = this.signToken({
      sub: 'usr_002',
      tenantId: 'tenant_alpha',
      role: 'developer',
      ttlSeconds: -10 // Already expired 10s ago
    });
    const res2 = this.verifyToken(expiredToken);
    results.push({
      testId: 'SEC-02',
      attackVector: 'Expired Token Replay',
      simulatedBehavior: 'Client presents token with exp < now',
      expectedResult: 'TOKEN_EXPIRED rejection',
      actualResult: res2.code,
      status: res2.code === 'TOKEN_EXPIRED' ? 'PASS' : 'FAIL',
      evidence: res2.reason
    });

    // Test 3: Wrong Secret / Untrusted Issuer
    const foreignSecret = crypto.randomBytes(32);
    const header = Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'ZY-TOKEN' })).toString('base64url');
    const body = Buffer.from(JSON.stringify({ sub: 'usr_rogue', tenantId: 'tenant_alpha', role: 'admin', exp: Date.now() + 10000 })).toString('base64url');
    const foreignSig = crypto.createHmac('sha256', foreignSecret).update(`${header}.${body}`).digest('base64url');
    const rogueToken = `${header}.${body}.${foreignSig}`;
    const res3 = this.verifyToken(rogueToken);
    results.push({
      testId: 'SEC-03',
      attackVector: 'Untrusted Secret Key Signature',
      simulatedBehavior: 'Attacker signs token with own external secret',
      expectedResult: 'SIGNATURE_MISMATCH',
      actualResult: res3.code,
      status: res3.code === 'SIGNATURE_MISMATCH' ? 'PASS' : 'FAIL',
      evidence: res3.reason
    });

    // Test 4: Malformed Structure & Injected JSON
    const malformedToken = `eyJhbGciOiJub25lIn0.invalid-json-payload-not-base64.extra-garbage`;
    const res4 = this.verifyToken(malformedToken);
    results.push({
      testId: 'SEC-04',
      attackVector: 'Malformed Structure & None-Alg Injection',
      simulatedBehavior: 'Attacker injects alg:none and malformed JSON',
      expectedResult: 'UNSUPPORTED_ALGORITHM or MALFORMED_JSON',
      actualResult: res4.code,
      status: (res4.code === 'UNSUPPORTED_ALGORITHM' || res4.code === 'MALFORMED_JSON') ? 'PASS' : 'FAIL',
      evidence: res4.reason
    });

    // Test 5: Cross-Tenant Isolation Breach
    const { token: tenantBToken } = this.signToken({
      sub: 'usr_tenant_b',
      tenantId: 'tenant_finance',
      role: 'admin'
    });
    // Attempting to access tenant_health resource
    const res5 = this.verifyToken(tenantBToken, { expectedTenantId: 'tenant_health' });
    results.push({
      testId: 'SEC-05',
      attackVector: 'Cross-Tenant Resource Access',
      simulatedBehavior: 'Admin of Tenant B attempts to read Tenant A private resources',
      expectedResult: 'TENANT_MISMATCH violation blocked',
      actualResult: res5.code,
      status: res5.code === 'TENANT_MISMATCH' ? 'PASS' : 'FAIL',
      evidence: res5.reason
    });

    // Test 6: Privilege Escalation
    const { token: devToken } = this.signToken({
      sub: 'usr_dev',
      tenantId: 'tenant_alpha',
      role: 'developer'
    });
    // Attempting an admin-only operation
    const res6 = this.verifyToken(devToken, { requiredRole: 'admin' });
    results.push({
      testId: 'SEC-06',
      attackVector: 'Privilege Escalation Attempt',
      simulatedBehavior: 'Developer-tier token calls Admin-tier system endpoint',
      expectedResult: 'UNAUTHORIZED_ROLE blocked',
      actualResult: res6.code,
      status: res6.code === 'UNAUTHORIZED_ROLE' ? 'PASS' : 'FAIL',
      evidence: res6.reason
    });

    return results;
  }
}

/**
 * Persistent JTI token revocation list.
 * Fail-closed: if the denylist file is corrupt, treat as empty list but log.
 * Storage: native_data/revoked_jti.jsonl (append-only) + snapshot index.
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { AuditLedger } from './AuditLedger';

const REVOKE_FILE = path.resolve(process.cwd(), 'native_data', 'revoked_jti.jsonl');
const REVOKE_INDEX = path.resolve(process.cwd(), 'native_data', 'revoked_jti_index.json');

export class TokenRevocation {
  private static jtiSet: Set<string> = new Set();
  private static loaded = false;

  private static ensureLoaded(): void {
    if (this.loaded) return;
    const dir = path.dirname(REVOKE_FILE);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });

    // Prefer compact index for fast startup
    if (fs.existsSync(REVOKE_INDEX)) {
      try {
        const list: string[] = JSON.parse(fs.readFileSync(REVOKE_INDEX, 'utf8'));
        this.jtiSet = new Set(list);
        this.loaded = true;
        return;
      } catch {
        /* fall through */
      }
    }

    if (fs.existsSync(REVOKE_FILE)) {
      try {
        const lines = fs.readFileSync(REVOKE_FILE, 'utf8').split('\n').filter(Boolean);
        for (const line of lines) {
          try {
            const rec = JSON.parse(line);
            if (rec.jti) this.jtiSet.add(rec.jti);
          } catch {
            /* skip bad line */
          }
        }
      } catch {
        AuditLedger.append('SYSTEM', 'REVOCATION_LIST_LOAD_ERROR', {
          path: REVOKE_FILE
        });
      }
    }
    this.loaded = true;
  }

  private static persistIndex(): void {
    const dir = path.dirname(REVOKE_INDEX);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    const tmp = REVOKE_INDEX + '.tmp.' + crypto.randomBytes(4).toString('hex');
    fs.writeFileSync(tmp, JSON.stringify([...this.jtiSet]), 'utf8');
    fs.renameSync(tmp, REVOKE_INDEX);
  }

  public static isRevoked(jti: string | undefined | null): boolean {
    if (!jti) return false;
    this.ensureLoaded();
    return this.jtiSet.has(jti);
  }

  public static revoke(jti: string, meta: { sub?: string; reason?: string } = {}): void {
    if (!jti) return;
    this.ensureLoaded();
    if (this.jtiSet.has(jti)) return;
    this.jtiSet.add(jti);
    const dir = path.dirname(REVOKE_FILE);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    const rec = {
      jti,
      revokedAt: new Date().toISOString(),
      sub: meta.sub || null,
      reason: meta.reason || 'manual'
    };
    fs.appendFileSync(REVOKE_FILE, JSON.stringify(rec) + '\n', 'utf8');
    this.persistIndex();
    AuditLedger.append('GOVERNANCE', 'TOKEN_REVOKED', rec);
  }

  public static size(): number {
    this.ensureLoaded();
    return this.jtiSet.size;
  }
}

/**
 * ZYNTHEOR Sovereign ToolGateway
 * Workspace-scoped command gateway with command allowlisting and path traversal defenses.
 * Note: cwd/path controls are not an OS-level sandbox; deploy behind a dedicated isolated runner.
 * All operations logged to AuditLedger.
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { execFile } from 'child_process';
import { AuditLedger } from './AuditLedger';

export interface CommandResult {
  command: string;
  args: string[];
  stdout: string;
  stderr: string;
  exitCode: number;
  durationMs: number;
}

export interface TamperVerificationResult {
  status: 'TAMPER_FREE' | 'TAMPER_DETECTED';
  verifiedAt: string;
  genesisDigest: string;
  executionDigest: string;
  probeDurationMs: number;
  filesAudited: number;
  sandboxPath: string;
  checks: {
    sandboxBoundaryIntact: boolean;
    noopExecutionPassed: boolean;
    genesisStateMatches: boolean;
    noSymlinkEscapes: boolean;
  };
  evidence: string;
}

export interface ZipDeliverableResult {
  zipFilename: string;
  zipPath: string;
  zipBytes: number;
  zipSha256: string;
  integrityOk: boolean;
  includedFiles: string[];
  createdAt: string;
}

export class ToolGateway {
  private static workspaceRoot = path.resolve(process.cwd(), 'workspace');
  private static allowedCommands = new Set([
    'node', 'python3', 'ls', 'cat', 'head', 'pwd', 'echo', 'mkdir', 'find'
  ]);
  private static executionTimeoutMs = 5000;

  public static getWorkspaceRoot(): string {
    if (!fs.existsSync(this.workspaceRoot)) {
      fs.mkdirSync(this.workspaceRoot, { recursive: true });
    }
    return this.workspaceRoot;
  }

  /**
   * Validates that target path stays strictly inside /workspace.
   * Throws an error on path traversal attempts.
   */
  public static resolveSafePath(relativePath: string): string {
    const root = fs.realpathSync(this.getWorkspaceRoot());
    const reject = (reason: string, resolvedPath = ''): never => {
      AuditLedger.append('SYSTEM', 'PATH_TRAVERSAL_BLOCKED', {
        attemptedPath: relativePath,
        resolvedPath,
        sandboxRoot: root,
        reason
      });
      throw new Error(`SECURITY_VIOLATION: ${reason}. Target path '${relativePath}' is outside or crosses a link in the workspace sandbox.`);
    };
    if (typeof relativePath !== 'string' || !relativePath.trim() || path.isAbsolute(relativePath)) {
      return reject('Invalid or absolute workspace path');
    }
    const resolved = path.resolve(root, relativePath);
    const relative = path.relative(root, resolved);
    if (relative === '..' || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
      return reject('Path traversal detected', resolved);
    }

    // Reject symlinks in every existing component, including the leaf. This
    // prevents a path that is lexically inside /workspace from escaping through
    // a symlinked directory or file.
    let cursor = root;
    for (const segment of relative.split(path.sep).filter(Boolean)) {
      cursor = path.join(cursor, segment);
      try {
        const stat = fs.lstatSync(cursor);
        if (stat.isSymbolicLink()) return reject('Symbolic link traversal blocked', cursor);
      } catch (error: any) {
        if (error?.code === 'ENOENT') break;
        if (error?.message?.startsWith('SECURITY_VIOLATION:')) throw error;
        throw error;
      }
    }
    return resolved;
  }

  /**
   * Safely writes a file within /workspace.
   */
  public static writeFile(relativePath: string, content: string): { filePath: string; bytesWritten: number } {
    const safePath = this.resolveSafePath(relativePath);
    const parentDir = path.dirname(safePath);
    if (!fs.existsSync(parentDir)) {
      fs.mkdirSync(parentDir, { recursive: true });
    }
    fs.writeFileSync(safePath, content, 'utf8');
    const bytesWritten = Buffer.byteLength(content, 'utf8');

    AuditLedger.append('CODER', 'TOOL_WRITE_FILE', {
      file: relativePath,
      bytes: bytesWritten
    });

    return { filePath: safePath, bytesWritten };
  }

  /**
   * Safely reads a file from /workspace.
   */
  public static readFile(relativePath: string): string {
    const safePath = this.resolveSafePath(relativePath);
    if (!fs.existsSync(safePath)) {
      throw new Error(`FILE_NOT_FOUND: '${relativePath}' does not exist in workspace.`);
    }
    return fs.readFileSync(safePath, 'utf8');
  }

  /**
   * Safely deletes a file within /workspace.
   */
  public static deleteFile(relativePath: string): boolean {
    const safePath = this.resolveSafePath(relativePath);
    if (!fs.existsSync(safePath)) {
      throw new Error(`FILE_NOT_FOUND: '${relativePath}' does not exist in workspace.`);
    }
    fs.unlinkSync(safePath);
    AuditLedger.append('SYSTEM', 'TOOL_DELETE_FILE', {
      file: relativePath
    });
    return true;
  }

  /**
   * Lists files in /workspace.
   */
  public static listFiles(): string[] {
    const root = this.getWorkspaceRoot();
    const getFiles = (dir: string): string[] => {
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      const files: string[] = [];
      for (const entry of entries) {
        const full = path.join(dir, entry.name);
        if (entry.isSymbolicLink()) {
          continue;
        } else if (entry.isDirectory()) {
          files.push(...getFiles(full));
        } else if (entry.isFile()) {
          files.push(path.relative(root, full));
        }
      }
      return files;
    };
    return getFiles(root);
  }

  /**
   * Executes an allowlisted command with workspace cwd and a 5s timeout. This is not OS isolation.
   */
  public static async runCommand(command: string, args: string[] = []): Promise<CommandResult> {
    if (!this.allowedCommands.has(command)) {
      AuditLedger.append('TESTER', 'COMMAND_REJECTED_WHITELIST', { command, args });
      throw new Error(`SECURITY_VIOLATION: Command '${command}' is not in the sandbox whitelist (${Array.from(this.allowedCommands).join(', ')}).`);
    }

    if (!Array.isArray(args) || args.length > 64 || args.some((arg) => typeof arg !== 'string' || arg.length > 4096)) {
      throw new Error('SECURITY_VIOLATION: Command arguments must be an array of at most 64 strings, each no longer than 4096 characters.');
    }

    const cwd = this.getWorkspaceRoot();
    const startTime = Date.now();

    return new Promise((resolve, reject) => {
      execFile(
        command,
        args,
        {
          cwd,
          timeout: this.executionTimeoutMs,
          maxBuffer: 1024 * 1024,
          // Do not pass server credentials or arbitrary runtime options to generated code.
          env: {
            PATH: process.env.PATH || '',
            HOME: process.env.HOME || cwd,
            TMPDIR: process.env.TMPDIR || process.env.TMP || '/tmp',
            TEMP: process.env.TEMP || process.env.TMP || '/tmp',
            TMP: process.env.TMP || process.env.TEMP || '/tmp',
            SystemRoot: process.env.SystemRoot || '',
            WINDIR: process.env.WINDIR || '',
            LANG: process.env.LANG || 'C.UTF-8',
            LC_ALL: process.env.LC_ALL || '',
            TZ: process.env.TZ || 'UTC',
            NODE_ENV: process.env.NODE_ENV || 'production',
            NODE_PATH: cwd,
            PYTHONPATH: cwd,
            CI: '1'
          }
        },
        (error, stdout, stderr) => {
          const durationMs = Date.now() - startTime;
          const exitCode = error ? (error.code as number || 1) : 0;

          const result: CommandResult = {
            command,
            args,
            stdout: stdout.toString(),
            stderr: stderr.toString() + (error && error.killed ? '\n[Process killed: Execution timed out]' : ''),
            exitCode,
            durationMs
          };

          AuditLedger.append('TESTER', 'TOOL_RUN_COMMAND', {
            command: `${command} ${args.join(' ')}`,
            exitCode,
            durationMs,
            stdoutSummary: result.stdout.slice(0, 150)
          });

          resolve(result);
        }
      );
    });
  }

  /**
   * Runtime Verification Tool:
   * Periodically executes a safe 'no-op' script in the /workspace sandbox
   * and checks the SHA-256 integrity against the known genesis state to ensure
   * the environment hasn't been tampered with.
   */
  public static async runSandboxTamperVerification(): Promise<TamperVerificationResult> {
    const startTime = Date.now();
    const root = this.getWorkspaceRoot();
    const GENESIS_STATE_SPEC = 'ZYNTHEOR_SOVEREIGN_SANDBOX_V1_GENESIS_ROOT';
    const genesisDigest = crypto.createHash('sha256').update(GENESIS_STATE_SPEC).digest('hex');

    const probeFilename = '.sandbox_noop_verify.cjs';
    const probePath = path.join(root, probeFilename);

    const probeScript = `// ZYNTHEOR Sovereign Sandbox Genesis Probe
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const genesisPayload = '${GENESIS_STATE_SPEC}';
const genesisDigest = crypto.createHash('sha256').update(genesisPayload).digest('hex');
const cwd = process.cwd();
const files = fs.readdirSync(cwd).filter(f => !f.startsWith('.sandbox_noop'));

const payload = {
  probe: 'SANDBOX_NOOP_GENESIS_VERIFY',
  genesisDigest: genesisDigest,
  cwdMatches: path.basename(cwd) === 'workspace',
  filesAudited: files.length,
  timestamp: new Date().toISOString()
};

process.stdout.write(JSON.stringify(payload));
`;

    let noopPassed = false;
    let genesisMatches = false;
    let executionDigest = '';
    let filesAudited = 0;
    let evidence = '';
    let noSymlinkEscapes = true;

    try {
      // 1. Check for symlink escapes in workspace
      const entries = fs.readdirSync(root, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isSymbolicLink()) {
          const target = fs.realpathSync(path.join(root, entry.name));
          if (!target.startsWith(root)) {
            noSymlinkEscapes = false;
            evidence += `Illegal symlink escape detected: ${entry.name} -> ${target}; `;
          }
        }
      }

      // 2. Write probe script inside workspace
      fs.writeFileSync(probePath, probeScript, 'utf8');

      // 3. Execute no-op probe
      const execResult = await this.runCommand('node', [probeFilename]);
      const durationMs = Date.now() - startTime;

      if (execResult.exitCode === 0 && execResult.stdout) {
        try {
          const parsed = JSON.parse(execResult.stdout);
          executionDigest = crypto.createHash('sha256').update(execResult.stdout).digest('hex');
          filesAudited = parsed.filesAudited || 0;
          noopPassed = parsed.probe === 'SANDBOX_NOOP_GENESIS_VERIFY' && parsed.cwdMatches === true;
          genesisMatches = parsed.genesisDigest === genesisDigest;
          evidence = `No-op probe verified successfully. Sandbox CWD valid: ${parsed.cwdMatches}. Genesis SHA-256 matched.`;
        } catch (parseErr: any) {
          evidence = `Failed to parse probe stdout: ${parseErr.message}`;
        }
      } else {
        evidence = `Probe execution failed with exit code ${execResult.exitCode}: ${execResult.stderr}`;
      }
    } catch (err: any) {
      evidence = `Sandbox tamper verification error: ${err.message}`;
    } finally {
      // Clean up probe script
      try {
        if (fs.existsSync(probePath)) {
          fs.unlinkSync(probePath);
        }
      } catch {
        // ignore probe unlink error
      }
    }

    const sandboxBoundaryIntact = noSymlinkEscapes && noopPassed;
    const isTamperFree = sandboxBoundaryIntact && genesisMatches;

    const result: TamperVerificationResult = {
      status: isTamperFree ? 'TAMPER_FREE' : 'TAMPER_DETECTED',
      verifiedAt: new Date().toISOString(),
      genesisDigest,
      executionDigest,
      probeDurationMs: Date.now() - startTime,
      filesAudited,
      sandboxPath: root,
      checks: {
        sandboxBoundaryIntact,
        noopExecutionPassed: noopPassed,
        genesisStateMatches: genesisMatches,
        noSymlinkEscapes
      },
      evidence
    };

    // Log verification to AuditLedger
    AuditLedger.append('GOVERNANCE', 'SANDBOX_TAMPER_VERIFICATION', {
      status: result.status,
      genesisDigest: result.genesisDigest,
      executionDigest: result.executionDigest,
      checks: result.checks,
      durationMs: result.probeDurationMs
    });

    return result;
  }

  /**
   * Captures a reversible atomic snapshot of a workspace file inside `.zyntheor/snapshots/<id>.json`.
   */
  public static snapshotFile(relativePath: string): { snapshotId: string; filePath: string; bytes: number } {
    const safePath = this.resolveSafePath(relativePath);
    if (!fs.existsSync(safePath)) {
      throw new Error(`FILE_NOT_FOUND: Cannot snapshot missing workspace file '${relativePath}'.`);
    }
    const content = fs.readFileSync(safePath, 'utf8');
    const root = this.getWorkspaceRoot();
    const snapshotsDir = path.join(root, '.zyntheor', 'snapshots');
    fs.mkdirSync(snapshotsDir, { recursive: true });
    const snapshotId = `snap_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;
    const snapFile = path.join(snapshotsDir, `${snapshotId}.json`);
    const payload = {
      snapshotId,
      relativePath,
      sha256: crypto.createHash('sha256').update(content, 'utf8').digest('hex'),
      createdAt: new Date().toISOString(),
      content,
    };
    fs.writeFileSync(snapFile, JSON.stringify(payload), { encoding: 'utf8', flag: 'wx' });
    AuditLedger.append('SYSTEM', 'TOOL_SNAPSHOT_CREATED', { snapshotId, file: relativePath, bytes: Buffer.byteLength(content, 'utf8') });
    return { snapshotId, filePath: snapFile, bytes: Buffer.byteLength(content, 'utf8') };
  }

  /**
   * Restores a previously snapshotted workspace file atomically.
   */
  public static rollbackSnapshot(snapshotId: string): { snapshotId: string; restoredPath: string; sha256: string } {
    if (typeof snapshotId !== 'string' || !/^[A-Za-z0-9_-]{6,80}$/.test(snapshotId)) {
      throw new Error('SECURITY_VIOLATION: Invalid snapshot identifier.');
    }
    const root = this.getWorkspaceRoot();
    const snapFile = path.join(root, '.zyntheor', 'snapshots', `${snapshotId}.json`);
    if (!fs.existsSync(snapFile)) {
      throw new Error(`SNAPSHOT_NOT_FOUND: '${snapshotId}' does not exist.`);
    }
    const snap = JSON.parse(fs.readFileSync(snapFile, 'utf8'));
    if (typeof snap?.relativePath !== 'string' || typeof snap?.content !== 'string') {
      throw new Error(`CORRUPT_SNAPSHOT: '${snapshotId}' payload invalid.`);
    }
    const safeTarget = this.resolveSafePath(snap.relativePath);
    fs.mkdirSync(path.dirname(safeTarget), { recursive: true });
    fs.writeFileSync(safeTarget, snap.content, 'utf8');
    AuditLedger.append('SYSTEM', 'TOOL_SNAPSHOT_ROLLBACK', { snapshotId, file: snap.relativePath, sha256: snap.sha256 });
    return { snapshotId, restoredPath: snap.relativePath, sha256: snap.sha256 };
  }

  /**
   * Packages verified workspace files into an independently integrity-checked ZIP deliverable under native_data/deliverables/.
   */
  public static async createZipDeliverable(relativePaths: string[], zipFilename: string): Promise<ZipDeliverableResult> {
    if (!Array.isArray(relativePaths) || relativePaths.length === 0) {
      throw new Error('INVALID_DELIVERABLE: relativePaths must contain at least one file.');
    }
    const cleanName = path.basename(String(zipFilename || `deliverable-${Date.now()}.zip`).trim()).replace(/[^A-Za-z0-9._-]/g, '_');
    const finalName = cleanName.endsWith('.zip') ? cleanName : `${cleanName}.zip`;
    const deliverablesDir = path.resolve(process.cwd(), 'native_data', 'deliverables');
    fs.mkdirSync(deliverablesDir, { recursive: true });
    const outZipPath = path.resolve(deliverablesDir, finalName);
    if (!outZipPath.startsWith(deliverablesDir + path.sep)) {
      throw new Error('SECURITY_VIOLATION: Deliverable path escapes native_data/deliverables.');
    }

    const root = fs.realpathSync(this.getWorkspaceRoot());
    const resolvedEntries: Array<{ rel: string; full: string }> = [];
    for (const rel of relativePaths) {
      const normalizedRel = String(rel).replace(/^\/+/, '');
      const full = this.resolveSafePath(normalizedRel);
      if (!fs.existsSync(full) || !fs.statSync(full).isFile()) {
        throw new Error(`FILE_NOT_FOUND: Deliverable member '${normalizedRel}' missing from workspace.`);
      }
      resolvedEntries.push({ rel: path.relative(root, full).split(path.sep).join('/'), full });
    }

    const pyScript = `
import hashlib, json, sys, zipfile, os
out_zip = sys.argv[1]
entries = json.loads(sys.argv[2])
with zipfile.ZipFile(out_zip, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
    for e in entries:
        zf.write(e['full'], e['rel'])
with zipfile.ZipFile(out_zip, 'r') as zf:
    bad = zf.testzip()
    names = zf.namelist()
with open(out_zip, 'rb') as f:
    digest = hashlib.sha256(f.read()).hexdigest()
print(json.dumps({
    'integrityOk': bad is None and len(names) == len(entries),
    'zipBytes': os.path.getsize(out_zip),
    'zipSha256': digest,
    'includedFiles': names
}))
`;

    const meta = await new Promise<{ integrityOk: boolean; zipBytes: number; zipSha256: string; includedFiles: string[] }>((resolve, reject) => {
      execFile(
        'python3',
        ['-I', '-c', pyScript, outZipPath, JSON.stringify(resolvedEntries)],
        { cwd: process.cwd(), timeout: 10000, maxBuffer: 1024 * 1024 },
        (err, stdout, stderr) => {
          if (err) {
            return reject(new Error(`ZIP_BUILD_FAILED: ${stderr || err.message}`));
          }
          try {
            resolve(JSON.parse(stdout.trim()));
          } catch (parseErr: any) {
            reject(new Error(`ZIP_PARSE_FAILED: ${parseErr.message}`));
          }
        }
      );
    });

    const result: ZipDeliverableResult = {
      zipFilename: finalName,
      zipPath: outZipPath,
      zipBytes: meta.zipBytes,
      zipSha256: meta.zipSha256,
      integrityOk: meta.integrityOk,
      includedFiles: meta.includedFiles,
      createdAt: new Date().toISOString(),
    };

    AuditLedger.append('SYSTEM', 'DELIVERABLE_ZIP_CREATED', {
      zipFilename: finalName,
      zipBytes: result.zipBytes,
      zipSha256: result.zipSha256,
      integrityOk: result.integrityOk,
      fileCount: result.includedFiles.length,
    });

    return result;
  }
}

/**
 * Shared knowledge utilities — no imports from Workspace/Engine (breaks cycles).
 */
import crypto from 'crypto';

export function detectLang(text: string): 'th' | 'en' | 'mixed' {
  const thai = (text.match(/[\u0E00-\u0E7F]/g) || []).length;
  const latin = (text.match(/[a-zA-Z]/g) || []).length;
  if (thai > 0 && latin > 0) return 'mixed';
  if (thai > latin) return 'th';
  return 'en';
}

export function semanticChunk(
  text: string,
  opts: { targetSize?: number; maxSize?: number; overlap?: number } = {}
): string[] {
  const target = opts.targetSize ?? 500;
  const maxSize = opts.maxSize ?? 900;
  const overlap = opts.overlap ?? 80;
  const paragraphs = text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
  const units: string[] = [];

  for (const para of paragraphs) {
    if (para.length <= maxSize) {
      units.push(para);
    } else {
      const sentences = para.split(/(?<=[\.\!\?\u0E2F])\s+|\n+/).filter((s) => s.trim());
      let buf = '';
      for (const s of sentences) {
        if ((buf + ' ' + s).trim().length > maxSize && buf) {
          units.push(buf.trim());
          buf = s;
        } else {
          buf = buf ? `${buf} ${s}` : s;
        }
      }
      if (buf.trim()) units.push(buf.trim());
    }
  }

  const merged: string[] = [];
  let acc = '';
  for (const u of units) {
    if (!acc) {
      acc = u;
      continue;
    }
    if ((acc + '\n\n' + u).length <= target + 150) {
      acc = `${acc}\n\n${u}`;
    } else {
      merged.push(acc);
      const tail = acc.slice(-overlap);
      acc = tail && u.length + tail.length < maxSize ? `${tail}\n${u}` : u;
    }
  }
  if (acc) merged.push(acc);
  return merged.length > 0 ? merged : text.trim() ? [text.trim()] : [];
}

export function contentHash(text: string): string {
  return crypto.createHash('sha256').update(text, 'utf8').digest('hex');
}

export function normalizeIntegrityText(text: string): string {
  return String(text || '')
    .toLowerCase()
    .replace(/\r\n/g, '\n')
    .replace(/\s+/g, ' ')
    .trim();
}

# -*- coding: utf-8 -*-
"""Shared fail-closed gate for NativeLM training entrypoints."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict, Mapping, Optional

from qplus_native.dataset_governance import validate_manifest
from qplus_native.trusted_approvals import load_hmac_verifier

def validate_training_readiness(
    provenance_manifest_path: str,
    evidence_root: str,
    approval_key_file: Optional[str],
    frozen_documents: Mapping[str, Mapping[str, Any]],
) -> Dict[str, Any]:
    """Validate provenance records against frozen docs and their exact split assignments.

    `frozen_documents` maps document IDs to {text, split}; split may be train/val/validation/test.
    A trusted key is mandatory to produce VERIFIED. This function never writes artifacts.
    """
    if not Path(provenance_manifest_path).is_file():
        return {"status": "BLOCKED", "issues": ["dataset_provenance_manifest_missing"], "documents": []}
    if not approval_key_file or not Path(approval_key_file).is_file():
        return {"status": "BLOCKED", "issues": ["trusted_approval_key_missing"], "documents": []}
    try:
        manifest = json.loads(Path(provenance_manifest_path).read_text(encoding="utf-8"))
        verifier = load_hmac_verifier(approval_key_file)
    except Exception as exc:
        return {"status": "BLOCKED", "issues": [f"manifest_or_trust_key_invalid:{type(exc).__name__}"], "documents": []}

    texts = {doc_id: str(value.get("text", "")) for doc_id, value in frozen_documents.items()}
    result = validate_manifest(manifest, texts, evidence_root, verifier)
    issues = list(result.get("issues", []))
    declared = {r.get("document_id"): r for r in manifest.get("documents", []) if isinstance(r, dict)}
    for doc_id, frozen in frozen_documents.items():
        record = declared.get(doc_id)
        if record is None:
            issues.append(f"frozen_document_missing_from_provenance:{doc_id}")
            continue
        fsplit = "validation" if frozen.get("split") == "val" else frozen.get("split")
        if record.get("split") != fsplit:
            issues.append(f"frozen_split_mismatch:{doc_id}")
    if not any(r.get("split") == "test" for r in manifest.get("documents", []) if isinstance(r, dict)):
        issues.append("test_split_missing")
    if issues or result.get("status") != "VERIFIED":
        result["status"] = "BLOCKED"
    result["issues"] = issues
    result["test_documents_excluded_from_training"] = True
    return result

# -*- coding: utf-8 -*-
"""Hardened HMAC-SHA256 Sovereign Token verification & signing for Python runtime."""
from __future__ import annotations

import base64
import hashlib
import hmac
import json
import math
import os
import re
import time
import uuid
from typing import Any, Mapping, Sequence

MAX_TOKEN_LENGTH = 4096
MIN_SECRET_BYTES = 32
DEFAULT_CLOCK_SKEW_SECONDS = 30

ROLE_HIERARCHY: dict[str, int] = {
    "guest": 1,
    "developer": 2,
    "operator": 3,
    "auditor": 4,
    "admin": 5,
}

_BASE64URL_RE = re.compile(r"^[A-Za-z0-9_-]+$")

class SovereignTokenError(ValueError):
    """Raised when a sovereign HMAC token fails cryptographic or policy validation."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code

def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

def _b64url_decode(segment: str) -> bytes:
    if not segment or not _BASE64URL_RE.fullmatch(segment):
        raise SovereignTokenError("MALFORMED_STRUCTURE", "Segment is not valid base64url.")
    padding = "=" * ((4 - len(segment) % 4) % 4)
    try:
        return base64.urlsafe_b64decode(segment + padding)
    except Exception as exc:
        raise SovereignTokenError("MALFORMED_STRUCTURE", "Failed to base64url-decode segment.") from exc

def _resolve_secret(secret: str | bytes | None) -> bytes:
    raw = secret
    if raw is None:
        raw = os.environ.get("ZYNTHEOR_TOKEN_SECRET") or os.environ.get("ZYNTHEOR_MASTER_SECRET")
    if raw is None:
        raise SovereignTokenError("MISSING_SECRET", "Token secret is not configured.")
    secret_bytes = raw.strip().encode("utf-8") if isinstance(raw, str) else bytes(raw)
    if not secret_bytes:
        raise SovereignTokenError("MISSING_SECRET", "Token secret is empty.")
    if len(secret_bytes) < MIN_SECRET_BYTES:
        raise SovereignTokenError(
            "WEAK_SECRET",
            f"Token secret must be at least {MIN_SECRET_BYTES} bytes (got {len(secret_bytes)}).",
        )
    return secret_bytes

def constant_time_str_equal(a: str, b: str) -> bool:
    return hmac.compare_digest(a.encode("utf-8"), b.encode("utf-8"))

def _is_finite_number(value: Any) -> bool:
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(float(value))
    )

def sign_hmac_token(
    *,
    sub: str,
    tenant_id: str,
    role: str,
    secret: str | bytes | None = None,
    ttl_seconds: int = 3600,
    now_seconds: float | None = None,
    jti: str | None = None,
    scope: Sequence[str] | None = None,
) -> str:
    secret_bytes = _resolve_secret(secret)
    if not isinstance(sub, str) or not sub:
        raise SovereignTokenError("INVALID_CLAIMS", "sub must be a non-empty string.")
    if not isinstance(tenant_id, str) or not tenant_id:
        raise SovereignTokenError("INVALID_CLAIMS", "tenantId must be a non-empty string.")
    if not isinstance(role, str) or role not in ROLE_HIERARCHY:
        raise SovereignTokenError("INVALID_CLAIMS", f"Unsupported role: {role!r}")

    now = int(time.time()) if now_seconds is None else int(now_seconds)
    header = {"alg": "HS256", "typ": "ZY-TOKEN"}
    payload: dict[str, Any] = {
        "sub": sub,
        "tenantId": tenant_id,
        "role": role,
        "iat": now,
        "exp": now + int(ttl_seconds),
        "jti": jti or str(uuid.uuid4()),
    }
    if scope is not None:
        payload["scope"] = list(scope)

    header_b64 = _b64url_encode(json.dumps(header, separators=(",", ":")).encode("utf-8"))
    payload_b64 = _b64url_encode(json.dumps(payload, separators=(",", ":")).encode("utf-8"))
    preimage = f"{header_b64}.{payload_b64}"
    sig = hmac.new(secret_bytes, preimage.encode("ascii"), hashlib.sha256).digest()
    return f"{preimage}.{_b64url_encode(sig)}"

def verify_hmac_token(
    token: str,
    *,
    secret: str | bytes | None = None,
    expected_tenant_id: str | None = None,
    required_role: str | None = None,
    now_seconds: float | None = None,
    clock_skew_seconds: float = DEFAULT_CLOCK_SKEW_SECONDS,
    max_token_length: int = MAX_TOKEN_LENGTH,
) -> dict[str, Any]:
    """Verify an HS256 ZY-TOKEN using Verify-Before-Parse and constant-time checks."""
    if not isinstance(token, str) or not token:
        raise SovereignTokenError("MALFORMED_STRUCTURE", "Token string is empty or missing.")

    # 1. DoS Protection: limit max token length before splitting, decoding, or hashing.
    if len(token) > max_token_length:
        raise SovereignTokenError(
            "TOKEN_TOO_LONG",
            f"Token length {len(token)} exceeds maximum allowed {max_token_length}.",
        )

    # 2. Fail-closed secret check (>= 32 bytes).
    secret_bytes = _resolve_secret(secret)

    # 3. Strict 3-segment structure check.
    parts = token.split(".")
    if len(parts) != 3:
        raise SovereignTokenError(
            "MALFORMED_STRUCTURE",
            f"Expected 3 segments (header.payload.signature), got {len(parts)}.",
        )
    header_b64, payload_b64, signature_b64 = parts
    if (
        not header_b64
        or not payload_b64
        or not signature_b64
        or not _BASE64URL_RE.fullmatch(header_b64)
        or not _BASE64URL_RE.fullmatch(payload_b64)
        or not _BASE64URL_RE.fullmatch(signature_b64)
    ):
        raise SovereignTokenError("MALFORMED_STRUCTURE", "Token contains empty or invalid base64url segments.")

    # 4. Verify-Before-Parse: validate HMAC-SHA256 over exact raw preimage BEFORE json.loads.
    preimage = f"{header_b64}.{payload_b64}".encode("ascii")
    expected_sig = hmac.new(secret_bytes, preimage, hashlib.sha256).digest()
    actual_sig = _b64url_decode(signature_b64)

    if (
        _b64url_encode(actual_sig) != signature_b64
        or len(actual_sig) != len(expected_sig)
        or not hmac.compare_digest(actual_sig, expected_sig)
    ):
        raise SovereignTokenError("SIGNATURE_MISMATCH", "HMAC-SHA256 signature verification failed.")

    # 5. Safe header parsing & algorithm validation.
    try:
        header_obj = json.loads(_b64url_decode(header_b64).decode("utf-8"))
    except Exception as exc:
        raise SovereignTokenError("MALFORMED_JSON", "Header is not valid JSON.") from exc

    if not isinstance(header_obj, Mapping) or header_obj.get("alg") != "HS256" or header_obj.get("typ") != "ZY-TOKEN":
        raise SovereignTokenError("UNSUPPORTED_ALGORITHM", "Unsupported header alg or typ.")

    # 6. Safe payload parsing & strict claim type validation.
    try:
        payload_obj = json.loads(_b64url_decode(payload_b64).decode("utf-8"))
    except Exception as exc:
        raise SovereignTokenError("MALFORMED_JSON", "Payload is not valid JSON.") from exc

    if not isinstance(payload_obj, dict):
        raise SovereignTokenError("MALFORMED_JSON", "Payload must be a JSON object.")

    sub = payload_obj.get("sub")
    tenant_id = payload_obj.get("tenantId")
    role = payload_obj.get("role")
    exp = payload_obj.get("exp")
    iat = payload_obj.get("iat")

    if not isinstance(sub, str) or not sub:
        raise SovereignTokenError("INVALID_CLAIMS", "Claim 'sub' must be a non-empty string.")
    if not isinstance(tenant_id, str) or not tenant_id:
        raise SovereignTokenError("INVALID_CLAIMS", "Claim 'tenantId' must be a non-empty string.")
    if not isinstance(role, str) or role not in ROLE_HIERARCHY:
        raise SovereignTokenError("INVALID_CLAIMS", "Claim 'role' is missing or invalid.")
    if not _is_finite_number(exp):
        raise SovereignTokenError("INVALID_CLAIMS", "Claim 'exp' must be a finite number.")
    if iat is not None and not _is_finite_number(iat):
        raise SovereignTokenError("INVALID_CLAIMS", "Claim 'iat' must be a finite number.")

    # 7. Expiration & clock skew leeway (default 30s).
    now = time.time() if now_seconds is None else float(now_seconds)
    if float(exp) + float(clock_skew_seconds) <= now:
        raise SovereignTokenError("TOKEN_EXPIRED", f"Token expired at {exp} (now={now}).")
    if iat is not None and float(iat) - float(clock_skew_seconds) > now:
        raise SovereignTokenError("TOKEN_NOT_YET_VALID", f"Token issued in the future (iat={iat}, now={now}).")

    # 8. Constant-time tenant isolation check.
    if expected_tenant_id is not None and not constant_time_str_equal(tenant_id, expected_tenant_id):
        raise SovereignTokenError(
            "TENANT_MISMATCH",
            f"Cross-tenant token rejected: expected '{expected_tenant_id}'.",
        )

    # 9. Role authorization check.
    if required_role is not None:
        if ROLE_HIERARCHY[role] < ROLE_HIERARCHY.get(required_role, 999):
            raise SovereignTokenError(
                "UNAUTHORIZED_ROLE",
                f"Role '{role}' lacks required privilege '{required_role}'.",
            )

    return payload_obj

/**
 * ZYNTHEOR Batch 29 — Adaptive Reasoning Architecture
 *
 * Selects, executes, verifies, and revises reasoning strategies dynamically per task class
 * without exposing raw internal reasoning chains to end users.
 *
 * Strictly distinguishes:
 *  - Deterministic & symbolic verification (`qplus_native/batch28_reasoning.py`)
 *  - Grounded knowledge & multi-hop graph evidence (`KnowledgeIntelligenceEngine` + `KnowledgeGraphEngine`)
 *  - Native Model neural status (never fabricated when cloud checkpoint is unconfigured)
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { execFile } from 'child_process';
import { AuditLedger } from './AuditLedger.ts';
import { CognitiveContextEngine, ContextAnalysisResult } from './CognitiveContextEngine.ts';
import { KnowledgeIntelligenceEngine } from './KnowledgeIntelligenceEngine.ts';
import { KnowledgeGraphEngine } from './KnowledgeGraphEngine.ts';
import { PerformanceEngine } from './PerformanceEngine.ts';
import { ConnectivityMonitor } from './ConnectivityMonitor.ts';
import {
  classifyTruthClaim,
  enforceTruthClaims,
  summarizeTruthClaims,
  type TruthClaimRecord,
  type TruthKernelSummary,
} from './TruthKernel.ts';

export type ProblemClass =
  | 'deterministic_symbolic'
  | 'constraint_csp'
  | 'code_verification'
  | 'multi_hop_rag'
  | 'bilingual_generation'
  | 'hybrid_execution';

export type ReasoningStrategyId =
  | 'symbolic_math_verifier'
  | 'csp_dependency_solver'
  | 'ast_code_inspector'
  | 'multi_hop_graph_rag'
  | 'multi_path_synthesis'
  | 'native_lm_guarded';

export interface ReasoningHypothesis {
  hypothesisId: string;
  strategy: ReasoningStrategyId;
  summary: string;
  evidenceRefs: Array<{ documentId: string; title: string; contentHash: string }>;
  constraintsChecked: string[];
  counterexampleTested: boolean;
  counterexamplePassed: boolean;
  counterexampleDetail?: string;
  verifierPassed: boolean;
  score: number;
}

export interface AdaptiveReasoningOutcome {
  reasoningId: string;
  timestamp: string;
  problemClass: ProblemClass;
  selectedStrategy: ReasoningStrategyId;
  revisedToStrategy?: ReasoningStrategyId;
  revisionReason?: string;
  contextAnalysis: {
    contextId: string;
    intent: ContextAnalysisResult['intent']['primary'];
    language: ContextAnalysisResult['language'];
    conflictsDetected: number;
    attribution: ContextAnalysisResult['attribution'];
  };
  constraints: string[];
  hypothesesEvaluated: number;
  winningHypothesis: ReasoningHypothesis;
  uncertainty: {
    calibratedConfidence: number;
    epistemicUncertainty: number;
    abstentionRecommended: boolean;
    reason?: string;
  };
  /** Public summary only; raw intermediate trace redacted via SHA-256 digest */
  reasoningMetadata: {
    traceDigestSha256: string;
    redactedPrivateTrace: true;
    verifierAttribution: string;
    nativeNeuralState: string;
    durationMs: number;
  };
  answerSummary: string;
  verified: boolean;
  truthClaims: TruthClaimRecord[];
  truthSummary: TruthKernelSummary;
}

export interface IndependentBenchmarkCase {
  caseId: string;
  problemClass: ProblemClass;
  prompt: string;
  mathSteps?: Array<{ expr: string; claimed?: number }>;
  expectedFinal?: number;
  pythonSource?: string;
  cspTasks?: Array<{ id: string; depends_on?: string[]; cost?: number; priority?: number }>;
  maxCost?: number;
  expectSatisfiable?: boolean;
  expectSyntaxValid?: boolean;
  expectSafe?: boolean;
  expectAbstain?: boolean;
}

const TRACE_LOG_FILE = () =>
  process.env.ZYNTHEOR_REASONING_LOG
    ? path.resolve(process.env.ZYNTHEOR_REASONING_LOG)
    : path.resolve(process.cwd(), 'native_data', 'adaptive_reasoning_history.json');

export class AdaptiveReasoningEngine {
  private static instance: AdaptiveReasoningEngine | null = null;
  private history: AdaptiveReasoningOutcome[] = [];

  private constructor() {
    this.loadHistory();
  }

  public static getInstance(): AdaptiveReasoningEngine {
    if (!AdaptiveReasoningEngine.instance) {
      AdaptiveReasoningEngine.instance = new AdaptiveReasoningEngine();
    }
    return AdaptiveReasoningEngine.instance;
  }

  private loadHistory(): void {
    try {
      const f = TRACE_LOG_FILE();
      if (!fs.existsSync(f)) return;
      const parsed = JSON.parse(fs.readFileSync(f, 'utf8'));
      if (Array.isArray(parsed)) this.history = parsed.slice(0, 100);
    } catch {
      this.history = [];
    }
  }

  private saveHistory(): void {
    const f = TRACE_LOG_FILE();
    const dir = path.dirname(f);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(f, JSON.stringify(this.history.slice(0, 100), null, 2), 'utf8');
  }

  public classifyProblem(
    prompt: string,
    hints?: {
      hasMathSteps?: boolean;
      hasCspTasks?: boolean;
      hasPythonSource?: boolean;
      preferBilingual?: boolean;
    }
  ): ProblemClass {
    if (hints?.hasMathSteps) return 'deterministic_symbolic';
    if (hints?.hasCspTasks) return 'constraint_csp';
    if (hints?.hasPythonSource) return 'code_verification';

    const ctx = CognitiveContextEngine.getInstance().analyzeContext({ input: prompt });
    switch (ctx.intent.primary) {
      case 'math_reasoning':
        return 'deterministic_symbolic';
      case 'planning':
        return /\b(budget|cost|dependenc|cycle|constraint|งบประมาณ|เงื่อนไข)\b/i.test(prompt)
          ? 'constraint_csp'
          : 'hybrid_execution';
      case 'coding':
      case 'debugging':
        return 'code_verification';
      case 'bilingual_translation':
        return 'bilingual_generation';
      case 'knowledge_qa':
      case 'security_audit':
        return 'multi_hop_rag';
      default:
        return 'hybrid_execution';
    }
  }

  public selectStrategy(problemClass: ProblemClass, hasStructuredVerifierInput = false): ReasoningStrategyId {
    const baseMap: Record<ProblemClass, ReasoningStrategyId> = {
      deterministic_symbolic: 'symbolic_math_verifier',
      constraint_csp: 'csp_dependency_solver',
      code_verification: 'ast_code_inspector',
      multi_hop_rag: 'multi_hop_graph_rag',
      bilingual_generation: 'native_lm_guarded',
      hybrid_execution: 'multi_path_synthesis',
    };

    const primary = baseMap[problemClass];
    if (hasStructuredVerifierInput) {
      return primary;
    }
    // Consult PerformanceEngine strategy track record for open-ended strategies
    const perfStats = PerformanceEngine.getInstance().compareStrategies();
    const primaryStat = perfStats.find((s) => s.strategy === primary);
    if (primaryStat && primaryStat.calls >= 3 && primaryStat.successRatePct < 50) {
      return problemClass === 'bilingual_generation' ? 'multi_hop_graph_rag' : 'multi_path_synthesis';
    }
    return primary;
  }

  private async runPythonVerifier(payload: Record<string, unknown>): Promise<any> {
    const script = path.resolve(process.cwd(), 'qplus_native', 'batch28_reasoning.py');
    return new Promise((resolve, reject) => {
      const proc = execFile('python3', ['-B', script], { cwd: process.cwd(), timeout: 8000 }, (err, stdout, stderr) => {
        if (err && !stdout.trim()) return reject(new Error(stderr || err.message));
        try {
          resolve(JSON.parse(stdout.trim()));
        } catch (parseErr: any) {
          reject(new Error(`Invalid Python verifier JSON: ${parseErr.message}`));
        }
      });
      proc.stdin?.write(JSON.stringify(payload));
      proc.stdin?.end();
    });
  }

  public async executeReasoning(params: {
    prompt: string;
    scope?: { tenantId?: string; userId?: string; role?: string };
    mathSteps?: Array<{ expr: string; claimed?: number }>;
    expectedFinal?: number;
    cspTasks?: Array<{ id: string; depends_on?: string[]; cost?: number; priority?: number }>;
    maxCost?: number;
    pythonSource?: string;
    maxHops?: number;
  }): Promise<AdaptiveReasoningOutcome> {
    const perf = PerformanceEngine.getInstance();
    const tenantId = params.scope?.tenantId || 'default-tenant';

    const ctx = CognitiveContextEngine.getInstance().analyzeContext({ input: params.prompt });
    const hasStructured = Boolean(
      params.mathSteps?.length || params.cspTasks?.length || params.pythonSource?.trim()
    );
    const problemClass = this.classifyProblem(params.prompt, {
      hasMathSteps: Boolean(params.mathSteps?.length),
      hasCspTasks: Boolean(params.cspTasks?.length),
      hasPythonSource: Boolean(params.pythonSource?.trim()),
    });
    const selectedStrategy = this.selectStrategy(problemClass, hasStructured);

    const conn = await ConnectivityMonitor.getInstance().getStatus();
    const constraints = ctx.segments.filter((s) => s.kind === 'constraint').map((s) => s.text.slice(0, 140));
    const hypotheses: ReasoningHypothesis[] = [];
    const internalTraceSteps: string[] = [
      `problemClass=${problemClass}`,
      `selectedStrategy=${selectedStrategy}`,
      `contextConflicts=${ctx.conflicts.length}`,
    ];

    const profiled = await perf.profileAsync(
      { operation: 'adaptive_reasoning', strategy: selectedStrategy, tenantId },
      async () => {
        let verified = false;
        let revisedToStrategy: ReasoningStrategyId | undefined;
        let revisionReason: string | undefined;
        let answerSummary = '';
        let verifierAttribution = 'adaptive_orchestrator';

        // Hypothesis 1: Primary strategy execution
        if (selectedStrategy === 'symbolic_math_verifier' && params.mathSteps?.length) {
          const pyRes = await this.runPythonVerifier({
            op: 'verify_math',
            steps: params.mathSteps,
            expected_final: params.expectedFinal,
          });
          // Counterexample test: negate expectedFinal if present and ensure verifier rejects false claim
          const counterRes = await this.runPythonVerifier({
            op: 'verify_math',
            steps: params.mathSteps,
            expected_final: (pyRes.final_value ?? 0) + 999.123,
          });
          const counterPassed = counterRes.verified === false;
          verified = Boolean(pyRes.verified && counterPassed);
          verifierAttribution = pyRes.attribution || 'symbolic_math_ast_verifier';
          answerSummary = verified
            ? `Symbolic AST verification passed: final_value=${pyRes.final_value} across ${pyRes.steps?.length || 0} step(s).`
            : `Symbolic AST verification failed: ${pyRes.steps?.find((s: any) => !s.valid)?.error || 'Expected mismatch'}.`;
          hypotheses.push({
            hypothesisId: 'hyp_symbolic_1',
            strategy: 'symbolic_math_verifier',
            summary: answerSummary,
            evidenceRefs: [],
            constraintsChecked: constraints,
            counterexampleTested: true,
            counterexamplePassed: counterPassed,
            counterexampleDetail: 'Injected perturbed target (+999.123); verifier rejected false claim cleanly.',
            verifierPassed: Boolean(pyRes.verified),
            score: verified ? 0.96 : 0.25,
          });
          internalTraceSteps.push(`symbolic_verified=${pyRes.verified} final=${pyRes.final_value}`);
        } else if (selectedStrategy === 'csp_dependency_solver' && params.cspTasks?.length) {
          const pyRes = await this.runPythonVerifier({
            op: 'solve_constraints',
            tasks: params.cspTasks,
            max_total_cost: params.maxCost ?? 100,
          });
          // Counterexample test: impossibly tight budget (0.0001) when total cost > 0 must yield satisfiable=false
          const tightBudget = (pyRes.total_cost || 1) > 0.01 ? 0.0001 : -1;
          const counterRes = await this.runPythonVerifier({
            op: 'solve_constraints',
            tasks: params.cspTasks,
            max_total_cost: tightBudget,
          });
          const counterPassed = counterRes.satisfiable === false;
          verified = Boolean(pyRes.satisfiable && counterPassed);
          verifierAttribution = pyRes.attribution || 'deterministic_csp_scheduler';
          answerSummary = pyRes.satisfiable
            ? `Constraint solver found valid DAG schedule [${(pyRes.schedule || []).join(' -> ')}] (cost=${pyRes.total_cost}).`
            : `Constraint system unsatisfiable: ${pyRes.reason}.`;
          hypotheses.push({
            hypothesisId: 'hyp_csp_1',
            strategy: 'csp_dependency_solver',
            summary: answerSummary,
            evidenceRefs: [],
            constraintsChecked: [`max_total_cost=${params.maxCost ?? 100}`, ...constraints],
            counterexampleTested: true,
            counterexamplePassed: counterPassed,
            counterexampleDetail: 'Tight budget counterexample cleanly rejected as unsatisfiable.',
            verifierPassed: Boolean(pyRes.satisfiable),
            score: pyRes.satisfiable ? 0.94 : 0.45,
          });
          internalTraceSteps.push(`csp_satisfiable=${pyRes.satisfiable} reason=${pyRes.reason || 'ok'}`);
        } else if (selectedStrategy === 'ast_code_inspector' && params.pythonSource?.trim()) {
          const pyRes = await this.runPythonVerifier({
            op: 'reason_code',
            source: params.pythonSource,
          });
          // Counterexample: inject syntax defect to confirm AST verifier catches broken code
          const counterRes = await this.runPythonVerifier({
            op: 'reason_code',
            source: 'def broken(:\n  pass',
          });
          const counterPassed = counterRes.syntax_valid === false;
          verified = Boolean(pyRes.syntax_valid && pyRes.safe && counterPassed);
          verifierAttribution = pyRes.attribution || 'ast_code_reasoning';
          answerSummary = verified
            ? `Python AST verified safe & syntactically valid (functions: ${(pyRes.functions || []).join(', ') || 'none'}).`
            : `AST inspection flagged issues: ${(pyRes.findings || []).join('; ') || 'Syntax/Safety check failed'}.`;
          hypotheses.push({
            hypothesisId: 'hyp_ast_1',
            strategy: 'ast_code_inspector',
            summary: answerSummary,
            evidenceRefs: [],
            constraintsChecked: ['syntax_valid', 'no_unsafe_builtins', ...constraints],
            counterexampleTested: true,
            counterexamplePassed: counterPassed,
            counterexampleDetail: 'Malformed Python snippet rejected with SyntaxError.',
            verifierPassed: Boolean(pyRes.syntax_valid && pyRes.safe),
            score: verified ? 0.93 : 0.3,
          });
          internalTraceSteps.push(`ast_syntax=${pyRes.syntax_valid} ast_safe=${pyRes.safe}`);
        } else {
          // Hypothesis 1: Hybrid RAG + Knowledge Graph Multi-Hop Evidence
          const kg = KnowledgeGraphEngine.getInstance();
          const kie = KnowledgeIntelligenceEngine.getInstance();
          const rag = kie.advancedRetrieve(params.prompt, {
            limit: perf.getConfig().retrievalLimit,
            minScore: 1.5,
            maxContextChars: perf.getConfig().contextMaxChars,
            tenantId: params.scope?.tenantId,
            role: params.scope?.role,
          });
          const graphRes = kg.traverseMultiHop(params.prompt, {
            maxHops: params.maxHops ?? perf.getConfig().graphMaxHops,
            limit: 5,
            scope: params.scope,
          });

          const evRefs = rag.results.map((r) => ({
            documentId: r.documentId,
            title: r.documentTitle,
            contentHash: r.citation.contentHash,
          }));
          const graphPathsCount = graphRes.paths.length;
          const ragHitCount = rag.results.length;

          // Counterexample: query random nonce expecting 0 false hits
          const nonsenseProbe = kie.hybridRetrieve(`__counterexample_absent_${crypto.randomBytes(4).toString('hex')}__`, {
            limit: 2,
            minScore: 1.5,
            tenantId: params.scope?.tenantId,
            role: params.scope?.role,
          });
          const counterPassed = !nonsenseProbe.found && nonsenseProbe.results.length === 0;

          const ragOk = ragHitCount > 0 || graphPathsCount > 0;
          hypotheses.push({
            hypothesisId: 'hyp_rag_graph_1',
            strategy: 'multi_hop_graph_rag',
            summary: ragOk
              ? `Grounded in ${ragHitCount} workspace chunk(s) and ${graphPathsCount} knowledge-graph path(s). Top source: ${rag.results[0]?.documentTitle || graphRes.paths[0]?.hops[0]?.documentTitle || 'KnowledgeGraph'}.`
              : 'No workspace document or graph path exceeded confidence threshold.',
            evidenceRefs: evRefs,
            constraintsChecked: constraints,
            counterexampleTested: true,
            counterexamplePassed: counterPassed,
            counterexampleDetail: 'Absent-concept probe yielded 0 fabricated citations.',
            verifierPassed: ragOk && counterPassed,
            score: ragOk ? Math.min(0.92, 0.55 + ragHitCount * 0.08 + graphPathsCount * 0.05) : 0.18,
          });

          // Strategy revision when primary strategy yields weak evidence or native model is blocked
          if (!ragOk || selectedStrategy === 'native_lm_guarded') {
            if (selectedStrategy === 'native_lm_guarded' && !conn.executionVerified) {
              revisedToStrategy = 'multi_hop_graph_rag';
              revisionReason = `Native Model logits ${conn.runtimeState} (cloud checkpoint not verified); revised to grounded multi-hop retrieval with honest abstention.`;
              internalTraceSteps.push(`strategy_revised -> multi_hop_graph_rag`);
            }
          }

          verified = ragOk && counterPassed && ctx.conflicts.length === 0;
          verifierAttribution = 'knowledge_graph_hybrid_verifier';
          if (ragOk) {
            const topExcerpt = rag.compressedContext ? rag.compressedContext.split('\n')[0] : hypotheses[0].summary;
            answerSummary = `${hypotheses[0].summary} Evidence: ${topExcerpt}`;
          } else {
            answerSummary =
              'Abstaining cleanly: no verified Knowledge Workspace or Knowledge Graph evidence matched the prompt, and cloud native weights are not resident.';
          }
        }

        // Hypothesis 2 (Multi-Path): Objective candidate comparison via Python verifier
        if (problemClass === 'hybrid_execution' && params.prompt.length > 0) {
          const measuredLatencyMs = Math.max(1, Date.now() - Date.parse(ctx.analyzedAt));
          const candidates = hypotheses.map((h) => ({
            id: h.hypothesisId,
            tests_passed: h.verifierPassed ? 1 : 0,
            tests_total: 1,
            constraints_satisfied: ctx.conflicts.length === 0,
            safety_passed: true,
            latency_ms: measuredLatencyMs,
          }));
          const altRank = await this.runPythonVerifier({ op: 'evaluate_alternatives', candidates });
          internalTraceSteps.push(`alt_rank_selected=${altRank.selected}`);
        }

        hypotheses.sort((a, b) => b.score - a.score);
        const winner = hypotheses[0];

        // Uncertainty & Calibration
        const epistemicPenalty = ctx.conflicts.length * 0.18 + (winner.verifierPassed ? 0 : 0.45);
        const calibratedConfidence = Number(Math.max(0.05, Math.min(0.97, winner.score - epistemicPenalty)).toFixed(3));
        const epistemicUncertainty = Number((1 - calibratedConfidence).toFixed(3));
        const abstentionRecommended = !winner.verifierPassed || calibratedConfidence < 0.45 || ctx.conflicts.length > 0;

        return {
          result: {
            verified,
            revisedToStrategy,
            revisionReason,
            answerSummary,
            verifierAttribution,
            winner,
            calibratedConfidence,
            epistemicUncertainty,
            abstentionRecommended,
          },
          succeeded: hasStructured ? winner.counterexamplePassed : verified,
          accuracyScore: calibratedConfidence,
        };
      }
    );

    const traceDigestSha256 = crypto
      .createHash('sha256')
      .update(internalTraceSteps.join('|'))
      .digest('hex');

    const rawClaims: TruthClaimRecord[] = [
      classifyTruthClaim({
        domain: 'adaptive_reasoning',
        statement: profiled.result.verified
          ? `Winning hypothesis '${profiled.result.winner.hypothesisId}' passed verifier '${profiled.result.verifierAttribution}' and counterexample probe`
          : `Hypothesis '${profiled.result.winner.hypothesisId}' failed verification or triggered honest abstention`,
        classification: profiled.result.verified ? 'VERIFIED_FACT' : 'UNVERIFIED',
        basis: `Verifier=${profiled.result.verifierAttribution}; counterexamplePassed=${profiled.result.winner.counterexamplePassed}`,
        evidenceRefs: [traceDigestSha256, ...profiled.result.winner.evidenceRefs.map((e) => e.contentHash)],
      }),
      classifyTruthClaim({
        domain: 'adaptive_reasoning',
        statement: `Epistemic confidence=${profiled.result.calibratedConfidence} (uncertainty=${profiled.result.epistemicUncertainty})`,
        classification: 'ASSUMPTION',
        basis: 'Heuristic scoring formula combining verifier pass/fail and context conflict penalty',
      }),
    ];
    if (ctx.conflicts.length > 0) {
      rawClaims.push(
        classifyTruthClaim({
          domain: 'adaptive_reasoning',
          statement: `${ctx.conflicts.length} unresolved context conflict(s) lowered confidence`,
          classification: 'CONTRADICTED',
          basis: 'Context conflict detector flagged opposing assertions or numeric mismatch',
          evidenceRefs: ctx.conflicts.map((c) => c.conflictId),
        })
      );
    }
    if (profiled.result.revisedToStrategy) {
      rawClaims.push(
        classifyTruthClaim({
          domain: 'adaptive_reasoning',
          statement: `Strategy fallback proposed from '${selectedStrategy}' to '${profiled.result.revisedToStrategy}'`,
          classification: 'PROPOSED',
          basis: profiled.result.revisionReason || 'Guardrail triggered when Native Model runtime is not verified',
        })
      );
    }

    const truthClaims = enforceTruthClaims(rawClaims);
    const truthSummary = summarizeTruthClaims(truthClaims);

    const outcome: AdaptiveReasoningOutcome = {
      reasoningId: `rsn_${Date.now()}_${crypto.randomBytes(3).toString('hex')}`,
      timestamp: new Date().toISOString(),
      problemClass,
      selectedStrategy,
      revisedToStrategy: profiled.result.revisedToStrategy,
      revisionReason: profiled.result.revisionReason,
      contextAnalysis: {
        contextId: ctx.contextId,
        intent: ctx.intent.primary,
        language: ctx.language,
        conflictsDetected: ctx.conflicts.length,
        attribution: ctx.attribution,
      },
      constraints,
      hypothesesEvaluated: hypotheses.length,
      winningHypothesis: profiled.result.winner,
      uncertainty: {
        calibratedConfidence: profiled.result.calibratedConfidence,
        epistemicUncertainty: profiled.result.epistemicUncertainty,
        abstentionRecommended: profiled.result.abstentionRecommended,
        reason: profiled.result.abstentionRecommended
          ? 'Low empirical grounding, context conflict detected, or verifier rejected hypothesis.'
          : undefined,
      },
      reasoningMetadata: {
        traceDigestSha256,
        redactedPrivateTrace: true,
        verifierAttribution: profiled.result.verifierAttribution,
        nativeNeuralState: conn.runtimeState,
        durationMs: profiled.durationMs,
      },
      answerSummary: profiled.result.answerSummary,
      verified: profiled.result.verified,
      truthClaims,
      truthSummary,
    };

    this.history.unshift(outcome);
    this.saveHistory();

    AuditLedger.append('SYSTEM', 'ADAPTIVE_REASONING_EXECUTED', {
      reasoningId: outcome.reasoningId,
      problemClass,
      selectedStrategy,
      revisedToStrategy: outcome.revisedToStrategy || null,
      verified: outcome.verified,
      calibratedConfidence: outcome.uncertainty.calibratedConfidence,
      traceDigestSha256,
      tenantId,
    });

    return outcome;
  }

  /**
   * Independent benchmark suite measuring strategy accuracy, counterexample resistance,
   * uncertainty abstention, and constraint satisfaction without train/eval leakage.
   */
  public async evaluateAgainstIndependentBenchmark(): Promise<{
    totalCases: number;
    passedCases: number;
    accuracy: number;
    avgLatencyMs: number;
    cases: Array<{
      caseId: string;
      problemClass: ProblemClass;
      strategy: ReasoningStrategyId;
      passed: boolean;
      calibratedConfidence: number;
      detail: string;
    }>;
  }> {
    const suite: IndependentBenchmarkCase[] = [
      {
        caseId: 'IND-MATH-01',
        problemClass: 'deterministic_symbolic',
        prompt: 'Compute multi-step budget check: (12 * 4) + 15',
        mathSteps: [
          { expr: '12 * 4', claimed: 48 },
          { expr: '48 + 15', claimed: 63 },
        ],
        expectedFinal: 63,
      },
      {
        caseId: 'IND-MATH-02-REJECT',
        problemClass: 'deterministic_symbolic',
        prompt: 'Detect arithmetic error in claimed step output',
        mathSteps: [{ expr: '25 * 4', claimed: 90 }],
        expectedFinal: 100,
        expectAbstain: true,
      },
      {
        caseId: 'IND-CSP-01',
        problemClass: 'constraint_csp',
        prompt: 'Plan topological order under budget limit=60',
        cspTasks: [
          { id: 'ingest', cost: 15, priority: 1 },
          { id: 'index', depends_on: ['ingest'], cost: 20, priority: 2 },
          { id: 'verify', depends_on: ['index'], cost: 10, priority: 3 },
        ],
        maxCost: 60,
        expectSatisfiable: true,
      },
      {
        caseId: 'IND-CODE-01',
        problemClass: 'code_verification',
        prompt: 'Inspect Python helper using AST safety rules',
        pythonSource: 'def add_numbers(a: int, b: int) -> int:\n    return a + b\n',
        expectSyntaxValid: true,
        expectSafe: true,
      },
      {
        caseId: 'IND-CODE-02-UNSAFE',
        problemClass: 'code_verification',
        prompt: 'Reject unsafe Python eval() call via AST check',
        pythonSource: 'def run_user(s):\n    return eval(s)\n',
        expectSyntaxValid: true,
        expectSafe: false,
        expectAbstain: true,
      },
      {
        caseId: 'IND-ABSTAIN-01',
        problemClass: 'multi_hop_rag',
        prompt: '__nonexistent_xyz_992817_quantum_flux_module__',
        expectAbstain: true,
      },
    ];

    const caseResults: Array<{
      caseId: string;
      problemClass: ProblemClass;
      strategy: ReasoningStrategyId;
      passed: boolean;
      calibratedConfidence: number;
      detail: string;
    }> = [];
    let totalDuration = 0;

    for (const c of suite) {
      const out = await this.executeReasoning({
        prompt: c.prompt,
        mathSteps: c.mathSteps,
        expectedFinal: c.expectedFinal,
        cspTasks: c.cspTasks,
        maxCost: c.maxCost,
        pythonSource: c.pythonSource,
        scope: { tenantId: '__b29_independent_benchmark', userId: 'benchmark_runner', role: 'developer' },
      });
      totalDuration += out.reasoningMetadata.durationMs;

      const passed = c.expectAbstain
        ? !out.verified && out.uncertainty.abstentionRecommended
        : out.verified && !out.uncertainty.abstentionRecommended;

      caseResults.push({
        caseId: c.caseId,
        problemClass: out.problemClass,
        strategy: out.selectedStrategy,
        passed,
        calibratedConfidence: out.uncertainty.calibratedConfidence,
        detail: out.answerSummary.slice(0, 140),
      });
    }

    const passedCases = caseResults.filter((r) => r.passed).length;
    return {
      totalCases: suite.length,
      passedCases,
      accuracy: Number((passedCases / suite.length).toFixed(3)),
      avgLatencyMs: Number((totalDuration / suite.length).toFixed(2)),
      cases: caseResults,
    };
  }

  public getHistory(limit = 20): AdaptiveReasoningOutcome[] {
    return this.history.slice(0, limit);
  }
}

/**
 * ZYNTHEOR Batch 28 — Autonomous Planning Engine (DAG + Resource Budget + Plan Revisions)
 *
 * Capabilities:
 *  - Goal decomposition into structured multi-step DAG
 *  - Dependency cycle detection & topological ordering
 *  - Priority & resource budget allocation (tool calls, retries, time, tokens)
 *  - Live step progress tracking
 *  - Failure detection & dynamic plan revision with explicit traceable reasons
 *  - Completion verification against measurable acceptance gates
 *  - Disk persistence in native_data/plans/
 */

import fs from 'fs';
import path from 'path';
import { AuditLedger } from './AuditLedger';
import type { TaskPriority } from './TaskOrchestrator';

export type PlanStepStatus = 'PENDING' | 'RUNNING' | 'COMPLETED' | 'FAILED' | 'SKIPPED';

export interface PlanStep {
  id: string;
  title: string;
  stage: string;
  tool?: string;
  dependsOn: string[];
  priority: number; // 1 (highest) .. 10
  estimatedMs: number;
  status: PlanStepStatus;
  attempts: number;
  startedAt?: string;
  completedAt?: string;
  outputSummary?: string;
  error?: string;
}

export interface PlanRevisionRecord {
  revision: number;
  timestamp: string;
  reason: string;
  failedStepId?: string;
  actionTaken: string;
  addedStepIds: string[];
}

export interface ResourceBudget {
  maxToolCalls: number;
  usedToolCalls: number;
  maxRetries: number;
  usedRetries: number;
  maxDurationMs: number;
  elapsedMs: number;
  maxTokens: number;
  usedTokens: number;
  exhausted: boolean;
  exhaustedReason?: string;
}

export interface AutonomousPlan {
  planId: string;
  taskId: string;
  tenantId: string;
  ownerUserId: string;
  goal: string;
  priority: TaskPriority;
  runtime: 'node' | 'python3';
  createdAt: string;
  updatedAt: string;
  status: 'ACTIVE' | 'REVISED' | 'COMPLETED' | 'FAILED' | 'BLOCKED';
  steps: PlanStep[];
  executionOrder: string[];
  revisions: PlanRevisionRecord[];
  budget: ResourceBudget;
  completionVerified: boolean;
  completionSummary?: string;
}

export function resolveDagOrder(steps: PlanStep[]): string[] {
  const byId = new Map<string, PlanStep>();
  for (const s of steps) {
    if (!s.id || !s.id.trim()) {
      throw new Error('PLAN_INVALID_STEP: Every plan step requires a non-empty id.');
    }
    if (byId.has(s.id)) {
      throw new Error(`PLAN_DUPLICATE_STEP: Duplicate step id '${s.id}'.`);
    }
    byId.set(s.id, s);
  }

  // Validate unknown dependencies upfront
  for (const s of steps) {
    for (const dep of s.dependsOn) {
      if (!byId.has(dep)) {
        throw new Error(`PLAN_UNKNOWN_DEPENDENCY: Step '${s.id}' depends on missing step '${dep}'.`);
      }
    }
  }

  // Sort candidates by priority ascending so higher-priority steps execute earliest when deps allow
  const sortedCandidates = [...steps].sort((a, b) => a.priority - b.priority);
  const state = new Map<string, 0 | 1 | 2>();
  const ordered: string[] = [];

  const visit = (id: string) => {
    const cur = state.get(id) ?? 0;
    if (cur === 2) return;
    if (cur === 1) {
      throw new Error(`PLAN_CYCLE_DETECTED: Cyclic dependency detected involving step '${id}'.`);
    }
    state.set(id, 1);
    const step = byId.get(id)!;
    const deps = [...step.dependsOn].sort(
      (a, b) => (byId.get(a)?.priority ?? 5) - (byId.get(b)?.priority ?? 5)
    );
    for (const dep of deps) {
      visit(dep);
    }
    state.set(id, 2);
    ordered.push(id);
  };

  for (const s of sortedCandidates) {
    if ((state.get(s.id) ?? 0) === 0) {
      visit(s.id);
    }
  }

  return ordered;
}

export class AutonomousPlanner {
  private static instance: AutonomousPlanner | null = null;
  private plansDir: string;
  private plans = new Map<string, AutonomousPlan>();

  private constructor() {
    this.plansDir = process.env.ZYNTHEOR_PLANS_DIR
      ? path.resolve(process.env.ZYNTHEOR_PLANS_DIR)
      : path.resolve(process.cwd(), 'native_data', 'plans');
    this.loadAll();
  }

  public static getInstance(): AutonomousPlanner {
    if (!AutonomousPlanner.instance) {
      AutonomousPlanner.instance = new AutonomousPlanner();
    }
    return AutonomousPlanner.instance;
  }

  private ensureDir(): void {
    if (!fs.existsSync(this.plansDir)) {
      fs.mkdirSync(this.plansDir, { recursive: true });
    }
  }

  private loadAll(): void {
    try {
      this.ensureDir();
      for (const fn of fs.readdirSync(this.plansDir)) {
        if (!fn.endsWith('.json')) continue;
        try {
          const parsed: AutonomousPlan = JSON.parse(fs.readFileSync(path.join(this.plansDir, fn), 'utf8'));
          if (parsed?.taskId) this.plans.set(parsed.taskId, parsed);
        } catch {
          // skip unreadable plan file
        }
      }
    } catch {
      // ignore initial dir errors
    }
  }

  private persistPlan(plan: AutonomousPlan): void {
    this.ensureDir();
    plan.updatedAt = new Date().toISOString();
    const target = path.join(this.plansDir, `${plan.taskId}.json`);
    const tmp = `${target}.tmp.${process.pid}`;
    fs.writeFileSync(tmp, JSON.stringify(plan, null, 2), 'utf8');
    fs.renameSync(tmp, target);
    this.plans.set(plan.taskId, plan);
  }

  public decomposeGoal(params: {
    taskId: string;
    goal: string;
    priority: TaskPriority;
    runtime: 'node' | 'python3';
    tenantId: string;
    ownerUserId: string;
    customSteps?: PlanStep[];
    budgetOverrides?: Partial<ResourceBudget>;
  }): AutonomousPlan {
    const g = params.goal.toLowerCase();
    const basePrio = params.priority === 'High' ? 1 : params.priority === 'Medium' ? 3 : 5;
    const steps: PlanStep[] = params.customSteps
      ? params.customSteps
      : [
          {
            id: 'step_intake',
            title: 'Decompose goal constraints and target runtime',
            stage: '01_INTAKE',
            dependsOn: [],
            priority: basePrio,
            estimatedMs: 120,
            status: 'PENDING',
            attempts: 0,
          },
          {
            id: 'step_analyze_context',
            title: 'Audit workspace files and retrieve grounded knowledge',
            stage: '02_ANALYZE',
            tool: 'list_files',
            dependsOn: ['step_intake'],
            priority: basePrio + 1,
            estimatedMs: 250,
            status: 'PENDING',
            attempts: 0,
          },
          {
            id: 'step_plan_architecture',
            title: 'Formulate DAG execution steps & acceptance gates',
            stage: '03_PLAN',
            dependsOn: ['step_analyze_context'],
            priority: basePrio + 1,
            estimatedMs: 300,
            status: 'PENDING',
            attempts: 0,
          },
          {
            id: 'step_build_source',
            title: `Synthesize ${params.runtime === 'python3' ? 'Python 3' : 'Node.js'} entry & companion modules`,
            stage: '04_BUILD',
            dependsOn: ['step_plan_architecture'],
            priority: basePrio + 2,
            estimatedMs: 800,
            status: 'PENDING',
            attempts: 0,
          },
          {
            id: 'step_execute_sandbox',
            title: 'Write artifacts into /workspace and run static syntax + security review',
            stage: '05_EXECUTE',
            tool: 'write_file',
            dependsOn: ['step_build_source'],
            priority: basePrio + 2,
            estimatedMs: 600,
            status: 'PENDING',
            attempts: 0,
          },
          {
            id: 'step_verify_tests',
            title: /\bweb\b|html|ui|dashboard/.test(g)
              ? 'Run runtime smoke + unit + DOM/UI artifact checks'
              : 'Execute sandbox runtime and isolated unit test suite',
            stage: '06_TEST',
            tool: 'run_command',
            dependsOn: ['step_execute_sandbox'],
            priority: basePrio + 2,
            estimatedMs: 900,
            status: 'PENDING',
            attempts: 0,
          },
          {
            id: 'step_deliver_package',
            title: 'Verify acceptance criteria and seal deliverable ZIP manifest',
            stage: '08_DELIVER',
            dependsOn: ['step_verify_tests'],
            priority: basePrio + 3,
            estimatedMs: 400,
            status: 'PENDING',
            attempts: 0,
          },
        ];

    const executionOrder = resolveDagOrder(steps);
    const now = new Date().toISOString();
    const maxRetries = params.priority === 'High' ? 3 : 2;

    const plan: AutonomousPlan = {
      planId: `plan_${params.taskId}`,
      taskId: params.taskId,
      tenantId: params.tenantId,
      ownerUserId: params.ownerUserId,
      goal: params.goal,
      priority: params.priority,
      runtime: params.runtime,
      createdAt: now,
      updatedAt: now,
      status: 'ACTIVE',
      steps,
      executionOrder,
      revisions: [],
      budget: {
        maxToolCalls: params.budgetOverrides?.maxToolCalls ?? 24,
        usedToolCalls: 0,
        maxRetries: params.budgetOverrides?.maxRetries ?? maxRetries,
        usedRetries: 0,
        maxDurationMs: params.budgetOverrides?.maxDurationMs ?? 45_000,
        elapsedMs: 0,
        maxTokens: params.budgetOverrides?.maxTokens ?? 16_384,
        usedTokens: 0,
        exhausted: false,
      },
      completionVerified: false,
    };

    this.persistPlan(plan);
    AuditLedger.append('PLANNER', 'AUTONOMOUS_DAG_PLAN_CREATED', {
      planId: plan.planId,
      taskId: plan.taskId,
      stepCount: plan.steps.length,
      executionOrder: plan.executionOrder,
      tenantId: plan.tenantId,
    });
    return plan;
  }

  public updateStepStatus(
    taskId: string,
    stepId: string,
    status: PlanStepStatus,
    details?: { outputSummary?: string; error?: string }
  ): AutonomousPlan | null {
    const plan = this.plans.get(taskId);
    if (!plan) return null;
    const step = plan.steps.find((s) => s.id === stepId);
    if (!step) return plan;

    const now = new Date().toISOString();
    if (status === 'RUNNING') {
      step.attempts += 1;
      step.startedAt = step.startedAt || now;
    } else if (status === 'COMPLETED' || status === 'FAILED') {
      step.completedAt = now;
    }
    step.status = status;
    if (details?.outputSummary !== undefined) step.outputSummary = details.outputSummary;
    if (details?.error !== undefined) step.error = details.error;

    this.persistPlan(plan);
    return plan;
  }

  public recordResourceUsage(
    taskId: string,
    delta: { toolCalls?: number; retries?: number; elapsedMs?: number; tokens?: number }
  ): ResourceBudget | null {
    const plan = this.plans.get(taskId);
    if (!plan) return null;
    const b = plan.budget;
    if (delta.toolCalls) b.usedToolCalls += delta.toolCalls;
    if (delta.retries) b.usedRetries += delta.retries;
    if (delta.elapsedMs !== undefined) b.elapsedMs = Math.max(b.elapsedMs, delta.elapsedMs);
    if (delta.tokens) b.usedTokens += delta.tokens;

    if (b.usedToolCalls > b.maxToolCalls) {
      b.exhausted = true;
      b.exhaustedReason = `Tool call budget exceeded (${b.usedToolCalls}/${b.maxToolCalls})`;
    } else if (b.usedRetries > b.maxRetries) {
      b.exhausted = true;
      b.exhaustedReason = `Retry budget exceeded (${b.usedRetries}/${b.maxRetries})`;
    } else if (b.elapsedMs > b.maxDurationMs) {
      b.exhausted = true;
      b.exhaustedReason = `Duration budget exceeded (${b.elapsedMs}ms/${b.maxDurationMs}ms)`;
    } else if (b.usedTokens > b.maxTokens) {
      b.exhausted = true;
      b.exhaustedReason = `Token budget exceeded (${b.usedTokens}/${b.maxTokens})`;
    }

    if (b.exhausted && plan.status === 'ACTIVE') {
      plan.status = 'BLOCKED';
    }
    this.persistPlan(plan);
    return { ...b };
  }

  /**
   * Revises a plan dynamically when a defect/failure occurs, adding traceable repair steps
   * wired cleanly into the DAG before final verification & delivery.
   */
  public revisePlan(
    taskId: string,
    params: { reason: string; failedStepId?: string; actionTaken: string }
  ): AutonomousPlan | null {
    const plan = this.plans.get(taskId);
    if (!plan) return null;

    const revNum = plan.revisions.length + 1;
    const repairStepId = `step_repair_${revNum}`;
    const depSource = params.failedStepId && plan.steps.some((s) => s.id === params.failedStepId)
      ? [params.failedStepId]
      : ['step_execute_sandbox'];

    const repairStep: PlanStep = {
      id: repairStepId,
      title: `Autonomous Repair #${revNum}: ${params.actionTaken.slice(0, 100)}`,
      stage: '07_REPAIR',
      tool: 'write_file',
      dependsOn: depSource,
      priority: 1,
      estimatedMs: 500,
      status: 'RUNNING',
      attempts: 1,
      startedAt: new Date().toISOString(),
    };

    plan.steps.push(repairStep);
    const deliverStep = plan.steps.find((s) => s.id === 'step_deliver_package');
    if (deliverStep && !deliverStep.dependsOn.includes(repairStepId)) {
      deliverStep.dependsOn.push(repairStepId);
    }

    plan.executionOrder = resolveDagOrder(plan.steps);
    plan.status = 'REVISED';
    const revision: PlanRevisionRecord = {
      revision: revNum,
      timestamp: new Date().toISOString(),
      reason: params.reason,
      failedStepId: params.failedStepId,
      actionTaken: params.actionTaken,
      addedStepIds: [repairStepId],
    };
    plan.revisions.push(revision);
    this.persistPlan(plan);

    AuditLedger.append('PLANNER', 'AUTONOMOUS_PLAN_REVISED', {
      planId: plan.planId,
      taskId: plan.taskId,
      revision: revNum,
      reason: params.reason,
      failedStepId: params.failedStepId,
    });

    return plan;
  }

  public finalizePlan(
    taskId: string,
    verified: boolean,
    summary: string,
    blocked = false
  ): AutonomousPlan | null {
    const plan = this.plans.get(taskId);
    if (!plan) return null;
    plan.completionVerified = verified;
    plan.completionSummary = summary;
    plan.status = verified ? 'COMPLETED' : blocked ? 'BLOCKED' : 'FAILED';
    this.persistPlan(plan);
    return plan;
  }

  public getPlan(taskId: string, scope?: { tenantId?: string; ownerUserId?: string }): AutonomousPlan | null {
    const plan = this.plans.get(taskId);
    if (!plan) return null;
    if (scope?.tenantId && plan.tenantId !== scope.tenantId) return null;
    if (scope?.ownerUserId && plan.ownerUserId !== scope.ownerUserId) return null;
    return plan;
  }

  public listPlans(scope?: { tenantId?: string; ownerUserId?: string }): AutonomousPlan[] {
    return Array.from(this.plans.values())
      .filter((p) => {
        if (scope?.tenantId && p.tenantId !== scope.tenantId) return false;
        if (scope?.ownerUserId && p.ownerUserId !== scope.ownerUserId) return false;
        return true;
      })
      .sort((a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt));
  }
}

