export interface S3ClientLike {
  send(command: any, options?: { abortSignal?: AbortSignal }): Promise<any>;
  destroy?: () => void;
}

export type S3ClientFactory = (cfg: {
  region: string;
  endpoint?: string;
  forcePathStyle: boolean;
  accessKeyId: string;
  secretAccessKey: string;
}) => S3ClientLike;

function cleanValue(raw: string | boolean | undefined): string {
  if (raw === undefined) return '';
  let trimmed = String(raw).trim();
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"') && trimmed.length >= 2) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'") && trimmed.length >= 2)
  ) {
    trimmed = trimmed.slice(1, -1).trim();
  }
  return trimmed;
}

function validateSafeExternalUrl(label: string, rawUrl: string): string {
  let parsed: URL;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new Error(`Invalid URL format for ${label}`);
  }
  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
    throw new Error(`${label} must use http:// or https://`);
  }
  if (parsed.username || parsed.password) {
    throw new Error(`${label} cannot contain embedded credentials`);
  }
  const host = parsed.hostname.toLowerCase();
  const allowLoopback = process.env.ZYNTHEOR_ALLOW_LOOPBACK_CLOUD !== 'false';
  const isLoopback = host === 'localhost' || host === '127.0.0.1' || host === '::1';
  if (
    !host ||
    host === 'metadata.google.internal' ||
    host === 'metadata.goog' ||
    host.endsWith('.internal') ||
    host.startsWith('169.254.') ||
    host === '0.0.0.0' ||
    host === '::' ||
    (isLoopback && !allowLoopback)
  ) {
    throw new Error(`SSRF_BLOCKED: Restricted host '${host}' for ${label}`);
  }
  return parsed.href;
}

async function bodyToBuffer(body: any): Promise<Buffer> {
  if (!body) {
    throw new Error('Empty response body from Cloud Object Storage');
  }
  if (Buffer.isBuffer(body)) {
    return body;
  }
  if (body instanceof Uint8Array) {
    return Buffer.from(body);
  }
  if (typeof body.transformToByteArray === 'function') {
    const arr = await body.transformToByteArray();
    return Buffer.from(arr);
  }
  const chunks: Buffer[] = [];
  for await (const chunk of body) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  }
  return Buffer.concat(chunks);
}

const defaultS3ClientFactory: S3ClientFactory = (cfg) =>
  new S3Client({
    region: cfg.region,
    endpoint: cfg.endpoint,
    forcePathStyle: cfg.forcePathStyle,
    maxAttempts: 1,
    credentials: {
      accessKeyId: cfg.accessKeyId,
      secretAccessKey: cfg.secretAccessKey,
    },
  });

export class CloudObjectStorageService {
  private static clientFactory: S3ClientFactory = defaultS3ClientFactory;

  public static setClientFactoryForTesting(factory?: S3ClientFactory): void {
    CloudObjectStorageService.clientFactory = factory || defaultS3ClientFactory;
  }

  public static getConfigurationStatus(): CloudSecretsSnapshot & {
    s3Configured: boolean;
    bucket: string | null;
    region: string;
    endpoint: string | null;
    checkpointKey: string;
    forcePathStyle: boolean;
  } {
    const norm = hydrateCloudRuntimeEnv();
    const snapshot = getCloudSecretsSnapshot();
    const endpoint = norm.S3_ENDPOINT || null;
    return {
      ...snapshot,
      s3Configured: isCloudCheckpointStorageConfigured(),
      bucket: norm.S3_BUCKET || null,
      region: norm.S3_REGION || (endpoint ? 'auto' : 'us-east-1'),
      endpoint,
      checkpointKey: norm.S3_CHECKPOINT_KEY || 'checkpoints/model_checkpoint.pt',
      forcePathStyle: String(norm.S3_FORCE_PATH_STYLE || 'false').toLowerCase() === 'true',
    };
  }

  public static configureConnection(updates: CloudStorageEndpointConfigInput): {
    updatedKeys: AllowedCloudConfigKey[];
    clearedKeys: AllowedCloudConfigKey[];
    snapshot: CloudSecretsSnapshot;
  } {
    const res = persistCloudSecretsToEnv({ ...updates });
    AuditLedger.append('SYSTEM', 'CLOUD_OBJECT_STORAGE_CONFIGURED', {
      updatedKeys: res.updatedKeys,
      clearedKeys: res.clearedKeys,
      provider: res.snapshot.provider,
      configValid: res.snapshot.configValid,
    });
    return res;
  }

  public static async testBucketConnection(opts?: {
    verifyReadWrite?: boolean;
    objectKey?: string;
    overrides?: CloudStorageEndpointConfigInput;
    listPrefix?: string;
  }): Promise<CloudStorageConnectionTestResult> {
    const started = Date.now();
    const norm = hydrateCloudRuntimeEnv();
    const pick = (overrideVal: string | boolean | undefined, envKey: AllowedCloudConfigKey): string => {
      if (overrideVal !== undefined) {
        const cleaned = cleanValue(overrideVal);
        if (cleaned && !cleaned.includes('••••')) {
          return cleaned;
        }
      }
      return cleanValue(norm[envKey] ?? process.env[envKey]);
    };

    const bucket = pick(opts?.overrides?.S3_BUCKET, 'S3_BUCKET');
    const endpointRaw = pick(opts?.overrides?.S3_ENDPOINT, 'S3_ENDPOINT');
    const region = pick(opts?.overrides?.S3_REGION, 'S3_REGION') || (endpointRaw ? 'auto' : 'us-east-1');
    const accessKeyId = pick(opts?.overrides?.S3_ACCESS_KEY_ID, 'S3_ACCESS_KEY_ID');
    const secretAccessKey = pick(opts?.overrides?.S3_SECRET_ACCESS_KEY, 'S3_SECRET_ACCESS_KEY');
    const checkpointKey =
      cleanValue(opts?.objectKey) ||
      pick(opts?.overrides?.S3_CHECKPOINT_KEY, 'S3_CHECKPOINT_KEY') ||
      'checkpoints/model_checkpoint.pt';
    const forcePathStyleRaw =
      opts?.overrides?.S3_FORCE_PATH_STYLE !== undefined
        ? String(opts.overrides.S3_FORCE_PATH_STYLE)
        : norm.S3_FORCE_PATH_STYLE || process.env.S3_FORCE_PATH_STYLE || 'false';
    const forcePathStyle = forcePathStyleRaw.toLowerCase() === 'true';

    const missing: string[] = [];
    if (!bucket) missing.push('S3_BUCKET');
    if (!accessKeyId) missing.push('S3_ACCESS_KEY_ID');
    if (!secretAccessKey) missing.push('S3_SECRET_ACCESS_KEY');

    AuditLedger.emitWorkflowEvent({
      source: 'cloud_preflight',
      tag: 'INIT',
      goal: `Production Integration · ${checkpointKey}`,
      resetLogs: true,
      isRunning: true,
      message: `Cloud Preflight: checking bucket '${bucket || 'UNSET'}', credentials, checkpoint '${checkpointKey}' & R/W permissions`,
    });

    let validatedEndpoint: string | undefined;
    if (endpointRaw) {
      try {
        validatedEndpoint = validateSafeExternalUrl('S3_ENDPOINT', endpointRaw);
      } catch (err: any) {
        const errMsg = err?.message || 'Invalid S3_ENDPOINT URL';
        AuditLedger.emitWorkflowEvent({
          source: 'cloud_preflight',
          tag: 'ERROR',
          isRunning: false,
          message: `FAIL_CLOSED: Cloud Preflight invalid S3_ENDPOINT — ${errMsg}`,
        });
        return {
          success: false,
          preflightReady: false,
          validConfig: false,
          bucketReachable: false,
          readVerified: false,
          writeVerified: false,
          cleanupVerified: false,
          roundtripSha256Match: false,
          objectExists: null,
          objectSizeBytes: null,
          bucket: bucket || null,
          region,
          endpoint: endpointRaw,
          checkpointKey,
          forcePathStyle,
          httpStatusCode: null,
          latencyMs: Math.max(1, Date.now() - started),
          probeKey: null,
          probeSha256: null,
          artifacts: [],
          errorCode: 'INVALID_ENDPOINT',
          errorMessage: errMsg,
          checkedAt: new Date().toISOString(),
        };
      }
    }

    if (missing.length > 0) {
      const errMsg = `Missing required Cloud Object Storage credentials: ${missing.join(', ')}`;
      AuditLedger.emitWorkflowEvent({
        source: 'cloud_preflight',
        tag: 'ERROR',
        isRunning: false,
        message: `FAIL_CLOSED: Cloud Preflight blocked — ${errMsg}`,
      });
      return {
        success: false,
        preflightReady: false,
        validConfig: false,
        bucketReachable: false,
        readVerified: false,
        writeVerified: false,
        cleanupVerified: false,
        roundtripSha256Match: false,
        objectExists: null,
        objectSizeBytes: null,
        bucket: bucket || null,
        region,
        endpoint: validatedEndpoint || null,
        checkpointKey,
        forcePathStyle,
        httpStatusCode: null,
        latencyMs: Math.max(1, Date.now() - started),
        probeKey: null,
        probeSha256: null,
        artifacts: [],
        errorCode: 'MISSING_CREDENTIALS',
        errorMessage: errMsg,
        checkedAt: new Date().toISOString(),
      };
    }

    const client = CloudObjectStorageService.clientFactory({
      region,
      endpoint: validatedEndpoint,
      forcePathStyle,
      accessKeyId,
      secretAccessKey,
    });

    let httpStatusCode: number | null = null;
    let objectExists: boolean | null = null;
    let objectSizeBytes: number | null = null;
    let readVerified = false;
    let writeVerified = false;
    let cleanupVerified = false;
    let roundtripSha256Match = false;
    let probeKey: string | null = null;
    let probeSha256: string | null = null;
    const artifacts: BucketArtifactSummary[] = [];

    try {
      const headBucketRes = await client.send(new HeadBucketCommand({ Bucket: bucket }), {
        abortSignal: AbortSignal.timeout(6000),
      });
      httpStatusCode = headBucketRes?.$metadata?.httpStatusCode ?? 200;

      // Stat target checkpoint object (read check #1)
      try {
        const headObjRes = await client.send(
          new HeadObjectCommand({ Bucket: bucket, Key: checkpointKey }),
          { abortSignal: AbortSignal.timeout(5000) }
        );
        objectExists = true;
        objectSizeBytes = typeof headObjRes?.ContentLength === 'number' ? headObjRes.ContentLength : null;
        readVerified = true;
      } catch (headErr: any) {
        const st = headErr?.$metadata?.httpStatusCode;
        if (st === 404 || headErr?.name === 'NotFound') {
          objectExists = false;
        } else {
          objectExists = null;
        }
      }

      // List checkpoint objects (up to 10)
      try {
        const listRes = await client.send(
          new ListObjectsV2Command({
            Bucket: bucket,
            Prefix: opts?.listPrefix ?? 'checkpoints/',
            MaxKeys: 10,
          }),
          { abortSignal: AbortSignal.timeout(5000) }
        );
        if (Array.isArray(listRes?.Contents)) {
          for (const item of listRes.Contents) {
            if (!item?.Key) continue;
            artifacts.push({
              key: String(item.Key),
              sizeBytes: Number(item.Size ?? 0),
              lastModified: item.LastModified ? new Date(item.LastModified).toISOString() : null,
              etag: item.ETag ? String(item.ETag) : null,
            });
          }
          readVerified = true;
        }
      } catch {
        // ListObjectsV2 is diagnostic; continue to explicit read/write probe
      }

      // Read/write/delete roundtrip probe
      if (opts?.verifyReadWrite !== false) {
        const nonce = crypto.randomUUID();
        probeKey = `.zyntheor-probes/rw-probe-${nonce}.bin`;
        const probePayload = Buffer.from(
          JSON.stringify({
            service: 'zyntheor-storage-probe',
            nonce,
            ts: new Date().toISOString(),
          }),
          'utf8'
        );
        probeSha256 = crypto.createHash('sha256').update(probePayload).digest('hex');

        await client.send(
          new PutObjectCommand({
            Bucket: bucket,
            Key: probeKey,
            Body: probePayload,
            ContentType: 'application/octet-stream',
            Metadata: { 'zyntheor-probe-sha256': probeSha256 },
          }),
          { abortSignal: AbortSignal.timeout(6000) }
        );
        writeVerified = true;

        const getRes = await client.send(
          new GetObjectCommand({
            Bucket: bucket,
            Key: probeKey,
          }),
          { abortSignal: AbortSignal.timeout(6000) }
        );
        const downloaded = await bodyToBuffer(getRes?.Body);
        const downloadedSha = crypto.createHash('sha256').update(downloaded).digest('hex');
        readVerified = true;
        roundtripSha256Match = downloadedSha === probeSha256 && Buffer.compare(downloaded, probePayload) === 0;

        try {
          await client.send(
            new DeleteObjectCommand({
              Bucket: bucket,
              Key: probeKey,
            }),
            { abortSignal: AbortSignal.timeout(5000) }
          );
          cleanupVerified = true;
        } catch {
          cleanupVerified = false;
        }

        if (!roundtripSha256Match) {
          AuditLedger.emitWorkflowEvent({
            source: 'cloud_preflight',
            tag: 'ERROR',
            isRunning: false,
            message: `FAIL_CLOSED: Cloud Preflight write/read SHA-256 mismatch on bucket '${bucket}'`,
          });
          return {
            success: false,
            preflightReady: false,
            validConfig: true,
            bucketReachable: true,
            readVerified,
            writeVerified,
            cleanupVerified,
            roundtripSha256Match: false,
            objectExists,
            objectSizeBytes,
            bucket,
            region,
            endpoint: validatedEndpoint || null,
            checkpointKey,
            forcePathStyle,
            httpStatusCode,
            latencyMs: Math.max(1, Date.now() - started),
            probeKey,
            probeSha256,
            artifacts,
            errorCode: 'PROBE_SHA256_MISMATCH',
            errorMessage: `Write/Read probe SHA-256 mismatch on bucket '${bucket}'`,
            checkedAt: new Date().toISOString(),
          };
        }
      }

      const overallSuccess =
        opts?.verifyReadWrite === false ? true : Boolean(writeVerified && readVerified && roundtripSha256Match);
      const preflightReady = Boolean(overallSuccess && objectExists === true);
      const latencyMs = Math.max(1, Date.now() - started);

      AuditLedger.append('SYSTEM', 'CLOUD_OBJECT_STORAGE_CONNECTION_TESTED', {
        bucket,
        region,
        endpoint: validatedEndpoint || null,
        bucketReachable: true,
        readVerified,
        writeVerified,
        roundtripSha256Match,
        objectExists,
        preflightReady,
        latencyMs,
      });

      AuditLedger.emitWorkflowEvent({
        source: 'cloud_preflight',
        tag: preflightReady ? 'INIT' : 'PLANNER',
        isRunning: false,
        message: preflightReady
          ? `Cloud Preflight passed (${latencyMs} ms): bucket '${bucket}' R/W SHA-256 verified and checkpoint '${checkpointKey}' ready (${objectSizeBytes ?? 0} bytes)`
          : `Cloud Preflight R/W probe passed (${latencyMs} ms), but checkpoint '${checkpointKey}' is not present in bucket '${bucket}' yet (objectExists=${String(objectExists)})`,
      });

      return {
        success: overallSuccess,
        preflightReady,
        validConfig: true,
        bucketReachable: true,
        readVerified,
        writeVerified,
        cleanupVerified,
        roundtripSha256Match,
        objectExists,
        objectSizeBytes,
        bucket,
        region,
        endpoint: validatedEndpoint || null,
        checkpointKey,
        forcePathStyle,
        httpStatusCode,
        latencyMs,
        probeKey,
        probeSha256,
        artifacts,
        errorCode: null,
        errorMessage:
          objectExists === false
            ? `Bucket '${bucket}' read/write verified, but target checkpoint '${checkpointKey}' does not exist yet (404).`
            : null,
        checkedAt: new Date().toISOString(),
      };
    } catch (err: any) {
      const status = err?.$metadata?.httpStatusCode ?? httpStatusCode;
      const errCode = String(err?.name || err?.Code || err?.code || 'S3_CONNECTION_ERROR');
      const errMsg = String(err?.message || err);
      const bucketReachable = Boolean(httpStatusCode && httpStatusCode < 400);
      const formattedErr = bucketReachable
        ? `Bucket '${bucket}' reachable, but read/write probe failed (${errCode}): ${errMsg}`
        : status
          ? `Bucket '${bucket}' failed with HTTP ${status} (${errCode}): ${errMsg}`
          : `Bucket '${bucket}' connection error (${errCode}): ${errMsg}`;

      AuditLedger.append('SYSTEM', 'CLOUD_OBJECT_STORAGE_CONNECTION_FAILED', {
        bucket,
        region,
        endpoint: validatedEndpoint || null,
        bucketReachable,
        readVerified,
        writeVerified,
        errorCode: errCode,
        httpStatusCode: status,
      });

      AuditLedger.emitWorkflowEvent({
        source: 'cloud_preflight',
        tag: 'ERROR',
        isRunning: false,
        message: `FAIL_CLOSED: Cloud Preflight failed — ${formattedErr}`,
      });

      return {
        success: false,
        preflightReady: false,
        validConfig: true,
        bucketReachable,
        readVerified,
        writeVerified,
        cleanupVerified,
        roundtripSha256Match: false,
        objectExists,
        objectSizeBytes,
        bucket,
        region,
        endpoint: validatedEndpoint || null,
        checkpointKey,
        forcePathStyle,
        httpStatusCode: status,
        latencyMs: Math.max(1, Date.now() - started),
        probeKey,
        probeSha256,
        artifacts,
        errorCode: errCode,
        errorMessage: formattedErr,
        checkedAt: new Date().toISOString(),
      };
    } finally {
      if (typeof client.destroy === 'function') {
        client.destroy();
      }
    }
  }

  public static async readCheckpointArtifact(opts?: {
    objectKey?: string;
    presignedUrl?: string;
    timeoutMs?: number;
  }): Promise<CloudCheckpointArtifactReadResult> {
    const started = Date.now();
    const norm = hydrateCloudRuntimeEnv();
    const presignedUrl = cleanValue(opts?.presignedUrl) || norm.CHECKPOINT_PRESIGNED_URL || '';
    const objectKey = cleanValue(opts?.objectKey) || norm.S3_CHECKPOINT_KEY || 'checkpoints/model_checkpoint.pt';
    const timeoutMs = opts?.timeoutMs ?? 60_000;

    // Prefer explicit presignedUrl if passed, otherwise S3 if configured, otherwise env CHECKPOINT_PRESIGNED_URL
    if (cleanValue(opts?.presignedUrl) || (!isCloudCheckpointStorageConfigured() && presignedUrl)) {
      const safeUrl = validateSafeExternalUrl('CHECKPOINT_PRESIGNED_URL', presignedUrl);
      const res = await fetch(safeUrl, {
        method: 'GET',
        headers: { 'User-Agent': 'ZYNTHEOR-CloudObjectStorage/1.0' },
        signal: AbortSignal.timeout(timeoutMs),
      });
      if (!res.ok) {
        throw new Error(`FAIL_CLOSED: Cloud checkpoint GET failed with HTTP ${res.status} ${res.statusText}`);
      }
      const arr = await res.arrayBuffer();
      const buffer = Buffer.from(arr);
      return {
        buffer,
        sourceUri: safeUrl,
        provider: 'presigned_url',
        byteSize: buffer.length,
        fetchLatencyMs: Math.max(1, Date.now() - started),
        httpStatusCode: res.status,
        etag: res.headers.get('etag'),
      };
    }

    const bucket = norm.S3_BUCKET || '';
    const accessKeyId = norm.S3_ACCESS_KEY_ID || '';
    const secretAccessKey = norm.S3_SECRET_ACCESS_KEY || '';
    if (!bucket || !accessKeyId || !secretAccessKey) {
      const cfg = validateCloudRuntimeConfig();
      throw new Error(
        `FAIL_CLOSED: Cloud Object Storage not configured (${cfg.missingKeys.join(', ') || 'missing bucket/credentials'}).`
      );
    }

    const endpointRaw = norm.S3_ENDPOINT || '';
    const validatedEndpoint = endpointRaw ? validateSafeExternalUrl('S3_ENDPOINT', endpointRaw) : undefined;
    const region = norm.S3_REGION || (validatedEndpoint ? 'auto' : 'us-east-1');
    const forcePathStyle = String(norm.S3_FORCE_PATH_STYLE || 'false').toLowerCase() === 'true';

    const client = CloudObjectStorageService.clientFactory({
      region,
      endpoint: validatedEndpoint,
      forcePathStyle,
      accessKeyId,
      secretAccessKey,
    });

    try {
      const response = await client.send(
        new GetObjectCommand({
          Bucket: bucket,
          Key: objectKey,
        }),
        { abortSignal: AbortSignal.timeout(timeoutMs) }
      );
      const buffer = await bodyToBuffer(response?.Body);
      return {
        buffer,
        sourceUri: `s3://${bucket}/${objectKey}`,
        provider: 's3',
        byteSize: buffer.length,
        fetchLatencyMs: Math.max(1, Date.now() - started),
        httpStatusCode: response?.$metadata?.httpStatusCode ?? 200,
        etag: response?.ETag ? String(response.ETag) : null,
      };
    } finally {
      if (typeof client.destroy === 'function') {
        client.destroy();
      }
    }
  }

  public static async writeCheckpointArtifact(
    buffer: Buffer,
    opts?: {
      objectKey?: string;
      presignedUploadUrl?: string;
      modelKey?: string;
    }
  ): Promise<{
    provider: 's3' | 'presigned_upload_url';
    sourceUri: string;
    payloadSha256: string;
    containerSha256: string;
    totalParams: number;
    byteSize: number;
    httpStatus?: number;
  }> {
    const parsed: ParsedCloudCheckpoint = parseCheckpointBuffer(buffer, opts?.objectKey || 'memory-buffer');
    const res = await publishCheckpointBufferToCloud(buffer, opts);
    return {
      ...res,
      containerSha256: parsed.containerSha256,
    };
  }

  public static async uploadTrainingTelemetryObject(
    objectKey: string,
    payload: string | Buffer,
    contentType: string = 'application/json'
  ): Promise<{
    sourceUri: string;
    sha256: string;
    byteSize: number;
    httpStatusCode: number | null;
  }> {
    const norm = hydrateCloudRuntimeEnv();
    const bucket = norm.S3_BUCKET || '';
    const accessKeyId = norm.S3_ACCESS_KEY_ID || '';
    const secretAccessKey = norm.S3_SECRET_ACCESS_KEY || '';
    if (!bucket || !accessKeyId || !secretAccessKey) {
      throw new Error('FAIL_CLOSED: S3_BUCKET, S3_ACCESS_KEY_ID, and S3_SECRET_ACCESS_KEY are required for cloud telemetry sync.');
    }
    const endpointRaw = norm.S3_ENDPOINT || '';
    const validatedEndpoint = endpointRaw ? validateSafeExternalUrl('S3_ENDPOINT', endpointRaw) : undefined;
    const region = norm.S3_REGION || (validatedEndpoint ? 'auto' : 'us-east-1');
    const forcePathStyle = String(norm.S3_FORCE_PATH_STYLE || 'false').toLowerCase() === 'true';
    const body = Buffer.isBuffer(payload) ? payload : Buffer.from(payload, 'utf8');
    const sha256 = crypto.createHash('sha256').update(body).digest('hex');

    const client = CloudObjectStorageService.clientFactory({
      region,
      endpoint: validatedEndpoint,
      forcePathStyle,
      accessKeyId,
      secretAccessKey,
    });
    try {
      const putRes = await client.send(
        new PutObjectCommand({
          Bucket: bucket,
          Key: objectKey,
          Body: body,
          ContentType: contentType,
          Metadata: { 'zyntheor-sha256': sha256 },
        }),
        { abortSignal: AbortSignal.timeout(10_000) }
      );
      return {
        sourceUri: `s3://${bucket}/${objectKey}`,
        sha256,
        byteSize: body.length,
        httpStatusCode: putRes?.$metadata?.httpStatusCode ?? 200,
      };
    } finally {
      if (typeof client.destroy === 'function') {
        client.destroy();
      }
    }
  }

  public static async listCheckpointArtifacts(prefix = 'checkpoints/', maxKeys = 50): Promise<BucketArtifactSummary[]> {
    const norm = hydrateCloudRuntimeEnv();
    const bucket = norm.S3_BUCKET || '';
    const accessKeyId = norm.S3_ACCESS_KEY_ID || '';
    const secretAccessKey = norm.S3_SECRET_ACCESS_KEY || '';
    if (!bucket || !accessKeyId || !secretAccessKey) {
      throw new Error('FAIL_CLOSED: S3_BUCKET, S3_ACCESS_KEY_ID, and S3_SECRET_ACCESS_KEY are required to list bucket artifacts.');
    }
    const endpointRaw = norm.S3_ENDPOINT || '';
    const validatedEndpoint = endpointRaw ? validateSafeExternalUrl('S3_ENDPOINT', endpointRaw) : undefined;
    const region = norm.S3_REGION || (validatedEndpoint ? 'auto' : 'us-east-1');
    const forcePathStyle = String(norm.S3_FORCE_PATH_STYLE || 'false').toLowerCase() === 'true';

    const client = CloudObjectStorageService.clientFactory({
      region,
      endpoint: validatedEndpoint,
      forcePathStyle,
      accessKeyId,
      secretAccessKey,
    });

    try {
      const listRes = await client.send(
        new ListObjectsV2Command({
          Bucket: bucket,
          Prefix: prefix,
          MaxKeys: maxKeys,
        }),
        { abortSignal: AbortSignal.timeout(8000) }
      );
      const out: BucketArtifactSummary[] = [];
      for (const item of listRes?.Contents || []) {
        if (!item?.Key) continue;
        out.push({
          key: String(item.Key),
          sizeBytes: Number(item.Size ?? 0),
          lastModified: item.LastModified ? new Date(item.LastModified).toISOString() : null,
          etag: item.ETag ? String(item.ETag) : null,
        });
      }
      return out;
    } finally {
      if (typeof client.destroy === 'function') {
        client.destroy();
      }
    }
  }

  /**
   * Dedicated Cloud Preflight gate executed prior to initiating training:
   * 1. Validates AWS S3 storage credentials & endpoint configuration.
   * 2. Verifies S3 bucket availability (HeadBucket).
   * 3. Verifies target checkpoint object exists (HeadObject) and is actively readable (Range GetObject).
   * 4. Optionally verifies bucket read/write permissions (PutObject -> GetObject SHA-256 -> DeleteObject).
   */
  public static async runCloudPreflight(opts?: {
    objectKey?: string;
    verifyReadWrite?: boolean;
    overrides?: CloudStorageEndpointConfigInput;
    silent?: boolean;
  }): Promise<CloudPreflightReport> {
    const started = Date.now();
    const silent = Boolean(opts?.silent);
    const norm = hydrateCloudRuntimeEnv();
    const pick = (overrideVal: string | boolean | undefined, envKey: AllowedCloudConfigKey): string => {
      if (overrideVal !== undefined) {
        const cleaned = cleanValue(overrideVal);
        if (cleaned && !cleaned.includes('••••')) {
          return cleaned;
        }
      }
      return cleanValue(norm[envKey] ?? process.env[envKey]);
    };

    const bucket = pick(opts?.overrides?.S3_BUCKET, 'S3_BUCKET');
    const endpointRaw = pick(opts?.overrides?.S3_ENDPOINT, 'S3_ENDPOINT');
    const region = pick(opts?.overrides?.S3_REGION, 'S3_REGION') || (endpointRaw ? 'auto' : 'us-east-1');
    const accessKeyId = pick(opts?.overrides?.S3_ACCESS_KEY_ID, 'S3_ACCESS_KEY_ID');
    const secretAccessKey = pick(opts?.overrides?.S3_SECRET_ACCESS_KEY, 'S3_SECRET_ACCESS_KEY');
    const checkpointKey =
      cleanValue(opts?.objectKey) ||
      pick(opts?.overrides?.S3_CHECKPOINT_KEY, 'S3_CHECKPOINT_KEY') ||
      'checkpoints/model_checkpoint.pt';
    const forcePathStyleRaw =
      opts?.overrides?.S3_FORCE_PATH_STYLE !== undefined
        ? String(opts.overrides.S3_FORCE_PATH_STYLE)
        : norm.S3_FORCE_PATH_STYLE || process.env.S3_FORCE_PATH_STYLE || 'false';
    const forcePathStyle = forcePathStyleRaw.toLowerCase() === 'true';

    const missingCredentials: string[] = [];
    if (!bucket) missingCredentials.push('S3_BUCKET');
    if (!accessKeyId) missingCredentials.push('S3_ACCESS_KEY_ID');
    if (!secretAccessKey) missingCredentials.push('S3_SECRET_ACCESS_KEY');
    if (!region) missingCredentials.push('S3_REGION');

    if (!silent) {
      AuditLedger.emitWorkflowEvent({
        source: 'cloud_preflight',
        tag: 'INIT',
        goal: `Production Integration · Cloud Preflight (${checkpointKey})`,
        resetLogs: true,
        isRunning: true,
        message: `Cloud Preflight: validating AWS S3 credentials, bucket '${bucket || 'UNSET'}', and checkpoint '${checkpointKey}' accessibility`,
      });
    }

    let validatedEndpoint: string | undefined;
    if (endpointRaw) {
      try {
        validatedEndpoint = validateSafeExternalUrl('S3_ENDPOINT', endpointRaw);
      } catch (err: any) {
        const errMsg = err?.message || 'Invalid S3_ENDPOINT URL';
        if (!silent) {
          AuditLedger.append('SYSTEM', 'CLOUD_PREFLIGHT_BLOCKED', {
            bucket: bucket || null,
            checkpointKey,
            reason: errMsg,
          });
          AuditLedger.emitWorkflowEvent({
            source: 'cloud_preflight',
            tag: 'ERROR',
            isRunning: false,
            message: `FAIL_CLOSED: Cloud Preflight invalid S3 endpoint — ${errMsg}`,
          });
        }
        return {
          passed: false,
          status: 'PREFLIGHT_BLOCKED',
          checks: {
            credentialsValid: false,
            bucketAvailable: false,
            checkpointExists: false,
            checkpointAccessible: false,
            readWriteVerified: false,
          },
          bucket: bucket || null,
          region,
          endpoint: endpointRaw,
          checkpointKey,
          checkpointSizeBytes: null,
          checkpointETag: null,
          checkpointLastModified: null,
          headerMagicValid: null,
          httpStatusCode: null,
          missingCredentials,
          blockers: ['invalid_s3_endpoint'],
          error: errMsg,
          latencyMs: Math.max(1, Date.now() - started),
          checkedAt: new Date().toISOString(),
        };
      }
    }

    if (missingCredentials.length > 0) {
      const errMsg = `Missing required AWS S3 storage credentials: ${missingCredentials.join(', ')}`;
      if (!silent) {
        AuditLedger.append('SYSTEM', 'CLOUD_PREFLIGHT_BLOCKED', {
          bucket: bucket || null,
          checkpointKey,
          missingCredentials,
        });
        AuditLedger.emitWorkflowEvent({
          source: 'cloud_preflight',
          tag: 'ERROR',
          isRunning: false,
          message: `FAIL_CLOSED: Cloud Preflight blocked — ${errMsg}`,
        });
      }
      return {
        passed: false,
        status: 'PREFLIGHT_BLOCKED',
        checks: {
          credentialsValid: false,
          bucketAvailable: false,
          checkpointExists: false,
          checkpointAccessible: false,
          readWriteVerified: false,
        },
        bucket: bucket || null,
        region,
        endpoint: validatedEndpoint || null,
        checkpointKey,
        checkpointSizeBytes: null,
        checkpointETag: null,
        checkpointLastModified: null,
        headerMagicValid: null,
        httpStatusCode: null,
        missingCredentials,
        blockers: ['missing_s3_credentials'],
        error: errMsg,
        latencyMs: Math.max(1, Date.now() - started),
        checkedAt: new Date().toISOString(),
      };
    }

    const client = CloudObjectStorageService.clientFactory({
      region,
      endpoint: validatedEndpoint,
      forcePathStyle,
      accessKeyId,
      secretAccessKey,
    });

    let bucketAvailable = false;
    let checkpointExists = false;
    let checkpointAccessible = false;
    let readWriteVerified = opts?.verifyReadWrite === false;
    let checkpointSizeBytes: number | null = null;
    let checkpointETag: string | null = null;
    let checkpointLastModified: string | null = null;
    let headerMagicValid: boolean | null = null;
    let httpStatusCode: number | null = null;
    const blockers: string[] = [];
    const errors: string[] = [];

    try {
      // 1. Validate Bucket Availability
      try {
        const headBucketRes = await client.send(new HeadBucketCommand({ Bucket: bucket }), {
          abortSignal: AbortSignal.timeout(6000),
        });
        httpStatusCode = headBucketRes?.$metadata?.httpStatusCode ?? 200;
        bucketAvailable = true;
      } catch (bucketErr: any) {
        httpStatusCode = bucketErr?.$metadata?.httpStatusCode ?? null;
        const msg = String(bucketErr?.message || bucketErr);
        blockers.push('s3_bucket_unavailable');
        errors.push(`Bucket '${bucket}' unavailable (${bucketErr?.name || 'HeadBucketError'}): ${msg}`);
      }

      // 2. Verify Checkpoint File Exists & Is Accessible
      if (bucketAvailable) {
        try {
          const headObjRes = await client.send(
            new HeadObjectCommand({ Bucket: bucket, Key: checkpointKey }),
            { abortSignal: AbortSignal.timeout(5000) }
          );
          checkpointExists = true;
          checkpointSizeBytes = typeof headObjRes?.ContentLength === 'number' ? headObjRes.ContentLength : null;
          checkpointETag = headObjRes?.ETag ? String(headObjRes.ETag) : null;
          checkpointLastModified = headObjRes?.LastModified ? new Date(headObjRes.LastModified).toISOString() : null;
        } catch (headErr: any) {
          const st = headErr?.$metadata?.httpStatusCode;
          if (st === 404 || headErr?.name === 'NotFound' || headErr?.name === 'NoSuchKey') {
            blockers.push(`checkpoint_object_not_found:${checkpointKey}`);
            errors.push(`Checkpoint object '${checkpointKey}' does not exist in bucket '${bucket}' (404).`);
          } else {
            blockers.push(`checkpoint_head_failed:${checkpointKey}`);
            errors.push(`Checkpoint stat failed for '${checkpointKey}': ${headErr?.message || headErr}`);
          }
        }

        if (checkpointExists) {
          if (checkpointSizeBytes !== null && checkpointSizeBytes <= 0) {
            blockers.push(`checkpoint_object_empty:${checkpointKey}`);
            errors.push(`Checkpoint object '${checkpointKey}' is empty (0 bytes).`);
          } else {
            try {
              const rangeGetRes = await client.send(
                new GetObjectCommand({
                  Bucket: bucket,
                  Key: checkpointKey,
                  Range: 'bytes=0-20',
                }),
                { abortSignal: AbortSignal.timeout(6000) }
              );
              const sampleBytes = await bodyToBuffer(rangeGetRes?.Body);
              if (sampleBytes.length > 0) {
                checkpointAccessible = true;
                if (sampleBytes.length >= 17) {
                  headerMagicValid = sampleBytes.subarray(0, 17).toString('utf8') === 'ZYNTHEOR_QPLUS_PT';
                }
              } else {
                blockers.push(`checkpoint_not_accessible:${checkpointKey}`);
                errors.push(`Checkpoint '${checkpointKey}' returned 0 readable bytes.`);
              }
            } catch (getErr: any) {
              blockers.push(`checkpoint_not_accessible:${checkpointKey}`);
              errors.push(`Checkpoint '${checkpointKey}' is not readable/accessible: ${getErr?.message || getErr}`);
            }
          }
        }

        // 3. Optional Read/Write Probe (verifies training can persist checkpoint artifacts back to bucket)
        if (opts?.verifyReadWrite !== false) {
          const nonce = crypto.randomUUID();
          const probeKey = `.zyntheor-probes/preflight-rw-${nonce}.bin`;
          const probePayload = Buffer.from(
            JSON.stringify({ service: 'zyntheor-cloud-preflight', nonce, ts: new Date().toISOString() }),
            'utf8'
          );
          const expectedSha = crypto.createHash('sha256').update(probePayload).digest('hex');
          try {
            await client.send(
              new PutObjectCommand({
                Bucket: bucket,
                Key: probeKey,
                Body: probePayload,
                ContentType: 'application/octet-stream',
              }),
              { abortSignal: AbortSignal.timeout(6000) }
            );
            const getProbe = await client.send(
              new GetObjectCommand({ Bucket: bucket, Key: probeKey }),
              { abortSignal: AbortSignal.timeout(6000) }
            );
            const downloaded = await bodyToBuffer(getProbe?.Body);
            const actualSha = crypto.createHash('sha256').update(downloaded).digest('hex');
            readWriteVerified = actualSha === expectedSha && Buffer.compare(downloaded, probePayload) === 0;
            if (!readWriteVerified) {
              blockers.push('s3_rw_probe_sha256_mismatch');
              errors.push(`Bucket '${bucket}' R/W probe SHA-256 mismatch.`);
            }
          } catch (rwErr: any) {
            readWriteVerified = false;
            blockers.push('s3_rw_probe_failed');
            errors.push(`Bucket '${bucket}' read/write probe failed: ${rwErr?.message || rwErr}`);
          } finally {
            await client
              .send(new DeleteObjectCommand({ Bucket: bucket, Key: probeKey }), {
                abortSignal: AbortSignal.timeout(5000),
              })
              .catch(() => null);
          }
        }
      }

      const passed = Boolean(
        bucketAvailable &&
          checkpointExists &&
          checkpointAccessible &&
          (opts?.verifyReadWrite === false || readWriteVerified) &&
          blockers.length === 0
      );
      const latencyMs = Math.max(1, Date.now() - started);
      const errorMsg = errors.length > 0 ? errors.join(' | ') : null;

      if (!silent) {
        AuditLedger.append('SYSTEM', passed ? 'CLOUD_PREFLIGHT_VERIFIED' : 'CLOUD_PREFLIGHT_BLOCKED', {
          bucket,
          region,
          endpoint: validatedEndpoint || null,
          checkpointKey,
          passed,
          bucketAvailable,
          checkpointExists,
          checkpointAccessible,
          readWriteVerified,
          checkpointSizeBytes,
          headerMagicValid,
          blockers,
          latencyMs,
        });

        AuditLedger.emitWorkflowEvent({
          source: 'cloud_preflight',
          tag: passed ? 'INIT' : 'ERROR',
          isRunning: false,
          message: passed
            ? `Cloud Preflight PASSED (${latencyMs} ms): AWS S3 credentials valid, bucket '${bucket}' available, checkpoint '${checkpointKey}' accessible (${checkpointSizeBytes ?? '—'} bytes)`
            : `FAIL_CLOSED: Cloud Preflight blocked — ${errorMsg || blockers.join(', ')}`,
        });
      }

      return {
        passed,
        status: passed ? 'PREFLIGHT_PASS' : 'PREFLIGHT_BLOCKED',
        checks: {
          credentialsValid: true,
          bucketAvailable,
          checkpointExists,
          checkpointAccessible,
          readWriteVerified,
        },
        bucket,
        region,
        endpoint: validatedEndpoint || null,
        checkpointKey,
        checkpointSizeBytes,
        checkpointETag,
        checkpointLastModified,
        headerMagicValid,
        httpStatusCode,
        missingCredentials: [],
        blockers,
        error: errorMsg,
        latencyMs,
        checkedAt: new Date().toISOString(),
      };
    } finally {
      if (typeof client.destroy === 'function') {
        client.destroy();
      }
    }
  }
}

export async function runCloudPreflight(opts?: {
  objectKey?: string;
  verifyReadWrite?: boolean;
  overrides?: CloudStorageEndpointConfigInput;
  silent?: boolean;
}): Promise<CloudPreflightReport> {
  return CloudObjectStorageService.runCloudPreflight(opts);
}

/**
 * ZYNTHEOR Batch 29 — Cognitive Context Engine
 *
 * Unified context understanding & cross-session lifecycle system.
 * Strictly separates deterministic preprocessing (`attribution: 'deterministic_preprocessor'`)
 * from Native Model neural inference (`attribution: 'native_model_logits'`).
 *
 * Capabilities:
 *  - Context representation & structural segmentation (Thai/English/Code/Constraint/Question)
 *  - Intent recognition with matched evidence signals
 *  - Entity & candidate relationship extraction
 *  - Temporal context markers & freshness decay
 *  - Context prioritization & relevance scoring
 *  - Context conflict detection (numeric/directive/temporal contradictions)
 *  - Tenant- & owner-isolated cross-session context lifecycle in native_data/cognitive_context.json
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { AuditLedger } from './AuditLedger.ts';
import { detectLang, tokenize } from './KnowledgeIntelligenceEngine.ts';
import {
  classifyTruthClaim,
  enforceTruthClaims,
  summarizeTruthClaims,
  type TruthClaimRecord,
  type TruthKernelSummary,
} from './TruthKernel.ts';

export type ContextSegmentKind =
  | 'instruction'
  | 'constraint'
  | 'code'
  | 'question'
  | 'reference'
  | 'context_fact';

export type CognitiveIntent =
  | 'coding'
  | 'debugging'
  | 'math_reasoning'
  | 'knowledge_qa'
  | 'planning'
  | 'security_audit'
  | 'bilingual_translation'
  | 'general';

export interface ContextSegment {
  segmentId: string;
  index: number;
  kind: ContextSegmentKind;
  language: 'th' | 'en' | 'mixed';
  text: string;
  priority: number; // 1 (highest) .. 5
  relevanceScore: number;
  temporalHint?: string;
  tokenEstimate: number;
}

export interface ContextEntity {
  text: string;
  canonical: string;
  type: 'FILE_PATH' | 'API_ROUTE' | 'SYMBOL' | 'THAI_TERM' | 'NUMBER' | 'CONSTRAINT' | 'CONCEPT';
  segmentId: string;
}

export interface ContextRelationCandidate {
  subject: string;
  predicate: string;
  object: string;
  segmentId: string;
  confidence: number;
}

export interface ContextConflict {
  conflictId: string;
  segmentA: string;
  segmentB: string;
  kind: 'NUMERIC_MISMATCH' | 'DIRECTIVE_NEGATION' | 'TEMPORAL_SUPERSESSION';
  description: string;
  severity: 'low' | 'medium' | 'high';
}

export interface ContextAnalysisResult {
  contextId: string;
  analyzedAt: string;
  attribution: 'deterministic_preprocessor';
  nativeNeuralState: 'UNINVOKED' | 'READY' | 'BLOCKED';
  language: 'th' | 'en' | 'mixed';
  intent: {
    primary: CognitiveIntent;
    confidence: number;
    secondary: CognitiveIntent[];
    matchedSignals: string[];
  };
  segments: ContextSegment[];
  entities: ContextEntity[];
  relations: ContextRelationCandidate[];
  conflicts: ContextConflict[];
  temporalMarkers: string[];
  prioritizedOrder: string[];
  contentSha256: string;
  truthClaims: TruthClaimRecord[];
  truthSummary: TruthKernelSummary;
}

export interface ContextSessionWindow {
  sessionId: string;
  tenantId: string;
  ownerUserId: string;
  createdAt: string;
  updatedAt: string;
  expiresAt?: string;
  status: 'ACTIVE' | 'ARCHIVED' | 'EXPIRED';
  turns: Array<{
    turnId: string;
    timestamp: string;
    role: 'user' | 'system' | 'assistant';
    summary: string;
    intent: CognitiveIntent;
    entities: string[];
    contentSha256: string;
    priority: number;
  }>;
  pinnedFacts: Array<{
    factId: string;
    text: string;
    createdAt: string;
    priority: number;
    sourceTurnId?: string;
  }>;
}

export interface ContextScope {
  tenantId: string;
  userId: string;
  role?: string;
}

const INTENT_RULES: Array<{
  intent: CognitiveIntent;
  patterns: RegExp[];
  weight: number;
}> = [
  {
    intent: 'security_audit',
    patterns: [
      /\b(hmac|sha-?256|rbac|ssrf|tenant|isolation|tamper|audit|vulnerability|exploit|sanitize|auth|token)\b/i,
      /(ความปลอดภัย|สิทธิ์|ตรวจสอบบัญชี|แฮช|แยกผู้เช่า)/,
    ],
    weight: 1.25,
  },
  {
    intent: 'debugging',
    patterns: [
      /\b(bug|fix|error|exception|stack\s?trace|fail(ed|ing)?|broken|crash|repair|debug|regression)\b/i,
      /(แก้ไข|บั๊ก|ข้อผิดพลาด|พัง|ล้มเหลว|ซ่อมแซม)/,
    ],
    weight: 1.2,
  },
  {
    intent: 'math_reasoning',
    patterns: [
      /\b(calculate|compute|solve|equation|sum|product|budget|constraint|probability|perplexity|loss|math)\b/i,
      /[0-9]+\s*[\+\-\*\/]\s*[0-9]+/,
      /(คำนวณ|สมการ|คณิตศาสตร์|ความน่าจะเป็น|งบประมาณ)/,
    ],
    weight: 1.15,
  },
  {
    intent: 'planning',
    patterns: [
      /\b(plan|roadmap|dag|schedule|workflow|steps|decompose|milestones|architecture|design)\b/i,
      /(วางแผน|ขั้นตอน|สถาปัตยกรรม|ออกแบบ|จัดลำดับ)/,
    ],
    weight: 1.1,
  },
  {
    intent: 'coding',
    patterns: [
      /\b(build|create|implement|write|function|class|module|typescript|python|api|endpoint|test|compile)\b/i,
      /```[\s\S]*```/,
      /(สร้าง|เขียนโค้ด|ฟังก์ชัน|โปรแกรม|ทดสอบ|โมดูล)/,
    ],
    weight: 1.05,
  },
  {
    intent: 'bilingual_translation',
    patterns: [
      /\b(translate|bilingual|thai\s+to\s+english|english\s+to\s+thai)\b/i,
      /(แปลภาษา|สองภาษา|ภาษาไทย|ภาษาอังกฤษ)/,
    ],
    weight: 1.1,
  },
  {
    intent: 'knowledge_qa',
    patterns: [
      /\b(what|why|how|when|where|which|explain|summarize|compare|retrieve|citation|document|graph)\b/i,
      /(คืออะไร|อย่างไร|ทำไม|อธิบาย|สรุป|เปรียบเทียบ|เอกสาร|ความรู้)/,
    ],
    weight: 1.0,
  },
];

export class CognitiveContextEngine {
  private static instance: CognitiveContextEngine | null = null;
  private filePath: string;
  private sessions = new Map<string, ContextSessionWindow>();

  private constructor() {
    this.filePath = process.env.ZYNTHEOR_CONTEXT_FILE
      ? path.resolve(process.env.ZYNTHEOR_CONTEXT_FILE)
      : path.resolve(process.cwd(), 'native_data', 'cognitive_context.json');
    this.loadFromDisk();
  }

  public static getInstance(): CognitiveContextEngine {
    if (!CognitiveContextEngine.instance) {
      CognitiveContextEngine.instance = new CognitiveContextEngine();
    }
    return CognitiveContextEngine.instance;
  }

  private ensureDir(): void {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  }

  private loadFromDisk(): void {
    try {
      this.ensureDir();
      if (!fs.existsSync(this.filePath)) return;
      const parsed = JSON.parse(fs.readFileSync(this.filePath, 'utf8'));
      if (parsed && Array.isArray(parsed.sessions)) {
        for (const s of parsed.sessions) {
          if (s?.sessionId && s?.tenantId) {
            this.sessions.set(this.sessionKey(s.tenantId, s.sessionId), s);
          }
        }
      }
    } catch {
      this.sessions.clear();
    }
  }

  private persist(): void {
    this.ensureDir();
    const payload = {
      version: 'ZYNTHEOR_CONTEXT_V1',
      updatedAt: new Date().toISOString(),
      sessions: Array.from(this.sessions.values()).slice(0, 500),
    };
    const tmp = `${this.filePath}.tmp.${process.pid}`;
    fs.writeFileSync(tmp, JSON.stringify(payload, null, 2), 'utf8');
    fs.renameSync(tmp, this.filePath);
  }

  private sessionKey(tenantId: string, sessionId: string): string {
    return `${tenantId}::${sessionId}`;
  }

  public recognizeIntent(text: string): ContextAnalysisResult['intent'] {
    const trimmed = (text || '').trim();
    const scores = new Map<CognitiveIntent, number>();
    const signals: string[] = [];

    for (const rule of INTENT_RULES) {
      let hits = 0;
      for (const pat of rule.patterns) {
        const m = trimmed.match(pat);
        if (m) {
          hits += 1;
          signals.push(`${rule.intent}:${m[0].slice(0, 32)}`);
        }
      }
      if (hits > 0) {
        scores.set(rule.intent, Number((hits * rule.weight).toFixed(3)));
      }
    }

    if (scores.size === 0) {
      return {
        primary: 'general',
        confidence: trimmed.length > 0 ? 0.55 : 0.0,
        secondary: [],
        matchedSignals: [],
      };
    }

    const sorted = Array.from(scores.entries()).sort((a, b) => b[1] - a[1]);
    const topScore = sorted[0][1];
    const totalScore = sorted.reduce((acc, [, s]) => acc + s, 0);
    const confidence = Number(Math.min(0.98, Math.max(0.5, topScore / Math.max(1, totalScore) + 0.25)).toFixed(3));

    return {
      primary: sorted[0][0],
      confidence,
      secondary: sorted.slice(1, 3).map(([k]) => k),
      matchedSignals: signals.slice(0, 12),
    };
  }

  public segmentContext(rawInput: string, query?: string): ContextSegment[] {
    const clean = (rawInput || '').replace(/\r\n/g, '\n').trim();
    if (!clean) return [];

    // Split code fences cleanly while preserving paragraph / sentence lines
    const rawBlocks: string[] = [];
    const fenceRegex = /```[\s\S]*?```/g;
    let lastIdx = 0;
    let match: RegExpExecArray | null;
    while ((match = fenceRegex.exec(clean)) !== null) {
      const before = clean.slice(lastIdx, match.index).trim();
      if (before) {
        rawBlocks.push(...before.split(/\n+/).map((l) => l.trim()).filter(Boolean));
      }
      rawBlocks.push(match[0].trim());
      lastIdx = match.index + match[0].length;
    }
    const tail = clean.slice(lastIdx).trim();
    if (tail) {
      rawBlocks.push(...tail.split(/\n+/).map((l) => l.trim()).filter(Boolean));
    }

    const qTokens = new Set(tokenize(query || clean));
    const segments: ContextSegment[] = rawBlocks.map((block, idx) => {
      let kind: ContextSegmentKind = 'context_fact';
      let priority = 3;
      if (block.startsWith('```') || /\b(function|class|def|import|export|const)\b/.test(block)) {
        kind = 'code';
        priority = 2;
      } else if (/\b(must|never|always|required|strictly|constraint|limit|max|min|ห้าม|ต้อง|เงื่อนไข)\b/i.test(block)) {
        kind = 'constraint';
        priority = 1;
      } else if (block.endsWith('?') || /\b(what|why|how|when|where|which|explain|คืออะไร|อย่างไร|ทำไม)\b/i.test(block)) {
        kind = 'question';
        priority = 1;
      } else if (/\b(build|create|implement|verify|fix|run|analyze|สร้าง|แก้ไข|ตรวจสอบ|รัน)\b/i.test(block)) {
        kind = 'instruction';
        priority = 2;
      } else if (/^(\[|source:|ref:|http|\/[a-z0-9_.\-/]+)/i.test(block)) {
        kind = 'reference';
        priority = 3;
      }

      const bTokens = tokenize(block);
      let overlap = 0;
      for (const bt of bTokens) if (qTokens.has(bt)) overlap += 1;
      const priorityBoost = (6 - priority) * 0.25;
      const relevanceScore = Number(
        Math.min(1, (overlap / Math.max(1, Math.min(8, qTokens.size))) * 0.7 + priorityBoost * 0.3).toFixed(3)
      );

      const tempMatch = block.match(/\b(\d{4}-\d{2}-\d{2}|today|yesterday|now|latest|before|after|วันนี้|ล่าสุด|ก่อนหน้า)\b/i);

      return {
        segmentId: `seg_${idx + 1}`,
        index: idx,
        kind,
        language: detectLang(block),
        text: block,
        priority,
        relevanceScore,
        temporalHint: tempMatch ? tempMatch[0] : undefined,
        tokenEstimate: Math.max(1, Math.ceil(block.length / 3.8)),
      };
    });

    return segments;
  }

  public extractEntitiesAndRelations(segments: ContextSegment[]): {
    entities: ContextEntity[];
    relations: ContextRelationCandidate[];
    temporalMarkers: string[];
  } {
    const entities: ContextEntity[] = [];
    const relations: ContextRelationCandidate[] = [];
    const temporalSet = new Set<string>();
    const seenEnt = new Set<string>();

    const addEntity = (text: string, type: ContextEntity['type'], segmentId: string) => {
      const clean = text.trim();
      if (!clean || clean.length < 2) return;
      const canonical = clean.toLowerCase();
      const key = `${type}:${canonical}:${segmentId}`;
      if (seenEnt.has(key)) return;
      seenEnt.add(key);
      entities.push({ text: clean, canonical, type, segmentId });
    };

    for (const seg of segments) {
      if (seg.temporalHint) temporalSet.add(seg.temporalHint);

      for (const m of seg.text.matchAll(/\b(?:src|lib|qplus_native|tests|native_data)\/[A-Za-z0-9_.\-/]+\b/g)) {
        addEntity(m[0], 'FILE_PATH', seg.segmentId);
      }
      for (const m of seg.text.matchAll(/\/api\/[A-Za-z0-9_.\-\/:]+/g)) {
        addEntity(m[0], 'API_ROUTE', seg.segmentId);
      }
      for (const m of seg.text.matchAll(/\b[A-Z][A-Za-z0-9]{2,}(?:[A-Z][a-z0-9]+)+\b/g)) {
        addEntity(m[0], 'SYMBOL', seg.segmentId);
      }
      for (const m of seg.text.matchAll(/[\u0E00-\u0E7F]{3,}/g)) {
        addEntity(m[0], 'THAI_TERM', seg.segmentId);
      }
      for (const m of seg.text.matchAll(/\b\d+(?:\.\d+)?(?:ms|mb|gb|%|s)?\b/gi)) {
        addEntity(m[0], 'NUMBER', seg.segmentId);
      }
      if (seg.kind === 'constraint') {
        addEntity(seg.text.slice(0, 64), 'CONSTRAINT', seg.segmentId);
      }

      // Extract explicit SVO / definition relation patterns: "X uses Y", "X depends on Y", "X -> Y", "X คือ Y"
      const relPatterns: Array<{ re: RegExp; pred: string }> = [
        { re: /\b([A-Za-z0-9_.\-/]{3,40})\s+(?:uses|requires|depends on|calls|verifies|implements|contains)\s+([A-Za-z0-9_.\-/]{3,40})/gi, pred: 'DEPENDS_ON' },
        { re: /\b([A-Za-z0-9_.\-/]{3,40})\s+is\s+(?:a|an|the)?\s*([A-Za-z0-9_.\-/ ]{3,40}?)(?:[.,;]|$)/gi, pred: 'IS_A' },
        { re: /([A-Za-z0-9_\u0E00-\u0E7F]{2,32})\s*(?:->|→)\s*([A-Za-z0-9_\u0E00-\u0E7F]{2,32})/g, pred: 'FLOWS_TO' },
        { re: /([\u0E00-\u0E7FA-Za-z0-9_]{2,32})\s+คือ\s+([\u0E00-\u0E7FA-Za-z0-9_ ]{2,40})/g, pred: 'IS_A' },
      ];
      for (const { re, pred } of relPatterns) {
        for (const rm of seg.text.matchAll(re)) {
          const subj = rm[1].trim();
          const obj = rm[2].trim();
          if (subj && obj && subj.toLowerCase() !== obj.toLowerCase()) {
            relations.push({
              subject: subj,
              predicate: pred,
              object: obj,
              segmentId: seg.segmentId,
              confidence: 0.78,
            });
          }
        }
      }
    }

    return {
      entities: entities.slice(0, 120),
      relations: relations.slice(0, 60),
      temporalMarkers: Array.from(temporalSet),
    };
  }

  public detectContextConflicts(segments: ContextSegment[]): ContextConflict[] {
    const conflicts: ContextConflict[] = [];
    const negPairRe = [
      { pos: /\b(allow|enable|online|persist|include|อนุญาต|เปิดใช้|บันทึก)\b/i, neg: /\b(forbid|disable|offline|never|exclude|block|ห้าม|ปิด|ปฏิเสธ)\b/i },
      { pos: /\b(strict|required|must)\b/i, neg: /\b(optional|skip|ignore)\b/i },
    ];

    for (let i = 0; i < segments.length; i++) {
      for (let j = i + 1; j < segments.length; j++) {
        const a = segments[i];
        const b = segments[j];

        // Numeric mismatch on shared key constraint (e.g., max=10 vs max=50)
        const numA = a.text.match(/\b(port|limit|timeout|max|min|version|ขั้นตอน|พอร์ต)\s*[:=]?\s*(\d+(?:\.\d+)?)/i);
        const numB = b.text.match(/\b(port|limit|timeout|max|min|version|ขั้นตอน|พอร์ต)\s*[:=]?\s*(\d+(?:\.\d+)?)/i);
        if (numA && numB && numA[1].toLowerCase() === numB[1].toLowerCase() && numA[2] !== numB[2]) {
          conflicts.push({
            conflictId: `ctx_num_${i + 1}_${j + 1}`,
            segmentA: a.segmentId,
            segmentB: b.segmentId,
            kind: 'NUMERIC_MISMATCH',
            description: `Conflicting value for '${numA[1]}': ${numA[2]} (${a.segmentId}) vs ${numB[2]} (${b.segmentId}).`,
            severity: 'medium',
          });
        }

        const tokA = new Set(tokenize(a.text));
        const tokB = new Set(tokenize(b.text));
        let shared = 0;
        for (const t of tokA) if (tokB.has(t) && t.length > 3) shared += 1;
        if (shared < 2) continue;

        for (const pair of negPairRe) {
          if ((pair.pos.test(a.text) && pair.neg.test(b.text)) || (pair.neg.test(a.text) && pair.pos.test(b.text))) {
            conflicts.push({
              conflictId: `ctx_conf_${i + 1}_${j + 1}`,
              segmentA: a.segmentId,
              segmentB: b.segmentId,
              kind: 'DIRECTIVE_NEGATION',
              description: `Conflicting directive polarity over shared topic (${shared} shared terms) between ${a.segmentId} and ${b.segmentId}.`,
              severity: 'high',
            });
            break;
          }
        }
      }
    }

    return conflicts;
  }

  public analyzeContext(params: {
    input: string;
    query?: string;
    nativeNeuralState?: 'UNINVOKED' | 'READY' | 'BLOCKED';
  }): ContextAnalysisResult {
    const clean = (params.input || '').trim();
    const segments = this.segmentContext(clean, params.query);
    const intent = this.recognizeIntent(params.query || clean);
    const { entities, relations, temporalMarkers } = this.extractEntitiesAndRelations(segments);
    const conflicts = this.detectContextConflicts(segments);
    const prioritizedOrder = [...segments]
      .sort((a, b) => a.priority - b.priority || b.relevanceScore - a.relevanceScore)
      .map((s) => s.segmentId);

    const contentSha256 = crypto.createHash('sha256').update(clean).digest('hex');
    const neuralState = params.nativeNeuralState ?? 'UNINVOKED';

    const rawClaims: TruthClaimRecord[] = [
      classifyTruthClaim({
        domain: 'cognitive_context',
        statement: `Input segmented into ${segments.length} structural unit(s) with ${entities.length} extracted entity reference(s)`,
        classification: 'VERIFIED_FACT',
        basis: `Deterministic tokenizer/regex segmentation (SHA-256 ${contentSha256.slice(0, 12)})`,
        evidenceRefs: [contentSha256],
      }),
      classifyTruthClaim({
        domain: 'cognitive_context',
        statement: `Primary intent classified as '${intent.primary}' (heuristic confidence ${intent.confidence})`,
        classification: 'ASSUMPTION',
        basis: 'Lexical pattern match heuristic (not calibrated neural probability)',
        evidenceRefs: intent.matchedSignals,
      }),
      classifyTruthClaim({
        domain: 'cognitive_context',
        statement:
          neuralState === 'READY'
            ? 'Context paired with active Native Model runtime'
            : `Native Model contextual embedding is not active (${neuralState})`,
        classification: neuralState === 'READY' ? 'VERIFIED_FACT' : 'UNVERIFIED',
        basis: `Reported nativeNeuralState=${neuralState}`,
      }),
    ];

    if (conflicts.length > 0) {
      rawClaims.push(
        classifyTruthClaim({
          domain: 'cognitive_context',
          statement: `Detected ${conflicts.length} internal context conflict(s): ${conflicts.map((c) => c.kind).join(', ')}`,
          classification: 'CONTRADICTED',
          basis: 'Deterministic numeric/directive negation detector across context segments',
          evidenceRefs: conflicts.map((c) => c.conflictId),
        })
      );
    }

    const truthClaims = enforceTruthClaims(rawClaims);
    const truthSummary = summarizeTruthClaims(truthClaims);

    return {
      contextId: `ctx_${Date.now()}_${crypto.randomBytes(3).toString('hex')}`,
      analyzedAt: new Date().toISOString(),
      attribution: 'deterministic_preprocessor',
      nativeNeuralState: neuralState,
      language: detectLang(clean),
      intent,
      segments,
      entities,
      relations,
      conflicts,
      temporalMarkers,
      prioritizedOrder,
      contentSha256,
      truthClaims,
      truthSummary,
    };
  }

  /**
   * Cross-session context lifecycle management (strictly tenant + owner scoped).
   */
  public upsertSessionTurn(params: {
    sessionId: string;
    role: 'user' | 'system' | 'assistant';
    text: string;
    scope: ContextScope;
    ttlSeconds?: number;
    pinAsFact?: boolean;
  }): { session: ContextSessionWindow; analysis: ContextAnalysisResult } {
    if (!params.scope.tenantId || !params.scope.userId) {
      throw new Error('VERIFIED_CONTEXT_SCOPE_REQUIRED');
    }
    const key = this.sessionKey(params.scope.tenantId, params.sessionId);
    const existing = this.sessions.get(key);
    if (!existing) {
      for (const s of this.sessions.values()) {
        if (s.sessionId === params.sessionId && s.tenantId !== params.scope.tenantId) {
          AuditLedger.append('SYSTEM', 'CONTEXT_CROSS_TENANT_WRITE_BLOCKED', {
            sessionId: params.sessionId,
            callerTenant: params.scope.tenantId,
            ownerTenant: s.tenantId,
          });
          throw new Error('FORBIDDEN: Cross-tenant context session write denied');
        }
      }
    }
    if (existing && existing.ownerUserId !== params.scope.userId && params.scope.role !== 'admin') {
      AuditLedger.append('SYSTEM', 'CONTEXT_CROSS_USER_ACCESS_BLOCKED', {
        sessionId: params.sessionId,
        tenantId: params.scope.tenantId,
        callerUserId: params.scope.userId,
      });
      throw new Error('FORBIDDEN: Cross-owner context session access denied');
    }

    const analysis = this.analyzeContext({ input: params.text });
    const now = new Date().toISOString();
    const expiresAt =
      typeof params.ttlSeconds === 'number' && params.ttlSeconds > 0
        ? new Date(Date.now() + params.ttlSeconds * 1000).toISOString()
        : existing?.expiresAt;

    const win: ContextSessionWindow = existing || {
      sessionId: params.sessionId,
      tenantId: params.scope.tenantId,
      ownerUserId: params.scope.userId,
      createdAt: now,
      updatedAt: now,
      expiresAt,
      status: 'ACTIVE',
      turns: [],
      pinnedFacts: [],
    };

    const turnId = `turn_${Date.now()}_${crypto.randomBytes(2).toString('hex')}`;
    win.updatedAt = now;
    if (expiresAt) win.expiresAt = expiresAt;
    win.status = 'ACTIVE';
    win.turns.push({
      turnId,
      timestamp: now,
      role: params.role,
      summary: params.text.trim().slice(0, 500),
      intent: analysis.intent.primary,
      entities: analysis.entities.slice(0, 12).map((e) => e.text),
      contentSha256: analysis.contentSha256,
      priority: analysis.segments[0]?.priority ?? 3,
    });
    if (win.turns.length > 50) {
      win.turns = win.turns.slice(-50);
    }

    if (params.pinAsFact) {
      win.pinnedFacts.push({
        factId: `fact_${Date.now()}_${crypto.randomBytes(2).toString('hex')}`,
        text: params.text.trim().slice(0, 320),
        createdAt: now,
        priority: 1,
        sourceTurnId: turnId,
      });
      if (win.pinnedFacts.length > 30) {
        win.pinnedFacts = win.pinnedFacts.slice(-30);
      }
    }

    this.sessions.set(key, win);
    this.persist();

    AuditLedger.append('SYSTEM', 'COGNITIVE_CONTEXT_UPDATED', {
      sessionId: params.sessionId,
      tenantId: params.scope.tenantId,
      intent: analysis.intent.primary,
      segmentsCount: analysis.segments.length,
      conflictsCount: analysis.conflicts.length,
    });

    return { session: win, analysis };
  }

  public getSessionContext(sessionId: string, scope: ContextScope): ContextSessionWindow | null {
    this.purgeExpiredSessions();
    // Enforce tenant isolation: never return another tenant's session even if sessionId matches
    const key = this.sessionKey(scope.tenantId, sessionId);
    const win = this.sessions.get(key);
    if (!win) {
      // Check if session exists under another tenant to log attempted leakage probe
      for (const s of this.sessions.values()) {
        if (s.sessionId === sessionId && s.tenantId !== scope.tenantId) {
          AuditLedger.append('SYSTEM', 'CONTEXT_CROSS_TENANT_READ_BLOCKED', {
            sessionId,
            callerTenant: scope.tenantId,
            ownerTenant: s.tenantId,
          });
          throw new Error('FORBIDDEN: Cross-tenant cognitive context access denied');
        }
      }
      return null;
    }
    if (win.ownerUserId !== scope.userId && scope.role !== 'admin') {
      throw new Error('FORBIDDEN: Cross-owner cognitive context access denied');
    }
    return win;
  }

  public listSessions(scope: ContextScope): ContextSessionWindow[] {
    this.purgeExpiredSessions();
    return Array.from(this.sessions.values())
      .filter(
        (s) =>
          s.tenantId === scope.tenantId &&
          (scope.role === 'admin' || s.ownerUserId === scope.userId)
      )
      .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : -1));
  }

  public archiveSession(sessionId: string, scope: ContextScope): ContextSessionWindow | null {
    const win = this.getSessionContext(sessionId, scope);
    if (!win) return null;
    win.status = 'ARCHIVED';
    win.updatedAt = new Date().toISOString();
    this.sessions.set(this.sessionKey(scope.tenantId, sessionId), win);
    this.persist();
    return win;
  }

  public deleteSession(sessionId: string, scope: ContextScope): boolean {
    const win = this.getSessionContext(sessionId, scope);
    if (!win) return false;
    this.sessions.delete(this.sessionKey(scope.tenantId, sessionId));
    this.persist();
    return true;
  }

  public purgeExpiredSessions(): number {
    const now = Date.now();
    let count = 0;
    for (const [k, s] of this.sessions.entries()) {
      if (s.expiresAt && Number.isFinite(Date.parse(s.expiresAt)) && Date.parse(s.expiresAt) <= now) {
        this.sessions.delete(k);
        count += 1;
      }
    }
    if (count > 0) this.persist();
    return count;
  }

  public getSummaryStats(scope?: Partial<ContextScope>) {
    this.purgeExpiredSessions();
    const visible = Array.from(this.sessions.values()).filter(
      (s) => !scope?.tenantId || s.tenantId === scope.tenantId
    );
    const totalTurns = visible.reduce((acc, s) => acc + s.turns.length, 0);
    const activeCount = visible.filter((s) => s.status === 'ACTIVE').length;
    return {
      totalSessions: visible.length,
      activeSessions: activeCount,
      archivedSessions: visible.filter((s) => s.status === 'ARCHIVED').length,
      totalTurns,
      pinnedFactsCount: visible.reduce((acc, s) => acc + s.pinnedFacts.length, 0),
    };
  }
}

/**
 * ZYNTHEOR Sovereign Knowledge Intelligence Engine
 * Production-oriented extensions on top of KnowledgeWorkspace:
 * - Multi-format parsing (text-level; binary PDF/DOCX require external tools — reported honestly)
 * - Semantic-ish chunking, deduplication, versioning helpers
 * - Hybrid lexical + bag-of-words vector retrieval with simple reranking
 * - Entity extraction, co-occurrence graph edges, contradiction heuristics
 * - Grounded citations with provenance + content hashes
 * - Ingestion job records (resumable metadata on disk)
 *
 * NEVER equates indexed documents with learned model weights.
 */

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { AuditLedger } from './AuditLedger';
import {
  KnowledgeWorkspace,
  KnowledgeDocument,
  KnowledgeChunk,
  RetrievalResult
} from './KnowledgeWorkspace';
import { detectLang as detectLangUtil, semanticChunk as semanticChunkUtil } from './knowledgeUtils';

// Re-export types that may not all be exported — use structural typing
export type DocFormat =
  | 'markdown'
  | 'txt'
  | 'json'
  | 'csv'
  | 'pdf'
  | 'docx'
  | 'code'
  | 'html'
  | 'xml';

