        label: 'Video & Temporal Scene Understanding',
        status: videoCap.status,
        supportedFormats: [],
        missingDependencies: ['native_video_decoder', 'frame_sampler', 'native_vision_encoder', 'temporal_fusion_model'],
        notes: videoCap.reason,
      },
      {
