export type RuntimeLifecycleState =
  | 'NOT_CONFIGURED'
  | 'NOT_LOADED'
  | 'NOT_FOUND'
  | 'INITIALIZING'
  | 'LOADING'
  | 'READY'
  | 'FAILED'
  | 'BLOCKED';

export type BridgeLifecycleState =
  | 'Connecting'
  | 'Connected'
  | 'Degraded'
  | 'Reconnecting'
  | 'Session Timeout'
  | 'Initialization Error'
  | 'Service Error'
  | 'Unreachable';

export type BridgeFailureCategory =
  | 'none'
  | 'session_timeout'
  | 'initialization_error'
  | 'unreachable';

